INSERT INTO `tpl_template` (`id`,`tenant_id`,`group_id`,`source_id`,`code`,`name`,`category`,`archive_code`,`archive_item`,`box_no`,`post_scope`,`content`,`need_seal`,`version`,`version_label`,`status`,`created_by`) VALUES
(4200,0,4001,0,'ZD01','安全生产责任制','制度','BOX2','安全生产责任制',2,'','<div class="doc-no">制度编号：YT-ZD01</div>\n<div class="doc-p">安全生产责任制</div>\n<div class="doc-h1">1.总则</div>\n<div class="doc-p">为了进一步贯彻落实“安全第一、预防为主、综合治理”的基本方针，明确公司各级领导、各岗位人员的安全生产工作职责及责任关系，强化“管生产必须管安全”、“谁主管谁负责”的安全理念，突出安全生产的关键是落实安全生产责任制，依据《中华人民共和国安全生产法》、《中华人民共和国道路运输条例》的要求，保障公司安全生产工作持续、稳定发展，结合公司实际，特制定本制度。</div>\n<div class="doc-h1">2.适用范围</div>\n<div class="doc-p">本公司管理层、各部门、各岗位全体员工以及相关方公司的人员安全生产。</div>\n<div class="doc-h1">3.制定原则</div>\n<div class="doc-p">企业总经理是本公司的安全生产第一责任人,按照“谁主管、谁负责”，“管生产必须管安全”的原则，各级管理人员和职能部门在各自的工作范围内，对公司、营运、各岗位的安全生产负责。公司员工履行各自的安全职责,实现全员安全生产责任制。</div>\n<div class="doc-h1">4.安全生产目标</div>\n<div class="doc-h2">4.1目标设定</div>\n<div class="doc-p">公司以“坚决杜绝重特大事故，遏制较大事故，不发生一般及以上生产安全责任事故，开展双重预防机制建设，完善风险分级管控和隐患排查治理，全面落实企业安全生产主体责任”为安全生产目标，包括运输责任事故控制目标和运输安全管理工作目标。</div>\n<div class="doc-h2">4.2岗位目标分解</div>\n<div class="doc-h3">4.2.1总经理</div>\n<div class="doc-li">1、责任事故控制指标</div>\n<div class="doc-li">（1）发生一般以上生产安全责任事故0宗；</div>\n<div class="doc-li">（2）百万车公里行车责任事故频率≤3宗；</div>\n<div class="doc-li">（3）百万车公里行车责任事故死亡率≤0人；</div>\n<div class="doc-li">（4）百万车公里行车责任事故重伤率≤0人；</div>\n<div class="doc-li">（5）百万车公里行车责任事故经损率≤3.5万元；</div>\n<div class="doc-li">（6）不发生火灾事故；</div>\n<div class="doc-li">2、运输安全管理工作指标</div>\n<div class="doc-li">（1）职业病防护率 100%；</div>\n<div class="doc-li">（2）车辆卫星定位装置安装率 100%；</div>\n<div class="doc-li">（3）安全管理人员持证上岗率 100%；</div>\n<div class="doc-li">（4）从业人员持证上岗率 100%；</div>\n<div class="doc-li">（5）培训考核合格率 100%；</div>\n<div class="doc-li">（6）隐患排查治理率 100%；</div>\n<div class="doc-li">（7）事故治理及整改率 100%；</div>\n<div class="doc-li">（8）车辆年检率 100%；</div>\n<div class="doc-li">（9）车辆二级维护率 100%；</div>\n<div class="doc-li">（10）安全生产经费投入100%；</div>\n<div class="doc-li">（11）组织开展至少3次应急演练。</div>\n<div class="doc-h3">4.2.2安全员</div>\n<div class="doc-li">1、责任事故控制指标</div>\n<div class="doc-li">（1）发生一般及以上生产安全责任事故0宗；</div>\n<div class="doc-li">（2）百万车公里行车责任事故频率≤3宗；</div>\n<div class="doc-li">（3）百万车公里行车责任事故死亡率≤0人；</div>\n<div class="doc-li">（4）百万车公里行车责任事故重伤率≤0人；</div>\n<div class="doc-li">（5）百万车公里行车责任事故经损率≤3.5万元；</div>\n<div class="doc-li">（6）不发生火灾事故、爆炸、泄漏事故；</div>\n<div class="doc-li">2、运输安全管理工作指标</div>\n<div class="doc-li">（1）职业病防护率100%；</div>\n<div class="doc-li">（2）培训考核合格率100%；</div>\n<div class="doc-li">（3）安全管理人员持证上岗率100%；</div>\n<div class="doc-li">（4）从业人员持证上岗率100%；</div>\n<div class="doc-li">（5）隐患排查治理率100%；</div>\n<div class="doc-li">（6）事故治理及整改率100%；</div>\n<div class="doc-li">（7）组织并参与3次应急演练。</div>\n<div class="doc-h3">4.2.3车队长</div>\n<div class="doc-li">1、责任事故控制指标</div>\n<div class="doc-li">（1）发生一般及以上生产安全责任事故0宗；</div>\n<div class="doc-li">（2）百万车公里行车责任事故频率≤3宗；</div>\n<div class="doc-li">（3）百万车公里行车责任事故死亡率≤0人；</div>\n<div class="doc-li">（4）百万车公里行车责任事故重伤率≤0人；</div>\n<div class="doc-li">（5）百万车公里行车责任事故经损率≤3.5万元；</div>\n<div class="doc-li">（6）不发生火灾事故、爆炸、泄漏事故；</div>\n<div class="doc-li">2、运输安全管理工作指标</div>\n<div class="doc-li">（1）职业病防护率100%；</div>\n<div class="doc-li">（2）隐患排查治理率100%；</div>\n<div class="doc-li">（3）卫星定位装置安装率100%；</div>\n<div class="doc-li">（4）事故治理及整改率100%；</div>\n<div class="doc-li">（5）培训考核合格率100%；</div>\n<div class="doc-li">（6）车辆二级维护率100%；</div>\n<div class="doc-li">（7）车辆年检率100%；</div>\n<div class="doc-li">（8）应急预案演练参与率100%。</div>\n<div class="doc-h3">4.2.4驾驶员</div>\n<div class="doc-li">1、责任事故控制指标</div>\n<div class="doc-li">（1）发生一般及以上生产安全责任事故0宗；</div>\n<div class="doc-li">（2）百万车公里行车责任事故频率≤3宗；</div>\n<div class="doc-li">（3）百万车公里行车责任事故死亡率≤0人；</div>\n<div class="doc-li">（4）百万车公里行车责任事故重伤率≤0人；</div>\n<div class="doc-li">（5）百万车公里行车责任事故经损率≤3.5万元；</div>\n<div class="doc-li">（6）不发生火灾事故、爆炸、泄漏事故；</div>\n<div class="doc-li">2、运输安全管理工作指标</div>\n<div class="doc-li">（1）职业病防护率100%；</div>\n<div class="doc-li">（2）隐患排查治理率100%；</div>\n<div class="doc-li">（3）卫星定位装置安装率100%；</div>\n<div class="doc-li">（4）事故治理及整改率100%；</div>\n<div class="doc-li">（5）培训考核合格率100%；</div>\n<div class="doc-li">（6）车辆二级维护率100%；</div>\n<div class="doc-li">（7）车辆年检率100%；</div>\n<div class="doc-li">（8）应急预案演练参与率100%。</div>\n<div class="doc-h3">4.2.5监控员</div>\n<div class="doc-li">1、责任事故控制指标</div>\n<div class="doc-p">不发生火灾事故；</div>\n<div class="doc-li">2、运输安全管理工作指标</div>\n<div class="doc-li">（1）职业病防护率100%；</div>\n<div class="doc-li">（2）隐患排查治理率100%；</div>\n<div class="doc-li">（3）卫星定位装置安装率100%；</div>\n<div class="doc-li">（4）培训考核合格率100%；</div>\n<div class="doc-li">（5）应急预案演练参与率100%。</div>\n<div class="doc-h2">4.3目标执行</div>\n<div class="doc-h3">4.3.1认真贯彻执行《中华人民共和国安全生产法》、《中华人民共和国道路交通安全法》、《中华人民共和国道路运输条例》等法律法规，做到依法管理，不断完善安全管理规章制度。</div>\n<div class="doc-h3">4.3.2推行安全系统化管理，实现安全管理标准化、制度化，将安全管理与设备设施管理、现场管理、运输车辆管理有效结合起来。</div>\n<div class="doc-h3">4.3.3夯实安全管理基础工作，切实抓好安全物防、技防、人防工作。一是要结合运营流程和货物运输安全要求，积极推广应用安全防护新设备、新技术，提高本质安全化水平；二是结合我公司实际，强化设备设施安全运行的检查和维护；三是推进运输管理工作，做到经营有序、设施有效、安全可靠。</div>\n<div class="doc-h3">4.3.4持续开展全员安全教育和培训，努力提高全员安全素质。一是加强管理者的责任心教育和安全技术教育，提高安全管理的预见性和预防事故的能力；二是坚持做好新入公司员工、临时工、转岗、复工人员的安全教育工作；三是定期做好员工的安全教育培训，使他们掌握国家的政策、法规，以及公司的管理制度和安全生产操作规程，并应用于实际工作中。</div>\n<div class="doc-h3">4.3.5加强交通、消防的安全管理，强化日常安全检查，加大隐患排查治理力度，及时发现、消除事故隐患，防止事故发生。</div>\n<div class="doc-h3">4.3.6组织开展事故应急预案的评审和演练工作，进一步完善事故应急预案，增强应急预案的针对性和可操作性，避免或减少事故损失。</div>\n<div class="doc-h3">4.3.7加强职业卫生管理，防止和减少职业危害，为员工创造良好、健康的工作环境。</div>\n<div class="doc-h3">4.3.8抓好车辆运输安全管理工作，提高安全管理水平。</div>\n<div class="doc-h2">4.4目标监督检查</div>\n<div class="doc-p">安全生产领导机构根据公司制定的安全生产目标（即：运输责任事故控制目标和运输安全管理工作目标），对照公司各岗位目标分解结果，定期对各岗位安全生产责任安全生产目标达成情况进行监督、检查，并将检查结果应用于公司安全生产责任考核之中。</div>\n<div class="doc-h1">5.安全生产管理机构</div>\n<div class="doc-h2">5.1安全生产领导机构</div>\n<div class="doc-p">安全生产领导机构由本公司总经理及各部门级以上负责人等组成，领导开展本公司的安全生产管理工作；安全生产领导机构办公室的日常工作由安全员负责。</div>\n<div class="doc-h3">5.1.1安全生产领导机构的主要职责</div>\n<div class="doc-li">（1）组织制定并审核本公司全员安全生产责任制，加强安全生产标准化建设；</div>\n<div class="doc-li">（2）组织制定并审核本公司安全生产规章制度、操作规程和生产安全事故应急救援预案，并监督落实；</div>\n<div class="doc-li">（3）组织制定并审核本公司安全生产教育和培训计划，并监督落实；</div>\n<div class="doc-li">（4）定期召开安全生产领导机构名称会议，听取各部门安全生产工作汇报，研究解决安全生产运行中的相关问题；</div>\n<div class="doc-li">（5）组织建立并审核安全风险分级管控和隐患排查治理双重预防工作机制，督促、检查本单位的安全生产工作，并监督工作开展情况；</div>\n<div class="doc-li">（6）组织开展危险源辨识和评估，督促落实本单位重大危险源的安全管理措施；</div>\n<div class="doc-li">（7）督促落实本公司安全生产整改措施；</div>\n<div class="doc-li">（8）督促各部门及工作人员履行安全生产职责，组织安全生产考核，提出奖惩意见建议；</div>\n<div class="doc-li">（9）组织开展公司事故调查、处置及事故责任追究等工作；</div>\n<div class="doc-li">（10）督促落实本单位安全生产整改措施；</div>\n<div class="doc-li">（11）法律、法规规定的其他安全生产职责。</div>\n<div class="doc-h3">5.1.2安全生产领导机构办公室的主要职责</div>\n<div class="doc-li">（1）认真学习、贯彻国家和交通主管部门关于安全管理的方针、政策、法律、法规，在公司安全生产领导机构的领导下，负责安全生产领导机构日常工作；</div>\n<div class="doc-li">（2）及时接收国家和主管部门有关安全的文件，及时向安全生产领导机构汇报，根据安全生产领导机构决定，起草公司安全生产领导机构的文件，并及时传达和落实；</div>\n<div class="doc-li">（3）掌握公司安全生产和安全管理等工作的动态，及时向安全生产领导机构汇报，并提出合理化建议；</div>\n<div class="doc-li">（4）汇总分析各部门有关安全隐患和建议，及时向安全生产领导机构汇报；</div>\n<div class="doc-li">（5）组织安全生产领导机构成员进行法律法规、制度的学习，开展风险分级管控和隐患排查治理，应急演练，定期开展安全生产大检查，针对检查问题和隐患，督促组织相关责任部门及时整改；</div>\n<div class="doc-li">（6）筹备公司安全生产领导机构例会和安全工作会议，做好会务工作，并对决定的事项予以督办。</div>\n<div class="doc-li">（7）认真做好安全生产领导机构议记录，完成和传达会议纪要；</div>\n<div class="doc-li">（8）完成安全生产领导机构交办的其它工作</div>\n<div class="doc-h2">5.2各岗位安全职责</div>\n<div class="doc-h3">5.2.1总经理</div>\n<div class="doc-li">（1）贯彻执行国家安全生产方针、政策和有关安全生产法律、法规、规章及技术标准等；</div>\n<div class="doc-li">（2）建立健全并落实本公司全员安全生产责任制，加强安全生产标准化建设；</div>\n<div class="doc-li">（3）组织制定并实施本公司安全生产规章制度和操作规程；</div>\n<div class="doc-li">（4）确定符合条件的安全生产分管负责人，依法设置安全生产管理机构或配备专职安全生产管理人员；</div>\n<div class="doc-li">（5）组织制定并实施本公司安全生产教育和培训计划；</div>\n<div class="doc-li">（6）保证本公司安全生产投入的有效实施；</div>\n<div class="doc-li">（7）组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制；</div>\n<div class="doc-li">（8）督促、检查本公司的安全生产工作，每半年至少组织一次安全生产全面检查，研究分析安全生产存在问题，督促安全风险分级管控、隐患排查和整改措施的落实，对从业人员上报的隐患及时予以处理，及时消除生产安全事故隐患；</div>\n<div class="doc-li">（9）每季度召开一次安全生产专题会议，研究和审查公司有关安全生产的重大事项，协调本公司各相关机构安全生产工作事宜；</div>\n<div class="doc-li">（10）定期研究安全生产工作，每年向职工大会或者职工代表大会或者股东大会报告安全生产情况，接受工会、从业人员、股东对安全生产工作的监督；</div>\n<div class="doc-li">（11）组织制定并实施本公司的生产安全事故应急救援预案，成立应急救援队伍，配备应急救援物资，每年至少组织和参与一次应急救援演练；</div>\n<div class="doc-li">（12）建立、健全本公司的公司负责人现场带班制度，并按规定组织实施24小时应急值班管理；</div>\n<div class="doc-li">（13）及时、如实报告生产安全事故，发生事故时迅速组织抢险救援，并及时、如实向应急管理部门和其他负有安全生产监督管理职责的部门报告事故情况，做好善后处理工作，配合调查处理；</div>\n<div class="doc-li">（14）组织做好公司传染病疫情防控工作；</div>\n<div class="doc-li">（15）组织相关方安全管理工作，签订安全生产管理协议；</div>\n<div class="doc-li">（16）提供符合安全生产和职业健康标准的条件；</div>\n<div class="doc-li">（17）法律、法规、规章、规范、标准规定的其他安全生产管理职责。</div>\n<div class="doc-h3">5.2.2安全员</div>\n<div class="doc-li">（1）负责公司安全生产工作日常管理工作，贯彻落实公司有关安全生产决定和管理措施。</div>\n<div class="doc-li">（2）组织或者参与拟订本单位安全生产规章制度、操作规程和生产安全事故应急救援预案、安全生产计划及安全措施等；</div>\n<div class="doc-li">（3）组织或者参与本单位安全生产教育和培训，如实记录安全生产教育和培训情况；</div>\n<div class="doc-li">（4）组织开展安全风险和危险源辨识、评估，督促落实本单位安全风险分级管控和重大危险源安全管理措施；</div>\n<div class="doc-li">（5）组织或者参与本单位应急救援演练；</div>\n<div class="doc-li">（6）组织安全生产岗位检查、日常安全检查和专业性安全检查，每月至少组织一次安全生产全面检查，并对从业人员上报的隐患及时予以处理，及时排查生产安全事故隐患，提出改进安全生产管理的建议；</div>\n<div class="doc-li">（7）制止和纠正违章指挥、强令冒险作业、违反操作规程的行为；</div>\n<div class="doc-li">（8）督促本单位履行安全生产职责、落实安全生产整改措施，组织安全生产考核；</div>\n<div class="doc-li">（9）协助组织召开安全生产工作会议，汇报安全生产工作开展情况，综合分析公司安全生产和安全运输中的突出问题，提出工作要求及工作建议，如实记录相关会议情况；</div>\n<div class="doc-li">（10）协助组织开展安全文化建设及安全生产活动，做好文化建设及活动开展情况的记录；</div>\n<div class="doc-li">（11）监督本公司安全生产资金投入和技术措施的落实；</div>\n<div class="doc-li">（12）组织劳动防护用品及应急救援物资的购置及使用管理工作，并监督教育从业人员按规定使用；</div>\n<div class="doc-li">（13）协助组织事故抢险救援工作，做好现场协调处置、调查、报告及善后处理工作，配合政府部门事故调查处理或协助组织开展公司内部事故调查处理工作，提出处理建议；</div>\n<div class="doc-li">（14）落实公司的职业健康管理工作；</div>\n<div class="doc-li">（15）负责安全生产统计与安全生产管理档案建立；</div>\n<div class="doc-li">（16）法律、法规、规章、规范、标准规定的其他安全生产管理职责。</div>\n<div class="doc-h3">5.2.3车队长</div>\n<div class="doc-h1">1.严格遵守国家及地方的法律法规及标准和公司各项制度、规程；</div>\n<div class="doc-h1">2.负责车队车辆及驾驶员的日常安全生产管理工作；</div>\n<div class="doc-h1">3.负责车队驾驶员进行日常安全思想、安全行车及安全技术知识教育工作，</div>\n<div class="doc-h1">4.组织开展车队安全生产检查工作，制止各类违法违规行为，监督并落实安全生产整改措施；</div>\n<div class="doc-h1">5.负责开展车队营运车辆、安全防护装备、及应急救援器材等检查工作，确保处于完好状态；</div>\n<div class="doc-h1">6.检查督促驾驶员做好车辆日常维护及保养工作，随时掌握车辆技术状况，确保车辆技术状况良好；</div>\n<div class="doc-h1">7.发生车辆交通事故时，及时组织事故救援、应急处置及事故上报；</div>\n<div class="doc-h1">8.负责组织所辖车辆检验检测、车辆及驾驶员的证件审验、换发等工作；</div>\n<div class="doc-h1">9.负责对卫星定位监控平台使用及监控信息登记，建立动态监控台账，并归档管理；</div>\n<div class="doc-h1">10.监督卫星定位监控平台及车载设备使用情况，组织协调解决硬件、软件方面在使用中出现的问题，确保监控工作正常开展；</div>\n<div class="doc-h1">11.组织开展驾驶员（车辆）违法违规行为分析，提出普遍问题和重点问题的改进建议；</div>\n<div class="doc-h1">12.负责对驾驶员违法违规行为的监督提醒工作，对经提醒仍然继续违法驾驶的驾驶员，应当及时报告安全管理人员；</div>\n<div class="doc-h1">13.每月对公司动态监控工作开展情况进行全面的总结分析，形成书面材料报告公司主要负责人，并在公司安全生产工作例会上进行专题汇报；</div>\n<div class="doc-h1">14.配合开展事故调查处理工作；</div>\n<div class="doc-h1">15.法律、法规、规章、规范、标准规定的其他安全生产管理职责。</div>\n<div class="doc-h1">16.严格组织落实部门安全生产责任职责；</div>\n<div class="doc-h1">17.参与拟订本公司安全生产规章制度、操作规程，并严格执行；</div>\n<div class="doc-h1">18.组织制定、提出部门安全生产教育和培训计划及需求，根据公司安全生产教育和培训管理要求，严格落实并如实记录；</div>\n<div class="doc-h1">19.落实部门安全风险分级管控和隐患排查治理措施，定期检查分管部门的安全生产状况，及时排查生产安全事故隐患，提出改进安全生产管理的建议，对分管部门安全生产整改措施进行督促落实；</div>\n<div class="doc-h1">20.按职责权限协助并参与事故应急预案编制和应急演练工作，发生事故时，协助负责人组织事故抢险救援，配合保障事故救援工作高效、有序进行，最大限度地减少人员伤亡和财产损失；</div>\n<div class="doc-h1">21.制止和纠正违章指挥、强令冒险作业、违反操作规程的行为；</div>\n<div class="doc-h1">22.落实事故防范、风险监控和职业危害防治措施，全力防范本公司安全生产事故，遏止较大安全生产事故，杜绝重特大安全生产事故；</div>\n<div class="doc-h1">23.掌握公司生产经营活动的各个环节，沟通、协调各车队的营运业务，对出现的问题提出改进措施并组织落实；</div>\n<div class="doc-h1">24.负责制订、落实营运车辆的报废更新方案和实施计划，办理车辆报废更新相关报批手续；</div>\n<div class="doc-h1">25.负责司机营运违章和投诉处理，负责营运数据统计和信息采集、传送；</div>\n<div class="doc-h1">26.负责公司车辆技术管理工作，履行车辆技术管理职责；</div>\n<div class="doc-h1">27.严格执行相关车辆技术法律、法规和国家标准、行业标准；</div>\n<div class="doc-h1">28.组织实施上级有关车辆技术管理政策，落实各项车辆技术管理制度；</div>\n<div class="doc-h1">29.组织部门人员参加安全学习及安全培训,掌握车辆技术管理工作所需的安全生产知识，提高安全生产技能；</div>\n<div class="doc-h1">30.负责组织车辆维护、保养、检测、维修等车辆技术管理工作；</div>\n<div class="doc-h1">31.定期组织车辆性能检查及安全隐患排查，确保车辆技术管理相关机械设备、用电、环境等保持安全状况，保持车辆处于良好的技术状态；</div>\n<div class="doc-h1">32.协助开展生产安全事故造成车辆机损情况的调查与处理工作；</div>\n<div class="doc-h1">33.组织做好车辆技术管理的安全生产风险和应急处置措施的落实工作；</div>\n<div class="doc-h1">34.有权对公司安全生产工作中存在的问题提出批评、检举、控告，有权拒绝违章指挥和强令冒险作业；</div>\n<div class="doc-h1">35.法律、法规、规章以及本公司规定的其他安全生产职责。</div>\n<div class="doc-h3">5.3.4驾驶员</div>\n<div class="doc-li">（1）严格遵守国家及地方的法律法规及标准；</div>\n<div class="doc-li">（2）严格落实岗位安全责任，遵守本单位的安全生产规章制度、操作规程和应急预案等规定要求，服从管理，正确佩戴和使用劳动防护用品；</div>\n<div class="doc-li">（3）接受安全生产教育培训和考核，掌握本职工作所需的安全生产知识，提高安全生产技能，增强事故预防和应急处理能力；</div>\n<div class="doc-li">（4）随身携带相关有效证件及文书，认真做好车辆及安全防护设施、设备、防护用品的日常检查和维护工作，确保设备的安全状态良好，安全防护装置有效，发现事故隐患或者其他不安全因素，立即向安全产管理人员或者负责人报告；</div>\n<div class="doc-li">（5）做好各种个人防护用品、用具的检查工作，确保防护用品和器具齐全、完好有效；</div>\n<div class="doc-li">（6）熟悉车辆性能，熟练驾驶技术，熟练掌握安全技术知识、技能与应急处理方法，做到安全行车；</div>\n<div class="doc-li">（7）严格遵守道路交通发法规，杜绝违法违规行为，严禁车辆载客、超载、超速，不酒驾毒驾、不开带病车、不疲劳驾驶，做好行车中的车辆检查，确保行车安全，防止事故的发生；</div>\n<div class="doc-li">（8）进出场站低速慢行，并服从作业场所人员的管理指挥，确保作业安全；</div>\n<div class="doc-li">（9）合规停放车辆，严禁随意停放车辆，确保车辆安全及周边交通安全；</div>\n<div class="doc-li">（10）运输作业中发生运输事故时及时上报公司相关负责人，并立即采取相应的应急处置措施，及时疏散人员设立警示标志，避免事故扩大；</div>\n<div class="doc-li">（11）服从公司管理人员的指挥和检查，接受上级布置的有关任务；</div>\n<div class="doc-li">（12）法律、法规、规章、规范、标准规定的其他安全生产职责。</div>\n<div class="doc-h3">5.2.5监控员</div>\n<div class="doc-h1">1.负责组织开展公司车辆动态监控管理工作；</div>\n<div class="doc-h1">2.负责对卫星定位监控平台使用及监控信息登记，建立动态监控台账，并归档管理；</div>\n<div class="doc-h1">3.监督卫星定位监控平台及车载设备使用情况，组织协调解决硬件、软件方面在使用中出现的问题，确保监控工作正常开展；</div>\n<div class="doc-h1">4.组织开展驾驶员（车辆）违法违规行为分析，提出普遍问题和重点问题的改进建议；</div>\n<div class="doc-h1">5.负责对驾驶员违法违规行为的监督提醒工作，对经提醒仍然继续违法驾驶的驾驶员，应当及时报告安全管理人员；</div>\n<div class="doc-h1">6.每月对公司动态监控工作开展情况进行全面的总结分析，形成书面材料报告公司主要负责人，并在公司安全生产工作例会上进行专题汇报；</div>\n<div class="doc-h1">7.参加公司开展的安全教育培训、安全活动和应急演练；</div>\n<div class="doc-h1">8.配合开展事故调查处理工作；</div>\n<div class="doc-h1">9.定期开展部门所用设备、器材进行经常性检查，做好防火、防盗及安全用电工作，及时发现和消除安全隐患；</div>\n<div class="doc-h1">10.负责公司安全投入费用的提取和使用管理；</div>\n<div class="doc-h1">11.认真执行上级对安全生产工作的部署要求和各项安全规章制度；</div>\n<div class="doc-h1">12.制定、完善财务安全方面的规章制度并组织落实；</div>\n<div class="doc-h1">13.负责拟订本公司安全投入费用的提取和管理，梳理安全投入台账；</div>\n<div class="doc-h1">14.积极参加安全学习及安全培训,掌握本职工作所需的安全生产知识；</div>\n<div class="doc-h1">15.组织做好财务规范化管理工作，保证安全资金有效使用；</div>\n<div class="doc-h1">16.组织落实安全生产投入管理要求，确保安全生产经费专款专用并按规定足额提取；</div>\n<div class="doc-h1">17.组织做好重点部位、现金使用过程的安全防范工作；</div>\n<div class="doc-h1">18.对事故费用及安全管理过程中发生的罚没款等款项按规定进行有效监督管理。</div>\n<div class="doc-h1">19.做好收入、成本、费用的财务分析，提出合理化建议；</div>\n<div class="doc-h1">20.负责公司日常资金收支结算、往来帐的结算和清理，做好财务证照办理及年审工作,做好安全管理经费、疫情防护资金支出管理工作等；</div>\n<div class="doc-h1">21.参与拟订本公司安全生产规章制度、操作规程和生产安全事故应急救援预案；</div>\n<div class="doc-h1">22.定期检查分管部门的安全生产状况，及时排查生产安全事故隐患，提出改进安全生产管理的建议，督促落实分管部门安全生产整改措施；</div>\n<div class="doc-h1">23.负责公司日常行政管理，做好各类行政管理、后勤保障等工作；</div>\n<div class="doc-h1">24.组织参加公司有关安全生产和基本应急知识等方面的学习培训和考核；</div>\n<div class="doc-h1">25.落实火灾预防，不发生火灾事故；</div>\n<div class="doc-h1">26.发生事故时，做好事故救援及处置的后勤及物资保障工作；</div>\n<div class="doc-h1">27.负责公司级会议的筹备和安排，做好会议记录，整理会议纪要，对会议决定的执行情况进行催办和检查；</div>\n<div class="doc-h1">28.负责传达上级主管部门及公司传染病疫情防控工作要求，配合安全管理部门组织驾驶员做好相关传染病疫情防控知识学习、身体健康防护、疫苗接种等工作；</div>\n<div class="doc-h1">29.法律、法规、规章、规范、标准规定的其他安全生产职责。</div>\n<div class="doc-h1">6.组织实施</div>\n<div class="doc-p">通过签订安全生产责任书的形式明确告知各岗位人员安全生产责任范围和考核标准。责任书的签订由安全生产领导机构办公室组织实施，做到层层签订，横向到边，纵向到底。</div>\n<div class="doc-h1">7.责任制考评</div>\n<div class="doc-h2">7.1 责任追究</div>\n<div class="doc-p">安全生产责任制，把安全生产控制指标层层分解。将每个员工的安全生产职责作为岗位工作实绩考核的标准，与员工本人的考评升级和经济利益结合起来，把激励机制引入公司的安全生产管理工作，做到安全责任明确，奖罚分明。</div>\n<div class="doc-p">因不履行岗位安全生产职责，不遵守公司相关安全管理制度和操作规程，相关方（公司及人员）不按相关安全生产责任书、协议书及承诺书等约定，发生安全责任事故的，公司将按照“四不放过”原则，对相关责任人进行处理。</div>\n<div class="doc-h2">7.2责任制考评奖惩办法</div>\n<div class="doc-p">公司安全生产责任制必须与奖惩制度有机结合，才能使公司安全生产责任制的贯彻落实有保证。实行安全工作“一票否决”制。公司安全生产责任制落实与员工本人的考评升级和经济利益结合起来，把激励机制引入公司的安全生产管理工作。为进一步做好公司安全生产工作，公司加大投入安全考核资金，用于表彰在安全生产工作中有突出表现和做出重大贡献的集体或员工。公司的安全生产工作应每年总结一次。以公司内部安全生产责任制考核结果为依据，由安全员拟出具体名单，公司安全生产领导机构评选安全生产先进集体和先进个人。根据公司安全生产管理工作的特点与实际，公司安全生产考核政策向管理第一线岗位倾斜，加大驾驶员获奖的比例（具体由安全员提出方案，公司安全生产领导机构研究决定）。同时，对处置突发事件（事故）现场处置，防止事故发生或减少损失和社会负面影响方面有突出贡献的部门和个人，公司给予额外的物质与精神奖励。</div>\n<div class="doc-h1">8.持续改进</div>\n<div class="doc-p">安全生产责任制作为所有制度的重点，还需要在实际工作中不断加以完善，形成长效机制。根据公司安全生产责任制实施情况（可操作性、实用性与效果），提出进一步完善安全生产责任制的计划和措施，对安全生产目标、控制指标、管理制度、操作规程等进行修改完善。</div>\n<div class="doc-h1">9.附则</div>\n<div class="doc-h2">9.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">9.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">9.3本制度自发布之日起实施。</div>\n<div class="doc-p">安全生产责任制\n\n\n\n\n\nXxxx公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4201,0,4001,0,'ZD02','安全生产会议制度','制度','BOX2','安全生产会议制度',2,'','<div class="doc-no">制度编号：YT-ZD02</div>\n<div class="doc-p">安全生产会议制度</div>\n<div class="doc-h1">1.目的</div>\n<div class="doc-p">为了及时传达、落实上级对安全生产工作的各项要求，及时解决生产经营活动中出现的安全问题，消除事故隐患，推进安全管理。根据《中华人民共和国安全生产法》及相关法律、法规，制定本制度。</div>\n<div class="doc-h1">2.适用范围</div>\n<div class="doc-p">本制度适用于公司所有安全生产的会议。</div>\n<div class="doc-h1">3.工作程序</div>\n<div class="doc-h2">3.1 年度安全会议</div>\n<div class="doc-h3">3.1.1公司管理层每年召开1次，由公司总经理主持。</div>\n<div class="doc-h3">3.1.2会议参加人员：全体管理人员</div>\n<div class="doc-h3">3.1.3会议内容：</div>\n<div class="doc-li">（1）总结上一年度安全生产工作情况；</div>\n<div class="doc-li">（2）确定年度安全生产目标；</div>\n<div class="doc-li">（3）安排年度安全生产工作等。</div>\n<div class="doc-h3">3.1.4会议由公司安全生产领导机构办公室组织，安排专人做好会议记录。</div>\n<div class="doc-h2">3.2安全生产领导机构会议</div>\n<div class="doc-h3">3.2.1公司安全生产领导机构每季度召开1次以上生产安全会议，会议由总经理主持。总经理无法主持时，安排安全员代为主持。</div>\n<div class="doc-h3">3.2.2会议参加人员：安全生产领导机构成员。</div>\n<div class="doc-h3">3.2.3会议内容：</div>\n<div class="doc-li">（1）企业在相应时间段内安全生产目标改进；</div>\n<div class="doc-li">（2）安全生产岗位职责落实及安全管理重要人员变更；</div>\n<div class="doc-li">（3）安全管理制度改进；</div>\n<div class="doc-li">（4）分析、总结本单位安全生产与管理情况；。</div>\n<div class="doc-li">（5）事故隐患整改情况；</div>\n<div class="doc-li">（6）研究解决安全工作中的重大问题；</div>\n<div class="doc-li">（7）安排阶段性安全生产工作；</div>\n<div class="doc-li">（8）重要安全工作决策与部署等。</div>\n<div class="doc-h3">3.2.4会议由公司安全生产领导机构办公室组织，安排专人做好会议记录。</div>\n<div class="doc-h2">3.3安全工作例会</div>\n<div class="doc-h3">3.3.1安全工作例会每月召开1次以上，必要时随时召开。会议由总经理主持。当总经理无法主持时，安排安全员代为主持。</div>\n<div class="doc-h3">3.3.2会议参加人员：全体人员。</div>\n<div class="doc-h3">3.3.3会议主要内容包括：</div>\n<div class="doc-li">（1）传达、学习有关安全生产的方针、政策、文件；</div>\n<div class="doc-li">（2）企业在相应时间段内的安全生产工作与目标的实施情况（工作总结）；</div>\n<div class="doc-li">（3）通报本月度安全生产状况、安全管理制度符合度评价（违规通报）；</div>\n<div class="doc-li">（4）进行事故分析通报、解剖事故案例；</div>\n<div class="doc-li">（5）针对安全管理中存在的隐患，提出防范措施等；</div>\n<div class="doc-li">（6）本月度安全生产工作分析；</div>\n<div class="doc-li">（7）下个月安全生产工作的实施部署；</div>\n<div class="doc-li">（8）其他需要进行部署、讨论研究的事宜。</div>\n<div class="doc-h3">3.3.4会议由安全员负责组织，安排专人做好会议记录。</div>\n<div class="doc-h2">3.4安全专题会议</div>\n<div class="doc-h3">3.4.1安全专题会议根据专题研究安全生产相关工作需要随时召开。会议由总经理或安全员主持。</div>\n<div class="doc-h3">3.4.2会议参加人员：根据专题研究内容确定参会人员</div>\n<div class="doc-h3">3.4.3会议主要内容包括：专题研究相关内容</div>\n<div class="doc-h3">3.4.4会议由安全员负责组织，安排专人做好会议记录。</div>\n<div class="doc-h1">4.会议管理</div>\n<div class="doc-h2">4.1做好会前准备工作，发布会议通知。</div>\n<div class="doc-h2">4.2做好会议记录（包括会议议题、会议照片、参会人员签名、记录人、会议内容记录等）。</div>\n<div class="doc-h2">4.3会议实行签到制度，凡不能参加会议或不能准时参加会议者，要向主管领导请假，参加线上会议时应通过线上签到的方式进行签到。</div>\n<div class="doc-h2">4.4与会人员提前10分钟入场或登录线上会议软件参会，不得无故迟到、早退，不得中途退会。</div>\n<div class="doc-h2">4.5保持会场纪律，线下会议期间关闭通信工具或将通信工具设置为静音；线上会议期间参会人员默认静音，需要时向主持人申请发言。</div>\n<div class="doc-h1">5.处罚</div>\n<div class="doc-h2">5.1对违反会议纪律的行为给予通报批评。</div>\n<div class="doc-h2">5.2凡必须参加会议人员未经请假擅自不参加会议或请假未批准而不参加会议的，记为缺席，作警告处分。</div>\n<div class="doc-h2">5.3会议内容不及时向上级主管领导汇报；或没按要求贯彻落实会议内容的参会人员，作警告处分。</div>\n<div class="doc-h1">6.附则</div>\n<div class="doc-h2">6.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">6.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">6.3本制度自发布之日起实施。</div>\n<div class="doc-p">安全生产会议制度\n\n\n\n\n\nXxxxx公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4202,0,4001,0,'ZD03','安全生产台账及档案管理制度','制度','BOX2','安全生产台账及档案管理制度',2,'','<div class="doc-no">制度编号：YT-ZD03</div>\n<div class="doc-p">安全生产台账及档案管理制度</div>\n<div class="doc-p">1．目的</div>\n<div class="doc-p">为规范安全管理体系文件的管理，对包括职业健康安全在内的管理体系运行中使用的各类文件实施有效控制，以确保各过程、环节、场所使用的文件具有统一性、完整性、正确性和有效性，与体系运行相关的部门均使用有效的现行版本文件，防止误用作废文件。</div>\n<div class="doc-p">对安全记录档案进行有效控制，以证实符合规定要求，为安全管理体系有效运行提供客观证据，在必要时实现可追溯性，特制定本制度。</div>\n<div class="doc-p">2．适用范围</div>\n<div class="doc-p">本制度适用于公司各类安全生产台账及档案的相关管理工作。</div>\n<div class="doc-p">3．程序内容</div>\n<div class="doc-h2">3.1确定文件种类</div>\n<div class="doc-h3">3.1.1为便于文件管理，根据不同的管理方式将综合管理体系文件分为外来文件、综合管理体系文件。</div>\n<div class="doc-h3">3.1.2外来文件：外来文件系指国家、地方政府部门发布的法律、法规、条例和标准（见法律法规的识别与评价程序）；上级部门下发的通知、要求、规定和办法；相关方的期望和要求。</div>\n<div class="doc-h3">3.1.3综合管理体系文件</div>\n<div class="doc-li">（1）方针、目标和指标；</div>\n<div class="doc-li">（2）实现方针、目标和指标的策划；</div>\n<div class="doc-li">（3）控制各业务过程的程序、规定、指导书、表格。</div>\n<div class="doc-h3">3.1.4资料和台账记录</div>\n<div class="doc-p">相关的资料包括但不限于：</div>\n<div class="doc-p">公司资质证明相关资料；</div>\n<div class="doc-p">公司人员档案资料；</div>\n<div class="doc-p">公司营运车辆档案资料；</div>\n<div class="doc-p">各类分析/评价/统计数据；</div>\n<div class="doc-li">（5）特种设备及其附件的安全技术检验检测资料；</div>\n<div class="doc-li">（6）各类检查、教育培训、应急预案演练及其他活动记录；</div>\n<div class="doc-li">（7）车辆动态监控管理记录资料；</div>\n<div class="doc-li">（8）危险源辨识、风险分级管控资料；</div>\n<div class="doc-li">（9）安全隐患排查与治理记录；</div>\n<div class="doc-li">（10）事故管理档案资料；</div>\n<div class="doc-li">（11）运输单据等相关资料；</div>\n<div class="doc-li">（12）其他资料。</div>\n<div class="doc-h2">3.2提出文件的编制和修改需求</div>\n<div class="doc-h3">3.2.1公司所有人员都有提出编制和修改文件的权利，但是必须向过程负责人提出申请。</div>\n<div class="doc-h3">3.2.2相关负责人确定文件编制、修改的需求及内容。</div>\n<div class="doc-h3">3.2.3相关文件的修改编制根据公司各部门管理职责进行确定，修改编制部门安排相关人员进行相关文件编制、修订。</div>\n<div class="doc-h3">3.2.4文件编制修订部门建立文件清单，在发布/修改文件的同时，文件与文件清单保持一致。</div>\n<div class="doc-h2">3.3评审和审批</div>\n<div class="doc-h3">3.3.1文件评审</div>\n<div class="doc-p">文件由编制人在文件原件编制人栏中签字，文件编制、修订完成后，经所属部门负责人审核同意，再送交相关部门负责人审阅会签（由相应部门负责人确定会签部门的数量），并由文件批准人应对文件进行仔细审核后，如果同意在批准栏签字；</div>\n<div class="doc-p">如果不同意将文件返回文件编写人（或部门），待修改完毕后再批准。</div>\n<div class="doc-h3">3.3.2文件审批权限</div>\n<div class="doc-li">（1）安全方针、总目标、管理手册、管理评审计划及报告、安全生产责任制、应急预案等相关涉及公司整体安全管理工作的文件经安全员审核后，由总经理批准。</div>\n<div class="doc-li">（2）各部门内部业务过程管理文件（程序、规定、制度、表格）由相关过程所属部门负责人审核，安全生产负责人批准。</div>\n<div class="doc-li">（3）操作规程、安全管理指标、各类安全管理台账等由安全员负责人审批。</div>\n<div class="doc-li">（4）各部门内部适用的文件由本部门负责人批准。</div>\n<div class="doc-h2">3.4发放控制</div>\n<div class="doc-h3">3.4.1公司安全员发布安全管理体系文件,建立外发文件清单，该清单内容包括：文件名称、编号、版本、发放日期、数量、发至、接收人等。</div>\n<div class="doc-h3">3.4.2相关操作性、技术性等文件由各部门负责统一发放，并做好发放登记工作。</div>\n<div class="doc-h3">3.4.3需建立文件清单，在发布/修改文件的同时，文件与文件清单保持一致。</div>\n<div class="doc-h2">3.5使用控制</div>\n<div class="doc-h3">3.5.1公司安全员组织负责更新管理体系有关文件，保证体系文件始终保持最新有效状态；定期备份电子版文件。</div>\n<div class="doc-h3">3.5.2管理体系相关的文件必须妥善保存；各部门负责保管本部门相关文件；不得在文件上乱涂画改，不准私自外借，确保文件的清晰、易于识别和检索。</div>\n<div class="doc-h2">3.6文件更新</div>\n<div class="doc-h3">3.6.1当文件在实施过程中因组织结构、产品、工作流程、法律法规、标准等发生变化时，原文件编写部门负责组织对文件进行评审。如果需要进行修改，由原文件编写部门负责提出。</div>\n<div class="doc-p">文件更改申请后组织对文件进行编写并按原文件的审批程序进行审批。</div>\n<div class="doc-h3">3.6.2 文件更新后，由公司监控员发放保存文件原件，同时立即回收原有发布文件，防止作废文件非预期使用。</div>\n<div class="doc-h2">3.7安全档案管理</div>\n<div class="doc-h3">3.7.1企业资质档案</div>\n<div class="doc-li">（1）企业基本信息</div>\n<div class="doc-p">由公司安全员负责建立健全企业基本信息档案，并定期更新。</div>\n<div class="doc-li">（2）办公场地及设备（当期材料）</div>\n<div class="doc-p">由公司安全员负责建立健全停车场地及设备档案，并定期更新。</div>\n<div class="doc-li">（3）安全生产管理制度</div>\n<div class="doc-p">由公司安全员负责建立健全安全生产管理制度档案，并定期更新。</div>\n<div class="doc-h3">3.7.2人员档案</div>\n<div class="doc-li">（1）普通货物道路运输企业管理人员</div>\n<div class="doc-p">由公司安全员负责建立健全公司管理人员档案，并定期更新。</div>\n<div class="doc-li">（2）道路货物运输驾驶员</div>\n<div class="doc-p">由车队长负责建立健全从业人员基础信息档案，按一人一档案，建立从业人员个人档案，并定期更新，同时建立健全从业人员电子信息台帐。</div>\n<div class="doc-h3">3.7.3普通货物道路运输车辆档案</div>\n<div class="doc-p">由车队长负责建立健全车辆基础信息档案，一车一档案要求，建立车辆档案，并定期更新，同时建立健全电子信息台帐。</div>\n<div class="doc-h3">3.7.4监督检查档案</div>\n<div class="doc-p">由公司安全员负责建立健全公司监督检查档案。</div>\n<div class="doc-h1">4.归档</div>\n<div class="doc-h2">4.1归档的材料应齐全、准确、完整和系统。</div>\n<div class="doc-h2">4.2归档的材料纸张大小用 A4纸，并应根据档案分类整理案卷。</div>\n<div class="doc-h2">4.3档案案卷按照分类分别立卷，按照并进行规范编号。</div>\n<div class="doc-h2">4.4 安全生产过程中的录音、录像、照片、计算机存储和其他非纸质载体形式的档案，不单独设置类目，根据内容与纸质档案对应。</div>\n<div class="doc-h2">4.5 相关档案管理部门定期对安全生产记录进行收集并整理记录，放到指定的地点保存或交档案室存档。</div>\n<div class="doc-h1">5.保管</div>\n<div class="doc-h2">5.1 档案应分类存放，有序排列。</div>\n<div class="doc-h2">5.2 企业、车辆、人员证件及记录有效期发生变化，设备更换等有时效性的信息应及时更新。</div>\n<div class="doc-h2">5.3监督检查档案按照相关档案存放期限存放保管。</div>\n<div class="doc-h2">5.4对于电子媒体形式的档案、台账，必须保证所保存的记录不被无关人员或计算机病毒干扰，应留有备份。</div>\n<div class="doc-h2">5.5档案、台账保存要做到防潮、防火、防蛀虫鼠害、防止丢失、防磁等，同时还要做好标识。</div>\n<div class="doc-h2">5.6公司相关档案管理部门定期对保管期限已满的档案进行审核，对确无保存价值的档案登记造册，经总经理批准后进行监销。</div>\n<div class="doc-h1">6.附则</div>\n<div class="doc-h2">6.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">6.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">6.3本制度自发布之日起实施。</div>\n<div class="doc-p">安全生产台账及档案管理制度\n\n\n\n\nXxx公司</div>\n<div class="doc-p">序号 | 档案资料</div>\n<div class="doc-p">1 | 企业概况：企业名称、地址、法定代表人、企业负责人、联系电话、投资总额、注册资本、经营范围、车辆规模、专职安全管理人员及从业人员数量等基本信息；</div>\n<div class="doc-p">2 | 《道路运输经营许可证》；</div>\n<div class="doc-p">3 | 《企业法人营业执照》</div>\n<div class="doc-p">4 | 许可相关材料</div>\n<div class="doc-p">5 | 企业安全生产责任险</div>\n<div class="doc-p">序号 | 档案资料</div>\n<div class="doc-p">1 | 办公场所相关证明材料；</div>\n<div class="doc-p">2 | 配备其他安全防护和消防设施设备清单；</div>\n<div class="doc-p">序号 | 档案资料</div>\n<div class="doc-p">1 | 安全生产责任制</div>\n<div class="doc-p">2 | 安全生产监督检查制度</div>\n<div class="doc-p">3 | 安全生产教育培训制度</div>\n<div class="doc-p">4 | 从业人员安全管理制度</div>\n<div class="doc-p">5 | 专用车辆安全管理制度</div>\n<div class="doc-p">6 | 停车场地安全管理制度</div>\n<div class="doc-p">7 | 应急救援预案制度</div>\n<div class="doc-p">8 | 安全生产考核与奖惩制度</div>\n<div class="doc-p">9 | 安全事故报告、统计与处理制度</div>\n<div class="doc-p">10 | 安全生产费用提取和使用制度</div>\n<div class="doc-p">11 | 动态监控管理制度</div>\n<div class="doc-p">10 | 其他必要的安全生产管理制度</div>\n<div class="doc-p">序号 | 档案资料</div>\n<div class="doc-p">1 | 人员信息登记表</div>\n<div class="doc-p">2 | 安全考核合格证明或注册安全工程师资格证件复印件</div>\n<div class="doc-p">3 | 劳动合同</div>\n<div class="doc-p">4 | 安全生产目标责任书</div>\n<div class="doc-p">5 | 安全承诺书</div>\n<div class="doc-p">6 | 岗位危害及职业危害告知书</div>\n<div class="doc-p">7 | 教育培训记录</div>\n<div class="doc-p">8 | 安全生产奖惩情况记录</div>\n<div class="doc-p">9 | 其他必要档案资料</div>\n<div class="doc-p">序号 | 档案资料 | 档案资料</div>\n<div class="doc-p">1 | 驾驶证复印件（注：驾驶员必备）</div>\n<div class="doc-p">2 | 身份证复印件</div>\n<div class="doc-p">3 | 从业资格证复印件</div>\n<div class="doc-p">4 | 学历证件复印件</div>\n<div class="doc-p">5 | 从业人员信息登记表（姓名、性别、出生年月日、学历、岗位、简历等基本信息）</div>\n<div class="doc-p">6 | 劳动合同</div>\n<div class="doc-p">7 | 健康检查记录</div>\n<div class="doc-p">8 | 安全生产目标责任书</div>\n<div class="doc-p">9 | 签订的各类安全承诺书</div>\n<div class="doc-p">9 | 岗位危险及职业危害告知书</div>\n<div class="doc-p">10 | 从业人员岗前教育培训记录</div>\n<div class="doc-p">11 | 日常教育培训记录</div>\n<div class="doc-p">12 | 诚信考核记录</div>\n<div class="doc-p">13 | 交通违法和事故登记表</div>\n<div class="doc-p">14 | 安全生产考核奖惩情况</div>\n<div class="doc-p">15 | 其它需要归档的相关资料。</div>\n<div class="doc-p">序号 | 档案资料 | 档案资料</div>\n<div class="doc-p">1 | 机动车行驶证复印件</div>\n<div class="doc-p">2 | 道路运输证复印件</div>\n<div class="doc-p">3 | 机动车登记证</div>\n<div class="doc-p">4 | 发票及完税证明</div>\n<div class="doc-p">5 | 道路运输车辆标志和标识的照片</div>\n<div class="doc-p">6 | 车辆技术参数档案</div>\n<div class="doc-p">7 | 卫星定位装置的配备情况</div>\n<div class="doc-p">8 | 车辆保险资料</div>\n<div class="doc-p">9 | 机动车安全技术检验报告</div>\n<div class="doc-p">10 | 车辆等级评定记录</div>\n<div class="doc-p">11 | 车辆维护和维修记录（含出厂合格证、二级维护凭证）</div>\n<div class="doc-p">12 | 车辆机损事故登记表</div>\n<div class="doc-p">13 | 车辆主要部件更换登记表</div>\n<div class="doc-p">14 | 车辆变更记录</div>\n<div class="doc-p">15 | 车辆行驶里程记录</div>\n<div class="doc-p">16 | 有效的通信工具配备情况</div>\n<div class="doc-p">17 | 必备的应急处理器材、安全防护设施设备清单</div>\n<div class="doc-p">18 | 其它需要归档的相关资料</div>\n<div class="doc-p">序号 | 监督检查档案 | 保管部门 | 管理要求</div>\n<div class="doc-p">1 | 安全生产监督检查记录及台账 | 安全员 | 3年</div>\n<div class="doc-p">2 | 安全生产会议记录及台账 | 安全员 | 长期</div>\n<div class="doc-p">3 | 道路运输车辆监控数据记录及违法信息处理台账 | 安全员 | 3年</div>\n<div class="doc-p">4 | 道路运输车辆日常检查（一日三检）记录 | 车队长 | 定期更新</div>\n<div class="doc-p">5 | 道路运输车辆例检记录 | 车队长 | 定期更新</div>\n<div class="doc-p">6 | 安全学习及培训教育记录及台账 | 安全员 | 长期</div>\n<div class="doc-p">7 | 驾驶人员违法驾驶及处理情况记录 | 安全员 | 长期保存</div>\n<div class="doc-p">8 | 应急预案演练记录 | 安全员 | 3年</div>\n<div class="doc-p">9 | 事故报告、应急处置、调查、处理记录及台账 | 安全员 | 长期保存</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4203,0,4001,0,'ZD04','安全生产费用提取和使用管理制度','制度','BOX2','安全生产费用提取和使用管理制度',2,'','<div class="doc-no">制度编号：YT-ZD04</div>\n<div class="doc-p">安全生产费用提取和使用管理制度</div>\n<div class="doc-p">1．目的</div>\n<div class="doc-p">为规范公司的安全生产费用提取和使用管理，使公司安全生产所需费用得到保障，维护公司、员工以及社会公共利益，特制定本制度。</div>\n<div class="doc-p">2．适用范围</div>\n<div class="doc-p">本制度所指安全生产费用：是指企业按照规定标准提取，在成本中列支，专门用于完善和改进企业安全生产条件的资金。并适用于公司安全生产费用的预算、提取以及使用的管理。</div>\n<div class="doc-p">3．职责分工</div>\n<div class="doc-h2">3.1公司总经理负责每年安全生产投入计划的审批、保证安全生产费用能满足安全生产的需要和安全生产投入的有效实施，确保安全生产费用专款专用，并监督其有效实施。</div>\n<div class="doc-h2">3.2安全员根据各部门年度安全投入计划负责编制全公司每年安全生产投入计划、负责安全生产费用的审查、负责监督所有安全生产费用的有效实施，建立安全生产费用台帐。</div>\n<div class="doc-h2">3.3各级管理人员负责落实各自管辖范围内安全生产费用的实施、监督本部门安全投入的有效实施。</div>\n<div class="doc-h2">3.4 监控员负责安全专款的及时提供，将安全生产费用列入财务报表，并做到专款专用。</div>\n<div class="doc-p">4．安全生产费用的使用范围</div>\n<div class="doc-p">根据《企业安全生产费用提取和使用管理办法》中交通运输企业的安全生产费用范围，公司安全生产费用所涉及使用范围如下：</div>\n<div class="doc-h2">4.1完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括道路、水路、铁路、城市轨道交通、管道运输设施设备和装卸工具安全状况检测及维护系统、运输设施设备和装卸工具附属安全设备等支出；</div>\n<div class="doc-h2">4.2购置、安装和使用具有行驶记录功能的车辆卫星定位装置、视频监控装置、船舶通信导航定位和自动识别系统、电子海图等支出；</div>\n<div class="doc-h2">4.3配备、维护、保养应急救援器材、设备支出和应急救援队伍建设、应急预案制修订与应急演练支出；</div>\n<div class="doc-h2">4.4开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出；</div>\n<div class="doc-h2">4.5安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出；</div>\n<div class="doc-h2">4.6配备和更新现场作业人员安全防护用品支出；</div>\n<div class="doc-h2">4.7安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出；</div>\n<div class="doc-h2">4.8安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出；</div>\n<div class="doc-h2">4.9安全设施及特种设备检测检验、检定校准支出；</div>\n<div class="doc-h2">4.10安全生产责任保险及承运人责任保险支出；</div>\n<div class="doc-h2">4.11与安全生产直接相关的其他支出。</div>\n<div class="doc-p">5．安全生产费用的提取</div>\n<div class="doc-h2">5.1 提取和使用安全生产费用遵照“筹措有章、支出有据、管理有序、监督有效”的原则进行管理。</div>\n<div class="doc-h2">5.2 根据《企业安全生产费用提取和使用管理办法》相关要求，交通运输企业以上年度实际营业收入为计提依据，按照以下标准逐月平均提取：普通货运业务按照1%提取。</div>\n<div class="doc-h2">5.3 在安全生产费用保障前提下，要节约成本，确保安全文明生产正常实施。</div>\n<div class="doc-h2">5.4 安全生产费用在本制度规定的范围内使用，应将安全生产费用优先用于满足整改措施或达到法定安全生产标准所需支出。</div>\n<div class="doc-h2">5.5安全生产费用年度结余资金结转下年度使用。公司安全生产费用出现赤字（即当年计提公司安全生产费用加上年初结余小于年度实际支出）的，应当于年末补提公司安全生产费用。</div>\n<div class="doc-p">6．安全生产费用的使用规定</div>\n<div class="doc-h2">6.1公司提取安全生产费用从成本（费用）中列支并专项核算，按规定范围安排使用；</div>\n<div class="doc-h2">6.2安全生产费用作为公司的安全投入专款专用项目，任何人不得挪用或转给其它项目；</div>\n<div class="doc-h2">6.3公司应当将安全费用优先用于满足安全生产监督管理部门或上级主管部门对公司安全生产提出的整改措施或达到安全生产标准所需支出；</div>\n<div class="doc-h2">6.4各部门根据安全生产投入计划,按时完成本部门的安全投入项目,项目完成后报监控员,监控员对安全专项资金进行监督；</div>\n<div class="doc-h2">6.5公司建立安全投入台账，接受安全生产监督管理部门和监控员的监督；</div>\n<div class="doc-p">7．安全生产费用投入审批程序</div>\n<div class="doc-h2">7.1年度安全投入计划项目的审批</div>\n<div class="doc-p">申请部门负责人填写申请表，经安全员审查是否属于年度安全投入计划，如属于报总经理审批后，即可到监控员提取资金。如不属于按非年度安全投入计划项目进行审批。</div>\n<div class="doc-h2">7.2非年度安全投入计划项目的审批</div>\n<div class="doc-p">申请人填写申请表后，经本部门负责人和安全员审查通过后，报总经理进行审批，审批合格即可到监控员领取资金。</div>\n<div class="doc-p">8．建立安全经费使用台账</div>\n<div class="doc-p">由公司监控员负责，安全员配合，建立健全公司的安全经费使用台账，做到账面清晰、资金使用合理，审批流程完备。</div>\n<div class="doc-p">9．安全生产费用的其它管理规定</div>\n<div class="doc-h2">9.1安全生产费用的使用、管理，依法接受安全生产监督管理部门和财政部门的监督。</div>\n<div class="doc-h2">9.2安全生产费用形成的资产，纳入相关资产进行管理。</div>\n<div class="doc-h2">9.3公司由于产权转让、公司改制等变更股权结构或者组织形式的，结余的企业安全生产费用应当继续按照国家相关管理规定和本制度管理使用。</div>\n<div class="doc-h2">9.4公司调整业务、终止经营或者依法清算，结余的安全生产费用应当结转本期收益或者清算收益。</div>\n<div class="doc-h2">9.5公司当年实际使用的安全生产费用不足年度应计提金额60%时，于下一年度4月底前，按照属地安全生产监督管理职责的部门要求提交经公司安全生产领导机构审议的书面说明。</div>\n<div class="doc-p">10．附则</div>\n<div class="doc-h2">10.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">10.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">10.3本制度自发布之日起实施。</div>\n<div class="doc-p">安全生产费用提取和使用管理制度\n\n\n\n\n\nxxx公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4204,0,4001,0,'ZD05','车辆安全管理制度','制度','BOX2','车辆安全管理制度',2,'','<div class="doc-no">制度编号：YT-ZD05</div>\n<div class="doc-p">车辆安全管理制度</div>\n<div class="doc-h1">1.目的</div>\n<div class="doc-p">为保证车辆采购、报废、检测维护、安全设备设施安装及档案管理等工作的有序开展，规范公司普通货物运输车辆安全管理，明确职责，确保运输车辆保持良好的技术状态和正常的使用，杜绝因车辆故障导致事故发生，制定本制度。</div>\n<div class="doc-h1">2.制定依据</div>\n<div class="doc-p">《中华人民共和国道路运输条例》</div>\n<div class="doc-p">《道路运输车辆技术管理规定》</div>\n<div class="doc-h1">3.适用范围</div>\n<div class="doc-p">本制度适用于公司普通货物运输车辆安全管理工作。</div>\n<div class="doc-h1">4.实施主体和职责分工</div>\n<div class="doc-h2">4.1公司总经理负责公司运输车辆和设备的选型、采购、更新、报废等管理决策工作。\n4.2公司车队长负责定期组织开展车辆及相关设备的安全检查工作，并做好相应的记录，建立档案。</div>\n<div class="doc-h2">4.3 驾驶员负责车辆和设备的使用和日常维护工作，做好安全行车、合规使用相关车载设备，并按要求做好相关维护记录。</div>\n<div class="doc-h1">5. 车辆选配及报废管理</div>\n<div class="doc-h2">5.1 车辆选配管理要求</div>\n<div class="doc-h3">5.1.1选用的标准及要求</div>\n<div class="doc-li">（1）车辆是公司生产经营的基础，是公司的主要生产设备。组织运输生产首先要有合适的运输车辆。因此车辆选配应根据运输市场情况以及当地的社会动力、油料供应、运量、运距、道路、气候等社会和自然条件，制订车辆发展规划，择优选购，合理配置车辆，并做好车辆的分配和投用前的技术准备工作。</div>\n<div class="doc-li">（2）车辆的选用要遵循“择优选购、合理配置”的基本标准和要求。</div>\n<div class="doc-h3">5.1.2择优选购</div>\n<div class="doc-li">（1）择优选购是根据运输生产的需要和运行条件，按照对车辆的适应性、经济性、维修和供应配件的方便性以及产品质量的优劣等因素，择优选型购置车辆。</div>\n<div class="doc-li">（2）在选购车辆时，应从车辆的售价、适应性、可靠性、维修和配件供应方便性、燃油经济性以及使用寿命等因素综合考虑。</div>\n<div class="doc-li">（3）择优选购车辆是关系到公司经营生产的关键问题，应进行技术经济论证，避免盲目购置。要从实际出发，按需选购，量力而行，讲究实用可靠，同时尽可能达到少投入多产出、综合经济效益好的目的。</div>\n<div class="doc-h3">5.1.3合理配置选型</div>\n<div class="doc-p">合理配置选型车辆是指公司根据运输任务的性质、运量、运距、气候以及油料供应情况等条件，合理配置车辆，如大、中、小型车辆比例，通用、专用车比例等。通过合理规划，优化车辆构成，充分发挥车辆吨位和客量的利用率，满足运输市场的需要。</div>\n<div class="doc-h3">5.1.4运输设备选用的原则</div>\n<div class="doc-li">（1）车型先进、安全可靠、货物装卸方便。</div>\n<div class="doc-li">（2）车辆规格齐全，能与当地货源相适应，且配比合理(吨位大小，座位多少，高、中、低档比例等)，吨位利用率高。</div>\n<div class="doc-li">（3）车辆的油耗、维修费用、运输成本均低而利润高。</div>\n<div class="doc-li">（4）应用能力强，要求既能完成正常的运输任务，又能完成特殊任务。</div>\n<div class="doc-h3">5.1.5运输设备选型其它因素</div>\n<div class="doc-p">选购、配置车辆时，除需要考虑当地的运输市场状况，明晰现有在用运输车辆的基本技术情况外，还应考虑下列因素:</div>\n<div class="doc-li">（1）车辆经常行驶的道路条件:道路的通过能力、承载质量、坡度大小、路面质量和转弯半径等，均会影响车辆的运行。因此，要注意所配置车辆的技术参数是否适应所要行驶的道路条件，否则会影响运输效率。</div>\n<div class="doc-li">（2）气候、海拔条件:气候、海拔情况不同，对车辆的要求也不同。</div>\n<div class="doc-li">（3）油料供应情况:车辆在使用中要消耗多种油料，如果油料来源困难，就会影响生产。选用新车尤其是进口车(使用优质燃润料)时，要尤其注意。</div>\n<div class="doc-li">（4）车辆使用的经验:在性能先进的前提下，选择新车时应尽量选用公司熟悉的车型。这样在管理、使用和维修上有较为完整且行之有效的规章制度、技术措施，从而可以避免重新组织技术培训和摸索管理方法。</div>\n<div class="doc-li">（5）公司车辆构成情况和维修能力:配置车辆时应考虑当地车辆构成情况，要避免拥有的车辆车型过于复杂，以免造成维修配件材料的供应储备及维修工作的困难。</div>\n<div class="doc-h2">5.2 报废管理要求</div>\n<div class="doc-h3">5.2.1报废标准</div>\n<div class="doc-li">（1）车辆使用年限达到国家机动车强制报废标准规定的（1.车辆超过15年；2.中、轻型载货货车行驶里程超过60万公里；3.重型载货汽车（包括半挂牵引车和全挂牵引车）行驶70万公里报废里程要求）；</div>\n<div class="doc-li">（2）因各种原因造成车辆严重损坏或技术状况低劣，无法修复的；</div>\n<div class="doc-li">（3）车型淘汰，已无配件来源的；</div>\n<div class="doc-li">（4）燃料消耗量超过国家定型车出厂标准规定值15%的；</div>\n<div class="doc-li">（5）经修理和调整仍达不到国家道路运输车辆技术管理规定要求的；</div>\n<div class="doc-li">（6）经调整和修理，或采用排气污染控制技术后，排放污染物仍超过国家规定的汽车排放标准的；</div>\n<div class="doc-li">（7）其它需报废的情形。</div>\n<div class="doc-p">车辆达到报废标准时，车队长填写相关表单，经公司总经理批准后，按相关规定实施。</div>\n<div class="doc-h3">5.2.2 临近车辆报废管理</div>\n<div class="doc-li">（1）加强临近报废车辆的技术监管，及时处理其安全隐患，并将检查、维修等记录填写在技术档案的对应项目中。</div>\n<div class="doc-li">（2）车辆管理人员应认真、如实填写车辆运营里程记录表，做好相应的记录。</div>\n<div class="doc-li">（3）车辆达到临近报废期限时，车队长应告知车辆驾驶员，并做好相应的处理措施。</div>\n<div class="doc-h1">6. 车辆必备安全设施设备的配置和安装要求</div>\n<div class="doc-h2">6.1基础安全设施设备</div>\n<div class="doc-li">（1）灭火器。驾驶室配备1kg以上的灭火器；３.5吨＜总质量≤７.５吨的车辆额外配备4kg以上的灭火器；总质量＞７.５吨的车辆额外配备2个4kg以上的灭火器；</div>\n<div class="doc-li">（2）配备至少2个与最大允许总质量和车轮尺寸相匹配的三角木；</div>\n<div class="doc-li">（3）三角警示牌、反光背心等；</div>\n<div class="doc-li">（4）配备合适的防护性手套；</div>\n<div class="doc-li">（5）配备眼部防护装备（如护目镜）；</div>\n<div class="doc-li">（6）车辆动态监控装置设备。</div>\n<div class="doc-li">（7）其它相关安全防护所需配备的设备设施。</div>\n<div class="doc-h2">6.2 依实际经营范围配备的安全设施设备</div>\n<div class="doc-li">（1）车辆货物困扎、固定所用绳索等固定设施。</div>\n<div class="doc-li">（2）防止遗撒所需的覆盖所用的苫布、篷布等。</div>\n<div class="doc-li">（3）车厢、栏板防渗漏的防水布等。</div>\n<div class="doc-h2">6.3车辆必备安全设施设备安装使用要求</div>\n<div class="doc-h3">6.3.1 安装要求</div>\n<div class="doc-li">（1）车辆出厂配备的安全设施设备由厂家在出厂前安装配备。</div>\n<div class="doc-li">（2）车辆后置安装的安全设备设施，如动态监控装置、主动安全防碰撞系统等，由设备厂商或服务商进行安装调试。</div>\n<div class="doc-li">（3）随车配备的安全设施设备及防护用品，由驾驶员按照公司相关规定进行领用，并按要求置放在驾驶室或车身固定存放处，且便于取放。</div>\n<div class="doc-h3">6.3.2使用管理</div>\n<div class="doc-li">（1）随车设备在使用中正常损坏时，当班驾驶员应立即申报至车队长，由车队长联系公司相关部门确认后，由相关部门负责组织维修、更换工作。</div>\n<div class="doc-li">（2）驾驶员之间交接车辆时，接班驾驶员应清点核对随车设备是否齐全，若不齐全，应要求交班驾驶员进行确认并立即报告至车队长进行处理。</div>\n<div class="doc-h1">7.车辆检查维护与审验评定</div>\n<div class="doc-h2">7.1 车辆检查维护</div>\n<div class="doc-h3">7.1.1 车辆日常检查</div>\n<div class="doc-li">（1）车辆日常检查维护工作按照“谁驾驶、谁负责”的原则，由当班驾驶员负责。</div>\n<div class="doc-li">（2）每日驾驶员应按照行车日志或一日三检相关内容，做好出车前、行车中、收车后的日常检查工作，检查车辆相关部件或设备设施是否正常工作（如：手刹及脚制动器、灯光、喇叭、轮胎、后视镜、雨刮器、仪表、接地线、灭火器等；检查全车有无漏油、漏气、漏水现象，检查轮胎气压、蓄电池中的电解液平面、燃油箱中的储油量、水箱中的存水量、曲轴箱内的机油量是否正常；检查车身厢体罐体外观是否有损坏；车辆安全防护附件及安全标志标识是否清晰无破损以及其它必要检查项目等），并按规定要求认真填写。</div>\n<div class="doc-li">（3）车辆日常检查中发现问题的，应及时上报公司，暂停运输活动，待问题处理后方可重新申请恢复运输活动。</div>\n<div class="doc-h3">7.1.2 车辆例行检查</div>\n<div class="doc-li">（1）车辆例行检查工作由车队长负责，按照公司车辆例行检查内容及要求进行例行检查。</div>\n<div class="doc-li">（2）车队长对营运车辆日常检查和维护情况进行检查，每月对每辆车按期检查，并有书面记录。</div>\n<div class="doc-h3">7.1.3车辆维护</div>\n<div class="doc-p">按照国家相关规定开展车辆二级维护工作，车队长负责制定年度车辆二级维护计划，并组织开展二级维护工作。</div>\n<div class="doc-li">（2）车辆二级维护由驾驶员按期到公司指定有资质的修理厂进行维护。由修理厂按照国家相关规定维护项目进行，维护完成后将车辆维护相关凭证交公司负责车辆档案管理部门进行整理归档。</div>\n<div class="doc-h2">7.2审验评定</div>\n<div class="doc-h3">7.2.1等级评定</div>\n<div class="doc-li">（1）车队长负责组织开展车辆等级评定工作，由驾驶员按要求驾车去检测厂进行检测。检测时出现检测不合格的情形时，由驾驶员及时联系公司，对车辆进行整修，整修完毕后再次进行检测。</div>\n<div class="doc-li">（2）车辆等级评定时间按照车辆《道路运输证》“车辆审验及技术等级记录”中标注的有效期前一个月以内或主管部门通知时间为准。</div>\n<div class="doc-h3">7.2.2车辆审验</div>\n<div class="doc-li">（1）车队长负责安排相关工作人员，按照国家及地方法律法规规定，做好公司车辆年检、年审工作，按照要求准备相关材料，在规定时间内完成车辆年检、年审手续。</div>\n<div class="doc-li">（2）车辆年检、年审相关档案报公司进行归档，纳入车辆档案，确保审验资料完整准确。</div>\n<div class="doc-h1">8.车辆技术档案或台账记录</div>\n<div class="doc-h2">8.1 车辆技术档案</div>\n<div class="doc-p">车队长负责建立健全车辆基础信息档案，一车一档案要求，建立单车档案，并建立健全电子信息台帐。</div>\n<div class="doc-h3">8.1.1车辆技术档案内容</div>\n<div class="doc-p">车辆技术档案中所涉及的资料包括：</div>\n<div class="doc-li">（1）机动车行驶证复印件；</div>\n<div class="doc-li">（2）道路运输证复印件；</div>\n<div class="doc-li">（3）机动车登记证；</div>\n<div class="doc-li">（4）发票及完税证明；</div>\n<div class="doc-li">（5）道路运输车辆标志和标识的照片；</div>\n<div class="doc-li">（6）车辆技术参数档案；</div>\n<div class="doc-li">（7）卫星定位装置的配备情况；</div>\n<div class="doc-li">（8）车辆保险资料；</div>\n<div class="doc-li">（9）机动车安全技术检验报告；</div>\n<div class="doc-li">（10）车辆等级评定记录；</div>\n<div class="doc-li">（11）车辆维护和维修记录（含出厂合格证、二级维护凭证）；</div>\n<div class="doc-li">（12）车辆机损事故登记表；</div>\n<div class="doc-li">（13）车辆主要部件更换登记表；</div>\n<div class="doc-li">（14）车辆变更记录；</div>\n<div class="doc-li">（15）车辆行驶里程记录；</div>\n<div class="doc-li">（16）卫星定位装置配备情况；</div>\n<div class="doc-li">（17）有效的通信工具配备情况；</div>\n<div class="doc-li">（18）必备的应急处理器材、安全防护设施设备清单；</div>\n<div class="doc-li">（19）其它需要归档的相关资料。</div>\n<div class="doc-h3">8.1.2车辆技术档案管理要求</div>\n<div class="doc-li">（1）车辆档案由车队长统一管理，除相关负责人员之外，其余人员严禁动用任何车辆档案。</div>\n<div class="doc-li">（2）车辆档案管理人员对车辆档案的安全性和保密性负责，如出现车辆档案丢失、泄密等情况，一切责任由车辆档案管理人员负责。</div>\n<div class="doc-li">（3）所有车辆档案一律用档案袋保存，一辆车一份档案袋。</div>\n<div class="doc-li">（4）凡有车辆上户、过户、注销、报失等，新的档案内容应在车辆手续办完当天归入相应的档案内。</div>\n<div class="doc-li">（5）车辆档案管理人员要完善档案资料并及时进行维护更新。</div>\n<div class="doc-li">（6）车辆档案查阅。无关人员不得要求查阅车辆档案，凡因工作需要必须查阅车辆档案且需带离公司的，经公司负责人同意后，档案管理人员方可提供。</div>\n<div class="doc-h3">8.1.3 档案保存与销毁</div>\n<div class="doc-li">（1）车辆所有权转移、转籍时，车辆技术档案应当随车移交。</div>\n<div class="doc-li">（2）公司车辆档案保存期限按相关标准规定进行保存。</div>\n<div class="doc-li">（3）公司车队长对保管期限已满的档案进行审核，对确无保存价值的档案登记造册，经企业法定代表人批准后进行监销。</div>\n<div class="doc-h2">8.2 车辆台账记录</div>\n<div class="doc-h3">8.2.1车辆台账记录主要登记车辆关键信息，包括：车牌号、车牌颜色、车辆类型、总质量、核定载重量、车架号、道路运输证号、经营范围、道路运输证审验有效期、行驶证号、行驶证注册日期、发证日期、行驶证检验有效期、行驶证车辆报废日期、安全技术检验有效期、交强险有效期、商业险有效期等以及其它公司管理所需要的相关信息。</div>\n<div class="doc-h3">8.2.2公司车队长应及时更新、完善车辆台账，确保随时查阅、调阅公司车辆最新情况。</div>\n<div class="doc-h1">9.检查记录</div>\n<div class="doc-p">车辆检查记录包括本制度中所述的由公司组织开展日常检查记录、车辆例检记录、车辆安全防护设备设施检查记录；委托专业检测机构开展车辆安全技术性能检测记录、委托具有车辆维修资质的修理厂出具的维护记录；以及按要求在重大节假日或活动期间和季节变化时，开展车辆专项检查工作记录。</div>\n<div class="doc-h1">10.附则</div>\n<div class="doc-h2">10.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">10.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">10.3本制度自发布之日起实施。</div>\n<div class="doc-p">车辆安全管理制度\n\n\n\n\n\nXxx有限公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4205,0,4001,0,'ZD06','安全生产教育培训制度','制度','BOX2','安全生产教育培训制度',2,'','<div class="doc-no">制度编号：YT-ZD06</div>\n<div class="doc-p">安全生产教育培训制度</div>\n<div class="doc-p">1．目的</div>\n<div class="doc-p">为了加强和规范安全培训教育工作，普及安全生产知识，加强安全技术教育，提高全员安全素质，做好安全防范工作，减轻职业危害，预防和减少事故的发生，根据有关法律法规要求，结合本企业的实际，制定本制度。</div>\n<div class="doc-p">2．适用范围</div>\n<div class="doc-p">本制度适用于公司全体员工。</div>\n<div class="doc-h1">3.引用条款</div>\n<div class="doc-p">《中华人民共和国安全生产法》、《中华人民共和国道路运输条例》</div>\n<div class="doc-h1">4.工作职责</div>\n<div class="doc-h2">4.1 安全员负责制订运输各岗位上岗资格条件及培训要求，提出并组织实施本部门人员的年度培训计划，并做好员工的培训记录与档案管理工作，负责联系交通运输管理部门办理主要负责人、安全管理人员上岗资质证明；持证上岗从业人员进行继续教育培训等工作。</div>\n<div class="doc-h2">4.2 安全员负责制定公司年度培训计划，组织开展公司管理人员和从业人员的培训工作，负责组织“安全生产月活动”等，并保存培训及活动记录。</div>\n<div class="doc-h2">4.3 总经理负责批准、监督、检查年度安全培训计划。</div>\n<div class="doc-h2">4.4 监控员负责办理培训教育经费有关手续。</div>\n<div class="doc-p">5．培训要求</div>\n<div class="doc-h2">5.1公司定期了解员工的安全教育培训需求，至少每年了解一次，并根据了解的安全教育培训需求制定年度安全教育培训计划，按计划进行安全教育培训；</div>\n<div class="doc-h2">5.2安全教育培训需求应考虑的方面：员工培训效果、新增法律法规的需求、公司安全形势的需求、管理变化的要求、生产过程风险控制的要求、事故防范的要求、风险评价结果反映出的要求、应急演练与响应结果反映出的要求；</div>\n<div class="doc-h2">5.3组织实施驾驶员岗前、日常培训计划及培训档案管理；</div>\n<div class="doc-h2">5.4组织实施人员新入职及职业健康培训计划及培训档案管理；</div>\n<div class="doc-h2">5.5安全培训计划纳入责任制考核范畴并实施考核；</div>\n<div class="doc-h2">5.6公司主要负责人及安全管理人员的初次安全生产教育和培训时间及每年再培训时间不得少于国家及地方相关规定的学时要求。</div>\n<div class="doc-h2">5.7驾驶员在上岗前接受安全生产教育培训时间和每年再培训时间不得少于国家及地方相关规定的学时要求。</div>\n<div class="doc-h2">5.8换岗、离岗6个月以上复工或者采用新工艺、新技术、新材料和使用新设备的从业人员，接受安全生产教育和培训时间不得少于国家及地方相关规定的学时要求。</div>\n<div class="doc-p">培训教育内容</div>\n<div class="doc-h2">6.1驾驶员岗前教育培训</div>\n<div class="doc-p">公司岗前教育按照三级安全教育方法进行，分为公司级、部门级、车队级的安全教育。</div>\n<div class="doc-p">a.公司级安全教育培训是岗前教育培训的一个重要内容，培训内容重点是国家有关安全生产的法律、法规、条例，国家与行业标准，道路货物运输安全规章制度，公司安全生产管理目标、规章制度、职业道德、风险辨识、劳动纪律、安全考核奖惩、从业人员的安全生产权利和义务、安全事故法律责任规定、有关事故案例等；</div>\n<div class="doc-p">b.部门级安全教育培训是在从业人员工作岗位、工作内容基本确定后进行，由车队长负责人及安全员人员组织实施。培训内容重点是本岗位工作及作业环境范围内的安全风险辩识、评价和控制措施，典型事故案例，岗位安全职责、操作技能及强制性标准，安全检查及隐患排查、自救互救、急救方法、疏散和现场紧急情況的处理，安全设施、个人防护用品的使用和维护、运输货物的基本性质、理化特性、包装容器性能、灭火方法、应急处置措施、运输相关知识；</div>\n<div class="doc-p">c.车队级安全教育培训是在从业人员工作岗位确定后，由车队长负责人及安全员人员组织对其进行安全教育培训。车队安全教育培训重点是岗位安全技术规程、操作规程、岗位之间工作街接配合、作业过程的安全风险分析方法和控制对策、车辆构造常识、车辆日常检查维护、操作装置及方法、应急安全装置及操作方法、服务要求、安全操作经验、事故案例等。</div>\n<div class="doc-h2">6.2驾驶员日常培训教育</div>\n<div class="doc-p">日常安全教育由安全员负责组织实施。主要教育内容包括：</div>\n<div class="doc-li">（1）安全思想和安全技术、遵章守纪教育。</div>\n<div class="doc-li">（2）企业安全生产管理制度和劳动纪律宣贯。</div>\n<div class="doc-li">（3）相关法律、法规、规章以及安全生产文件通报与学习等。</div>\n<div class="doc-li">（4）安全设施设备、劳动防护用品(器具)等的正确操作和维护学习。</div>\n<div class="doc-li">（5）有关安全管理、安全技术、职业健康知识的教育和学习。</div>\n<div class="doc-li">（6）安全检查及事故隐患排查整治分析及对策措施。</div>\n<div class="doc-li">（7）运输事故案例分析和预防措施。</div>\n<div class="doc-li">（8）岗位安全职责和运输操作要求。</div>\n<div class="doc-li">（9）安全生产讲评，先进安全管理经验、安全操作经验学习。</div>\n<div class="doc-li">（10）异常情况紧急处置、事故应急预案、演练要求及经验总结。</div>\n<div class="doc-li">（11）安全生产先进集体(个人)的评选奖励，违规违纪人员的查处。</div>\n<div class="doc-li">（12）事故上报及处理基本要求，以及安全事故“四不放过”。</div>\n<div class="doc-li">（13）其他安全教育内容。</div>\n<div class="doc-h2">6.3特种业人员培训教育</div>\n<div class="doc-p">凡特种作业人员必须经上级有关安全管理部门培训、考试合格，并取得特种作业人员操作证后，方可上岗操作。无证上岗者按严重违章处理。</div>\n<div class="doc-h2">6.4安全管理人员教育</div>\n<div class="doc-h3">6.4.1岗前培训和每年再培训时间不得少于国家及地方相关规定要求，教育培训内容包括：</div>\n<div class="doc-p">a.国家安全生产方针、政策和有关安全生产的法律法规、规章及标准；</div>\n<div class="doc-p">b.安全生产管理基本知识、安全生产技术、安全生产专业知识、职业道德；</div>\n<div class="doc-p">c.重大危险源管理、重大事故防范、应急管理和救援组织以及事故调查处理的有关规定；</div>\n<div class="doc-p">d.伤亡事故统计、报告及职业危害的调查处理方法；</div>\n<div class="doc-p">e.应急管理、应急预案编制以及应急处置的内容和要求；</div>\n<div class="doc-p">f.职业危害及其预防措施；</div>\n<div class="doc-p">g.国内外先进的安全生产管理经验；</div>\n<div class="doc-p">h.典型事故和应急救援案例分析；</div>\n<div class="doc-p">i.基本消防知识和技能</div>\n<div class="doc-p">j.公司安全方针、安全目标及安全责任制，公司的安全管理制度、操作规程、安全组织机构和职责；</div>\n<div class="doc-p">k.运输货物的基本性质、理化特性、包装容器性能、灭火方法、应急处置措施、运输相关知识等；</div>\n<div class="doc-p">l.其他需要培训的内容。</div>\n<div class="doc-h3">6.4.2公司新聘用的专兼职安全员须经过安全培训、考核合格上岗。</div>\n<div class="doc-h2">6.5变换工种及复工安全教育</div>\n<div class="doc-p">员工调整工作岗位或离岗半年以上，在重新上岗时，必须进行相应的部门和岗位两级安全教育。</div>\n<div class="doc-p">6.6“四新”教育</div>\n<div class="doc-p">6.6.1“四新”教育是指采用新工艺、新技术、新材料或者使用新设备前，必须进行的安全教育。</div>\n<div class="doc-p">6.6.2“四新”安全教育主要内容有：</div>\n<div class="doc-li">（1）新工艺、新材料、新技术、新设备的特点和使用方法；</div>\n<div class="doc-li">（2）安全防护装置的特点和使用方法；</div>\n<div class="doc-li">（3）安全管理制度及安全操作规程的内容和要求；</div>\n<div class="doc-li">（4）“四新”投产、使用后可能导致的危险、危害因素及其防护方法；</div>\n<div class="doc-li">（5）涉及“四新”人员安全教育，要进行考试，合格后方可上岗，并报安全员备案。</div>\n<div class="doc-h2">6.7 针对性安全生产教育培训</div>\n<div class="doc-p">针对性安全生产教育培训由安全员负责组织实施。教育内容包括：</div>\n<div class="doc-li">（1）交通法律法规、安全生产管理制度、操作规程；</div>\n<div class="doc-li">（2）交通违法类型及分析；</div>\n<div class="doc-li">（3）事故类型、事故原因分析；</div>\n<div class="doc-li">（4）车辆行驶过程的风险及行车注意事项；</div>\n<div class="doc-li">（5）安全生产事故教育视频案例：事故案例、防御性驾驶技术等。</div>\n<div class="doc-p">安全员负责制订学习计划，提交应培训教育驾驶员名单，进行考勤登记，对培训效果进行评价，培训档案整理归档管理。</div>\n<div class="doc-h2">6.8专题安全教育活动</div>\n<div class="doc-p">国家新颁布文件，组织全体员工学习；举行专题讲座；参观学习同行业安全生产成果展；安全管理先进经验讲座；事故警示专题教育等。</div>\n<div class="doc-h1">7.培训实施计划</div>\n<div class="doc-h2">7.1公司各部门人员按照公司年度教育培训计划的安排，组织实施培训。</div>\n<div class="doc-h2">7.2在每次培训前，培训责任人员提前通知相关部门或人员。</div>\n<div class="doc-h2">7.3培训实施计划的内容：</div>\n<div class="doc-li">（1）培训具体日期；</div>\n<div class="doc-li">（2）培训具体地址；</div>\n<div class="doc-li">（3）培训项目名称；</div>\n<div class="doc-li">（4）培训讲师及资格情况；</div>\n<div class="doc-li">（5）培训对象；</div>\n<div class="doc-li">（6）培训内容；</div>\n<div class="doc-li">（7）培训考核的方式。</div>\n<div class="doc-h1">8.培训要求</div>\n<div class="doc-h2">8.1 每次公司或各部门组织的培训，参加培训的人员应按事件要求完成培训任务，完成培训后签字确认。培训过程要保留相关相片作为证明资料存档，未按时完成参加培训的员工由安全管理人员向总经理汇报，按照公司有关劳动纪律进行处理。并择期进行补习培训。</div>\n<div class="doc-h2">8.2对须进行考试的培训项目，安全管理人员对考核结果进行评分。</div>\n<div class="doc-h2">8.3每次培训结束后，安全管理人员应将培训记录、考试记录（包括考试卷）整理归档。</div>\n<div class="doc-p">9．培训评价和考核</div>\n<div class="doc-h2">9.1安全教育和培训要体现全面、全员、全过程的原则，覆盖所有岗位和人员，确保只通过安全培训合格的人才能上岗。</div>\n<div class="doc-h2">9.2考核包括口答、笔答、操作。</div>\n<div class="doc-h2">9.3在岗员工考核不及格者（80分以下，不含80分），进行再培训，再考核；两次考核不合格者，不得上岗，另行安排。</div>\n<div class="doc-h2">9.4新聘员工考核不合格者，不得录用。</div>\n<div class="doc-p">10．安全培训教育管理</div>\n<div class="doc-h2">10.1公司安全员对公司的安全教育、培训工作实施综合管理，并行使监督检查职能。</div>\n<div class="doc-h2">10.2公司的安全教育工作纳入公司的年度培训教育计划和长期规划，所需要人员、资金和物资应予充分保证。</div>\n<div class="doc-h2">10.3采取会议、宣传栏、视频、图片展览等多种形式，做好对职工的安全宣传教育工作。</div>\n<div class="doc-h2">10.4坚决做到未培训、考试（核）合格的，不准上岗作业。</div>\n<div class="doc-h2">10.5安全教育培训情况和考核结果，应记录存档。</div>\n<div class="doc-h1">11.员工培训档案</div>\n<div class="doc-h2">11.1公司安全管理人员负责建立公司员工安全培训档案，安全员负责建立安全员员工的培训档案。在培训档案中记录每次培训的结果，包括：岗位名称、培训地点、培训日期、培训项目名称、培训资料，培训内容，授课人、培训照片、考核结果及合格证书。</div>\n<div class="doc-h2">11.2公司安全员负责保存公司各级安全培训的记录。</div>\n<div class="doc-p">12．附则</div>\n<div class="doc-h2">12.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">12.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">12.3本制度自发布之日起实施。</div>\n<div class="doc-p">安全生产教育培训制度\n\n\n\n\n\nXxxx有限公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4206,0,4001,0,'ZD07','安全生产监督检查制度','制度','BOX2','安全生产监督检查制度',2,'','<div class="doc-no">制度编号：YT-ZD07</div>\n<div class="doc-p">安全生产监督检查制度</div>\n<div class="doc-h1">1.目的</div>\n<div class="doc-p">为加强安全检查管理，查找不安全因素（包括人、设备、环境、管理等方面），明确安全检查内容，规范安全检查程序，提出消除或控制不安全因素的方法、措施，确保公司安全生产，特制定本制度。</div>\n<div class="doc-h1">2.适用范围</div>\n<div class="doc-p">本制度适用于公司所有安全生产监督检查工作。</div>\n<div class="doc-h1">3.引用条款</div>\n<div class="doc-p">《中华人民共和国安全生产法》</div>\n<div class="doc-p">《中华人民共和国道路运输条例》</div>\n<div class="doc-p">《道路货物运输及场站管理规定》</div>\n<div class="doc-h1">4.检查规定</div>\n<div class="doc-h2">4.1公司安全生产领导机构负责组织公司全面性安全生产检查,由总经理带队开展检查工作；安全员负责组织公司级安全检查、重大活动或节假日期间（元旦、春节、五一、国庆）的安全检查、季节性安全检查和专项安全检查等；各部门负责组织部门日常安全检查，配合开展各项安全检查工作。</div>\n<div class="doc-h2">4.2 安全管理人员负责制定安全检查表，负责参与和监督管理安全检查工作，以及统计安全检查计划完成情况。</div>\n<div class="doc-h2">4.3 公司监控员负责企业车辆动态监控工作情况的检查。</div>\n<div class="doc-h2">4.4驾驶员负责本岗位责任范围内的每日车辆及设备设施的安全检查工作。</div>\n<div class="doc-h1">5.监督检查内容、方法及时间</div>\n<div class="doc-h2">5.1监督检查内容</div>\n<div class="doc-p">根据企业生产特点，监督检查包括但不限于以下内容：</div>\n<div class="doc-li">（1）安全生产管理机构建立健全情况、安全生产责任制和安全管理制度建立健全及落实情况；</div>\n<div class="doc-li">（2）安全投入保障情况，参加工伤保险、安全生产责任险的情况；</div>\n<div class="doc-li">（3）安全培训与教育情况，主要包括：①企业主要负责人、安全管理人员的培训及持证上岗情况； ②从业人员安全教育和技能培训情况。</div>\n<div class="doc-li">（4）车辆及设备设施安全技术状况、随车配备的安全设施设备及应急救援器材情况、车辆动态监控情况；</div>\n<div class="doc-li">（5）从业人员操作规程执行情况；</div>\n<div class="doc-li">（6）企业开展风险评价与隐患排查治理情况，主要包括： ①法律、法规和标准的识别和获取情况； ②定期和及时对作业活动和生产设施进行风险评价情况； ③风险评价结果的落实、宣传及培训情况； ④企业隐患排查治理制度是否满足安全生产需要。</div>\n<div class="doc-li">（7）事故管理、变更管理及承包商的管理情况；</div>\n<div class="doc-li">（8）作业活动作业前的危险有害因素识别与控制情况；</div>\n<div class="doc-li">（9）事故隐患整改、应急预案演练、应急处置培训等情况；</div>\n<div class="doc-li">（10）从业人员劳动防护用品和器具的配置、佩戴与使用情况；</div>\n<div class="doc-li">（11）经营办公场所配备的安全防护设备设施、应急器材情况；</div>\n<div class="doc-li">（12）安全生产其他内容。</div>\n<div class="doc-h2">5.2监督检查方法</div>\n<div class="doc-p">安全生产监督检查包括：包括综合性检查、专业性检查、季节性检查、节假日前后检查、日常检查、事故类比检查等。检查方法采取日常检查和专项安全检查等方式进行，同时可以与隐患排查工作相结合一并开展。</div>\n<div class="doc-h2">5.3监督检查时间频次</div>\n<div class="doc-p">综合性检查每半年一次、公司级安全检查每月一次。</div>\n<div class="doc-li">（2）根据上级部门下发的各种专项行动文件进行专业性检查的安排与实施。</div>\n<div class="doc-li">（3）日常全面检查由公司安全员组织并实施，每月开展一次。</div>\n<div class="doc-li">（4）各岗位管理人员要求每周一次，对生产场所内的人员、设备设施等进行检查；</div>\n<div class="doc-li">（5）驾驶员应按要求进行作业车辆的“一日三检”。</div>\n<div class="doc-li">（6）根据季节性特征及本单位的生产实际，每季度开展一次有针对性的季节性安全检查；重大活动及节假日前必须进行一次安全检查，节假日后组织一次复工复产安全检查。</div>\n<div class="doc-h1">6.工作程序</div>\n<div class="doc-h2">6.1 安全检查</div>\n<div class="doc-h3">6.1.1为了使安全检查更具有针对性、规范性、防止检查项目遗漏或“走过场”，要求各部门及人员依照公司相关安全检查表进行检查。</div>\n<div class="doc-h3">6.1.2安全检查项目确定原则应体现检查项目完整、内容清晰、标准明确、记录完整。实行谁检查，谁负责；谁整改，谁负责；谁验收，谁负责。</div>\n<div class="doc-h3">6.1.3安全检查必须实事求是，检查完毕相关参加人员必须签字确认。</div>\n<div class="doc-h2">6.2 整改通知</div>\n<div class="doc-p">检查组视所发现问题的性质，及可能引起的后果等原因，向相关责任人签发《隐患整改通知单》，指出需整改的问题、整改期限，相关责任人须签字确认并认真落实整改。</div>\n<div class="doc-h2">6.3 检查记录和档案</div>\n<div class="doc-h3">6.3.1各类安全生产检查表、《隐患整改通知单》以及必要时另外所附的“安全检查记录”均为安全检查的正式记录，检查负责人和相关责任人须就检查记录签字确认，并由安全员存档。</div>\n<div class="doc-h3">6.3.2安全管理人员每月对公司进行的各类安全检查结果进行统计，审核各部门的安全检查制度执行情况，如不达标，则安全管理人员须同有关部门商讨原因所在，采取有效措施，限期整改。</div>\n<div class="doc-h1">7.附则</div>\n<div class="doc-h2">7.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">7.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">7.3本制度自发布之日起实施。</div>\n<div class="doc-p">安全生产监督检查制度\n\n\n\n\n\nXxxx有限公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4207,0,4001,0,'ZD08','隐患排查与治理制度','制度','BOX2','隐患排查与治理制度',2,'','<div class="doc-no">制度编号：YT-ZD08</div>\n<div class="doc-p">隐患排查与治理制度</div>\n<div class="doc-h1">1.总则</div>\n<div class="doc-h2">1.1目的</div>\n<div class="doc-p">为深入开展公司安全生产隐患治理工作，有效遏制重特大事故的发生，促进全行业安全生产形势健康发展，特制订本制度。</div>\n<div class="doc-h3">1.2.适用范围</div>\n<div class="doc-p">适用于本公司的安全生产隐患排查与治理工作。</div>\n<div class="doc-h2">1.3编制依据</div>\n<div class="doc-p">《中华人民共和国安全生产法》；</div>\n<div class="doc-p">《中共中央国务院关于推进安全生产领域改革发展的意见》；</div>\n<div class="doc-p">《国务院安委会办公室关于实施遏制重特大事故工作指南构建双重预防机制的意见》；</div>\n<div class="doc-p">《安全生产事故隐患排查治理暂行规定》；</div>\n<div class="doc-p">《公路水路行业安全生产事故隐患治理暂行办法》。</div>\n<div class="doc-h2">1.4术语和定义</div>\n<div class="doc-h3">1.4.1隐患</div>\n<div class="doc-p">作业场所、设备或设施的不安全状态，人的不安全行为，环境的不利因素和管理上的缺陷。</div>\n<div class="doc-h3">1.4.2事故隐患</div>\n<div class="doc-p">含义是隐蔽、隐藏的祸患。即为失控的危险源，是指伴随着现实风险，发生事故的概率较大的危险源。隐患一般包括人（人的不安全行为）、物（物的不安全状态）、环（作业环境的不安全因素）、管（安全管理缺陷）等4个方面。</div>\n<div class="doc-h3">1.4.3一般事故隐患</div>\n<div class="doc-p">是指危害和整改难度较小，发现后能够立即整改排除的隐患。</div>\n<div class="doc-h3">1.4.4重大事故隐患</div>\n<div class="doc-p">是指危害和整改难度较大，应当全部或者局部停产停业，并经过一定时间整改治理方能排除的隐患，或者因外部因素影响致使生产经营单位自身难以排除的隐患。</div>\n<div class="doc-h3">1.4.5事故隐患排查治理</div>\n<div class="doc-p">通过制定事故隐患分类规定、确定事故隐患排查方法和事故隐患风险评价标准，并对不同风险等级的事故隐患采取不同的治理措施，即为隐患排查治理。隐患排查治理措施一般包括：法制措施、管理措施、技术措施、应急措施等四个层次。</div>\n<div class="doc-h3">1.4.6隐患治理闭环管理</div>\n<div class="doc-p">是指为了进一步加强安全隐患排查、统计、分析、治理工作，逐步掌握隐患发生规律，建立的安全隐患分析防控闭环体系。</div>\n<div class="doc-h2">1.5 隐患排查范围</div>\n<div class="doc-p">隐患排查范围应涵盖所有与生产经营相关的区域、场所、设备、人员活动及相关方的服务，企业应将相关方排查出的隐患统一纳入本企业隐患管理。</div>\n<div class="doc-h1">2.事故隐患分类及等级认定</div>\n<div class="doc-h2">2.1 分类</div>\n<div class="doc-p">按检查内容分为基础管理类隐患排查和现场管理类隐患排查两大类。</div>\n<div class="doc-h2">2.2 等级划分</div>\n<div class="doc-p">企业应该组织相关专业技术人员，依据事故隐患的定义，按事故隐患风险程度（即发生的可能性和后果严重程度）进行隐患等级认定。事故隐患分为一般事故隐患和重大事故隐患。</div>\n<div class="doc-h2">2.3 事故隐患等级划分标准</div>\n<div class="doc-p">对重大事故隐患应结合自身的生产经营实际情况，采用风险评估、评价方法对事故隐患后果进行定性分析，并根据风险等级标准和风险评估结果，确定事故隐患的风险等级。具有重大及以上风险的事故隐患，应认定为重大事故隐患。</div>\n<div class="doc-h1">3.隐患排查的职责</div>\n<div class="doc-h2">3.1 隐患治理责任主体</div>\n<div class="doc-p">公司逐级建立并落实从主要负责人到每个从业人员的隐患排查治理和监控责任制，主要负责人对本单位事故隐患排查治理工作全面负责。隐患所在、所管部门为治理主体，无确定单位主管的隐患治理主体为安全员；隐患所在、所管部门主要负责人为隐患治理第一责任人，无确定部门主管的隐患治理，总经理为隐患治理第一责任人。</div>\n<div class="doc-h2">3.2 隐患排查治理资金</div>\n<div class="doc-p">监控员落实隐患排查治理使用资金，建立资金使用专项制度。</div>\n<div class="doc-h2">3.3 隐患排查</div>\n<div class="doc-p">定期组织安全生产管理人员、技术人员和其他相关人员排查本单位的事故隐患。也可根据实际情况聘请有经验的安全专家或注册安全工程师指导开展隐患排查治理工作。对排查出的事故隐患，应当按照事故隐患的等级进行登记，建立事故隐患信息档案，并按照职责分工实施监控治理。</div>\n<div class="doc-h2">3.4 举报奖励制度</div>\n<div class="doc-p">建立事故隐患报告和举报奖励制度，鼓励、发动职工发现和排除事故隐患，鼓励社会公众举报。对发现、排除和举报事故隐患的有功人员，应当给予物质奖励和表彰。</div>\n<div class="doc-h2">3.5 相关方管理</div>\n<div class="doc-p">将生产经营项目、场所、设备发包、出租的，应当与承包、承租单位签订安全生产管理协议，并在协议中明确各方对事故隐患排查、治理和防控的管理职责。公司对承包、承租单位的事故隐患排查治理负有统一协调和监督管理的职责。</div>\n<div class="doc-h2">3.6 定期上报</div>\n<div class="doc-p">每季、每年对本单位事故隐患排查治理情况进行统计分析，按照行业主管部门及安全生产监督管理部门要求，报送相关表格，相关报送材料须由公司主要负责人签字。</div>\n<div class="doc-p">对于重大事故隐患，公司除依照前款规定报送外，应当及时向安全监管监察部门和有关部门报告。重大事故隐患报告内容应当包括：</div>\n<div class="doc-li">（1）隐患的现状及其产生原因；</div>\n<div class="doc-li">（2）隐患的危害程度和整改难易程度分析；</div>\n<div class="doc-li">（3）隐患的治理方案。</div>\n<div class="doc-h2">3.7 隐患整改</div>\n<div class="doc-p">对于一般事故隐患，由公司负责人或者有关人员立即组织整改。</div>\n<div class="doc-p">对于重大事故隐患，由公司主要负责人组织制定并实施事故隐患治理方案。重大事故隐患治理方案应当包括以下内容：</div>\n<div class="doc-li">（1）治理的目标和任务；</div>\n<div class="doc-li">（2）采取的方法和措施；</div>\n<div class="doc-li">（3）经费和物资的落实;</div>\n<div class="doc-li">（4）负责治理的机构和人员；</div>\n<div class="doc-li">（5）治理的时限和要求；</div>\n<div class="doc-li">（6）安全措施和应急预案。</div>\n<div class="doc-h2">3.8 防护措施</div>\n<div class="doc-p">在事故隐患治理过程中，应当采取相应的安全防范措施，防止事故发生。事故隐患排除前或者排除过程中无法保证安全的，应当从危险区域内撤出作业人员，并疏散可能危及的其他人员，设置警戒标志，暂时停产停业或者停止使用；对暂时难以停产或者停止使用后极易引发生产安全事故的相关设施、设备，应当加强维护保养和监测监控，防止事故发生。</div>\n<div class="doc-h2">3.9 预防自然灾害</div>\n<div class="doc-p">加强对自然灾害的预防。对于因自然灾害可能导致事故灾难的隐患，应当按照有关法律、法规、标准和本规定的要求排查治理，采取可靠的预防措施，制定应急预案。在接到有关自然灾害预报时，应当及时向下属单位、驾驶员发出预警通知；发生自然灾害可能危及生产经营单位和人员安全的情况时，应当采取撤离人员、停止作业、加强监测等安全措施，并及时向当地人民政府及其有关部门报告。</div>\n<div class="doc-h1">4.安全隐患排查治理基本要求</div>\n<div class="doc-h2">4.1 隐患排查治理要求</div>\n<div class="doc-p">隐患排查治理工作要做到“四个结合”：</div>\n<div class="doc-li">（1）把行业安全管理与深化交通各项安全专项整治结合起来，狠抓薄弱环节，解决影响安全生产的突出矛盾和问题；突出隐患治理，注重安全生产长效管理机制的建立；</div>\n<div class="doc-li">（2）安全检查与安全文化建设结合起来，加大“三个机制”（组织领导机制、制度保障机制、安全检查机制）、反“三违”（违章指挥、违章作业、违反劳动纪律）、消除隐患滋生根源；</div>\n<div class="doc-li">（3）加强企业安全管理和技术进步结合起来，强化安全标准化建设和现场管理，加大安全投入，推进安全技术改造，夯实安全管理基础；</div>\n<div class="doc-li">（4）加强应急管理结合起来，建立健全应急管理制度，完善事故应急救援预案体系，落实隐患治理责任与监控措施，严防整治期间发生事故。</div>\n<div class="doc-p">根据生产运行特点，制定安全检查计划，明确检查的目的、内容、要求。</div>\n<div class="doc-h2">4.2 事故隐患排查标准</div>\n<div class="doc-p">根据有关安全生产法律法规、规章标准、规范与要求编制不同专业、不同检查层级的事故隐患排查标准，事故隐患排查标准用安全检查表的方法逐一制定。利用检查条款按照相关的标准、规范等对已知的危险类别、设备设施、人员操作、管理、环境等有关的潜在危险性和有害性进行判别检查。</div>\n<div class="doc-h2">4.3 事故隐患治理原则与程序</div>\n<div class="doc-p">事故隐患治理由资源配置、权限、管理及技术能力等因素来确定。每一级均应建立健全隐患治理台账，对隐患清单、隐患治理过程以及隐患治理效果验证均应保持完整记录。</div>\n<div class="doc-h1">5.安全隐患排查方式和频次</div>\n<div class="doc-h2">5.1 隐患排查方式</div>\n<div class="doc-p">事故隐患排查可与日常巡查和专项安全检查相结合的方式进行。根据隐患排查的内容、组织形式，企业隐患排查一般包括综合性检查、专业性检查、季节性检查、节假日前后检查、日常检查、事故类比检查六种方式。</div>\n<div class="doc-h2">5.2 隐患排查频次及分工</div>\n<div class="doc-li">（1）综合性检查任务制定由安全生产领导机构办公室（安全管理部门）组织并实施，每半年一次，其它部门配合并组织本单位的检查；公司级安全检查任务制定由公司安全员组织并实施，要求每月一次。</div>\n<div class="doc-li">（2）上级部门下发的各种专项行动文件，由安全员组织学习宣贯后进行专业性检查的安排与实施。</div>\n<div class="doc-li">（3）日常检查任务制定由公司安全员组织并实施。基层管理人员要求每周一次，对生产场所内的人员、设备设施等进行检查；驾驶员应按要求进行作业车辆的“一日三检”。</div>\n<div class="doc-li">（4）根据季节性特征及本单位的生产实际，每季度开展一次有针对性的季节性隐患排查；重大活动及节假日前必须进行一次隐患排查，节假日后组织一次复工复产隐患排查。</div>\n<div class="doc-li">（5）当获知同类企业发生事故时，应举一反三，及时进行事故类比隐患专项排查。对于岗位人员、设施设备等不经常发生变化的，可依据实际变化情况确定排查周期，如果发生变化，应及时进行隐患排查。</div>\n<div class="doc-li">（6）当发生以下情形之一，应及时组织进行隐患排查：</div>\n<div class="doc-li">①颁布实施有关新的法律法规、标准规范或原有适用法律法规、 标准规范重新修订的；</div>\n<div class="doc-li">②组织机构和人员发生重大调整的；</div>\n<div class="doc-li">③配备新设备、电气、仪表或车型配备等发生重大改变的，应 按变更管理要求进行风险评估；</div>\n<div class="doc-li">④外部安全生产环境发生重大变化；</div>\n<div class="doc-li">⑤发生事故或对事故、事件有新的认识；</div>\n<div class="doc-li">⑥气候条件发生大的变化或预报可能发生重大自然灾害。</div>\n<div class="doc-h1">6.安全隐患排查内容</div>\n<div class="doc-p">根据企业生产特点，隐患排查包括但不限于以下内容：</div>\n<div class="doc-li">（1）安全生产管理机构建立健全情况、安全生产责任制和安全管理制度建立健全及落实情况。</div>\n<div class="doc-li">（2）安全投入保障情况，参加工伤保险、安全生产责任险的情况。</div>\n<div class="doc-li">（3）安全培训与教育情况，主要包括：</div>\n<div class="doc-li">①企业主要负责人、安全管理人员的培训及持证上岗情况；</div>\n<div class="doc-li">②从业人员安全教育和技能培训情况。</div>\n<div class="doc-li">（4）车辆及设备设施安全技术状况及随车配备的安全设施设备及应急救援器材情况；</div>\n<div class="doc-li">（5）从业人员操作规程执行情况；</div>\n<div class="doc-li">（6）企业开展风险评价与隐患排查治理情况，主要包括：</div>\n<div class="doc-li">①法律、法规和标准的识别和获取情况；</div>\n<div class="doc-li">②定期和及时对作业活动和生产设施进行风险评价情况；</div>\n<div class="doc-li">③风险评价结果的落实、宣传及培训情况；</div>\n<div class="doc-li">④企业隐患排查治理制度是否满足安全生产需要。</div>\n<div class="doc-li">（7）事故管理、变更管理及承包商的管理情况。</div>\n<div class="doc-li">（8）作业管理情况，主要包括：</div>\n<div class="doc-li">①作业活动作业前的危险有害因素识别与控制情况；</div>\n<div class="doc-li">②应急处置培训与管理的情况；</div>\n<div class="doc-li">③从业人员劳动防护用品和器具的配置、佩戴与使用情况。</div>\n<div class="doc-li">（9）配备的安全防护设备设施、应急器材情况；</div>\n<div class="doc-li">（10）安全生产其他内容。</div>\n<div class="doc-h1">7.安全隐患的处理</div>\n<div class="doc-h2">7.1 隐患处理的基本原则</div>\n<div class="doc-p">按照隐患治理“定人员、定时间、定责任、定标准、定措施”的“五定”原则，对排查出的事故隐患进行原因分析，制定并落实整改 措施，明确治理责任人，整改效果验证人。并对事故隐患的治理情况进行倒查，施行事故隐患闭环管理。</div>\n<div class="doc-h2">7.2 一般事故隐患的处理</div>\n<div class="doc-li">（1）现场能够立即整改的立即进行整改。</div>\n<div class="doc-li">（2）对于暂时不能整改的一般事故隐患，即有些隐患难以做到立即整改的，但也属于一般隐患，则应限期整改。</div>\n<div class="doc-h2">7.3 重大事故隐患的处理</div>\n<div class="doc-li">（1）对于重大事故隐患，现场应立即采取有效的安全防范措施，防止事故发生。</div>\n<div class="doc-li">（2）重大事故隐患排除前或者排除过程中无法保证安全的，本单位负责人应当从危险区域内撤出作业人员，并疏散可能危及的其他人员，设置警戒标志，暂时停产停业或者停止使用；对暂时难以停产或者停止使用的相关生产设施、设备，应当加强维护和保养，防止事故发生。</div>\n<div class="doc-li">（3）主要负责人及时组织制定并实施事故隐患治理方案，落实相应的安全防范措施，防止事故发生。应按要求及时向安全生产监督管理部门和有关部门报告。重大事故隐患治理方案应当包括以下内容：</div>\n<div class="doc-li">①治理的目标和任务；②采取的方法和措施；③经费和物资的落实；④负责治理的机构和人员；</div>\n<div class="doc-li">⑤治理的时限和要求；⑥安全措施和应急预案。</div>\n<div class="doc-h1">8.验收与评估</div>\n<div class="doc-p">隐患治理完成后，企业应对隐患治理情况进行验收。</div>\n<div class="doc-h2">8.1 要求</div>\n<div class="doc-p">隐患排查治理应符合闭环管理要求，对隐患治理的效果进行验证和跟踪，按照隐患等级明确效果验证责任部门和验证程序要求。对已按照要求整改的隐患及时销号，对未按期和按要求整改的隐患应督促整改并实施考核。</div>\n<div class="doc-h2">8.2 重大隐患治理验收</div>\n<div class="doc-li">（1）重大隐患治理完成后，由公司组织相关技术人员和专家对重大（特大）事故隐患的治理情况进行评估；或委托具备相应资质的安全评价机构对重大（特大）事故隐患的治理情况进行评估。</div>\n<div class="doc-li">（2）经治理后符合安全生产条件的，公司应当向安全生产监督管理部门和有关部门提出恢复生产的书面申请，经安全生产监督管理部门和有关部门审查同意后，方可恢复生产经营。恢复生产书面申请应当包括治理方案的内容、项目、整改情况和相应的评估或评价报告。</div>\n<div class="doc-h1">9.隐患台账建立</div>\n<div class="doc-h2">9.1 事故隐患排查治理体系运行记录</div>\n<div class="doc-p">企业如实记录隐患排查、治理、验收和评估情況，建立健全事故隐患排查与治理档案，建立健全各类隐患排查与治理记录。</div>\n<div class="doc-p">主要应包括：</div>\n<div class="doc-li">（1）检查时间；</div>\n<div class="doc-li">（2）检查部位或场所；</div>\n<div class="doc-li">（3）发现隐患的数量、类别和具体情况；</div>\n<div class="doc-li">（4）整改措施和完成整改时间；</div>\n<div class="doc-li">（5）检查现场照片；</div>\n<div class="doc-li">（6）验收时间；</div>\n<div class="doc-li">（7）检查人员、责任人、验收人签字。</div>\n<div class="doc-h2">9.2 完善事故隐患排查治理闭环工作机制</div>\n<div class="doc-p">完善安全隐患排查治理体系建设，应建立自查、自改、自报事故隐患的信息管理系统。建立健全事故隐患闭环工作机制，实现隐患排查、登记、评估、治理、报告、销账等持续改进的闭环管理。从排查发现隐患、制定整改方案、落实整改措施、验证整改效果等环节实现有效闭合管理。建立完善事故隐患登记报告制、事故隐患整改公示制、重大事故隐患督办制等工作制度，使隐患从发现到整改完毕都处在监督管理下，使排查治理工作成为一个“闭合线路”。对查出的隐患做到责任、措施、资金、时限和预案“五落实”，对重大事故隐患严格落实“分级负责、领导督办、跟踪问效、治理销号”制度。</div>\n<div class="doc-h1">10.隐患信息通报</div>\n<div class="doc-h2">10.1 信息上报</div>\n<div class="doc-p">各级单位和个人发现安全隐患，均有权向各级安全管理部门和相关部门报告。各级安全管理部门接到安全隐患报告后，应当按照职责分工立即组织核实并予以查处；发现所报告隐患应当由其他有关部门处理的，应当立即移送有关部门并记录备查。</div>\n<div class="doc-h2">10.2 举报</div>\n<div class="doc-p">安全管理部门或有相应职能的部门，负责受理各类安全问题的举报，接到举报后立即核实并予以查处，或移交其他相关部门处理，并做好记录备查。</div>\n<div class="doc-h2">10.3 统计分析</div>\n<div class="doc-p">公司各基层单位应当每月对本公司内事故隐患排查治理情况进行评审、分级和统计分析，并于每月5日前逐级向公司安全管理部门报送书面统计分析情况和隐患排查及治理台账。</div>\n<div class="doc-h1">11.工作监督、考核及奖惩</div>\n<div class="doc-h2">11.1各部门按照有关法律、法规、规章、标准和规程的要求，依法开展隐患排查治理工作，发现存在难以解决的重大问题时，应及时报告。</div>\n<div class="doc-h2">11.2安全员应对隐患排查与治理情况进行统计分析，并在公司安全例会上通报隐患排查治理工作，研究解决隐患排查工作中存在的问题。</div>\n<div class="doc-h2">11.3公司安全生产领导机构办公室应结合安全生产日常监管工作，组织安全管理人员定期对本单位安全生产事故隐患进行检查，发现问题及时督促整改。</div>\n<div class="doc-h2">11.4对于发现较大隐患的人员按照公司奖惩制度予以奖励。</div>\n<div class="doc-h2">11.5各部门应按照公司隐患排查与治理管理要求认真做好相关工作，各部门隐患排查与治理情况纳入年度安全生产考核，并按照公司安全生产奖惩制度进行处置。</div>\n<div class="doc-h1">12.附则</div>\n<div class="doc-h2">12.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">12.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">12.3本制度自发布之日起实施。</div>\n<div class="doc-p">隐患排查与治理制度\n\n\n\n\nXxxx有限公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4208,0,4001,0,'ZD09','安全隐患报告和举报奖励制度','制度','BOX2','安全隐患报告和举报奖励制度',2,'','<div class="doc-no">制度编号：YT-ZD09</div>\n<div class="doc-p">安全隐患报告和举报奖励制度</div>\n<div class="doc-h1">1.目的</div>\n<div class="doc-p">为充分发挥安全管理工作中的员工监督作用，及时发现和有效整改安全隐患、生产违章，预防和减少安全事故发生，保障我司安全生产，根据上级安全生产监督管理部门要求，结合我司实际，制定本制度。</div>\n<div class="doc-h1">2.安全隐患报告举报范围</div>\n<div class="doc-h2">2.1公司各部门、驾驶员、发生事故未按规定上报或隐瞒不报、拖延或谎报的。</div>\n<div class="doc-h2">2.2车辆有安全隐患未及时修复、严重危及人员生命财产安全，可能引起人员伤亡或重大财产损失的安全隐患。</div>\n<div class="doc-h2">2.3员工操作过程中不符合有关规程及规范的。</div>\n<div class="doc-h2">2.4其它构成重大伤亡或财产损失危险的安全隐患或者安全生产的“三违”行为。</div>\n<div class="doc-h1">3.报告和举报范围</div>\n<div class="doc-p">公司任何员工均有对安全隐患、安全事故和安全生产“三违”行为进行举报的权利及义务。但举报人在举报时不得捏造、诬告或以举报为名制造事端，干扰安全生产工作秩序。举报时可用电话、电子邮件、意见书等形式，说明事故隐患的名称、地点、安全生产违规、违章行为的时间和行为人等。举报时要告知举报者本人的真实姓名和联系电话，以便及时核实，查处和消除事故隐患及兑现奖励。</div>\n<div class="doc-h1">4.举报受理程序</div>\n<div class="doc-h2">4.1受理各类安全举报时，受理人应立即书面登记编号并到现场勘查核实。如属已受理过的同一内容举报，应向举报人详细说明受理的时间和处理经过。对举报安全违规行为和隐患、事故的，应直接告知举报人有权处理的责任部门。</div>\n<div class="doc-h2">4.2核实举报情况基本属实后，属一般或较大安全隐患的，由安全员下发《隐患整改通知单》督促相关责任人限期整改，并到期进行复查。隐患整改责任人整改事故隐患后，应及时将整改情况书面呈报安全员复查销号和存档。</div>\n<div class="doc-h2">4.3凡属情节特别严重的安全违法行为或重大、特大事故隐患，受理人应立即上报安全生产领导机构和公司领导。</div>\n<div class="doc-h2">4.4举报核实处理完毕，由安全员进行申请，并于每个季度的最后一个月报安全生产领导机构，审批后，对举报人进行奖励。</div>\n<div class="doc-h2">4.5受理举报时，对举报人不愿公开姓名、身份、部门以及不愿公开自己举报行为的，受理单位和人员将尊重举报人的权利给予保密。</div>\n<div class="doc-h1">5.举报奖励标准</div>\n<div class="doc-h2">5.1对经查证属实的举报，由安全生产领导机构按照国家有关事故隐患或者安全生产违规行为严重程度评审确定奖励标准，给予第一时间举报的部门或个人进行奖励。</div>\n<div class="doc-h2">5.2奖励采用现金兑现，由安全员申报，安全员签字后报总经理批准。</div>\n<div class="doc-h2">5.3资金来源：奖励资金由安全投入费用中支出。</div>\n<div class="doc-h1">6.附则</div>\n<div class="doc-h2">6.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">6.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">6.3本制度自发布之日起实施。</div>\n<div class="doc-p">安全隐患报告和举报奖励制度\n\n\n\n\n\nXxx有限公司</div><div class="doc-sign"><div>编制单位：<span class="fill">{{company_name}}</span></div><div>实施日期：<span class="fill">{{start_date}}</span></div><div>签发人：<span class="fill">{{issuer}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4209,0,4001,0,'ZD10','安全生产考核与奖惩制度','制度','BOX2','安全生产考核与奖惩制度',2,'','<div class="doc-no">制度编号：YT-ZD10</div>\n<div class="doc-p">安全生产考核与奖惩制度</div>\n<div class="doc-h1">1.目的</div>\n<div class="doc-p">为了加强公司安全生产的监督与管理，保障公司安全生产管理制度有效落实，督促公司、各岗位人员严格履行安全生产职责，提升公司全员安全生产意识，不断提升安全生产管理水平，依据国家相关法律法规的相关要求，特制定本制度。</div>\n<div class="doc-h1">2.适用范围</div>\n<div class="doc-p">本制度适用于公司全体员工的安全生产考核及奖惩工作。</div>\n<div class="doc-h1">3.实施主体及其职责分工</div>\n<div class="doc-h2">3.1实施主体</div>\n<div class="doc-p">公司安全生产考核及奖惩工作由公司安全生产领导机构组织实施。</div>\n<div class="doc-h2">3.2职责分工</div>\n<div class="doc-h3">3.2.1公司总经理负责建立健全公司安全生产考核及奖惩制度，监督落实考核及奖惩工作开展情况，对最终结果进行审定。</div>\n<div class="doc-h3">3.2.2 公司安全员负责进行安全生产责任目标分解，制定安全生产考核指标，组织开展考核及奖惩工作，负责提出奖惩意见建议，并建立安全生产考核及奖惩档案。</div>\n<div class="doc-h3">3.2.3 公司监控员负责建立安全奖惩资金专用帐户，确保专款专用。</div>\n<div class="doc-h3">3.2.4 公司负责按照考核和奖惩工作要求，组织并参加考核工作，落实相关奖惩措施。</div>\n<div class="doc-h1">4.安全生产考核的具体方法和内容</div>\n<div class="doc-h2">4.1安全生产考核方法</div>\n<div class="doc-h3">4.1.1公司、岗位的安全生产责任考核内容以公司制定的安全生产目标文件和各岗位安全生产职责为依据，由安全员负责制定相关考核表，公司安全生产领导机构进行考核，考核周期为。</div>\n<div class="doc-h3">4.1.2考核方法采用量化考核的方法，考核合格标准为80分以上为及格，具体评分标准见附件《安全生产考核及奖惩标准》。</div>\n<div class="doc-h2">4.2安全生产考核内容</div>\n<div class="doc-h3">4.2.1安全生产考核主要依据安全员制定安全生产考核指标，针对、各岗位安全生产责任目标落实情况进行考核，负责人应认真落实各岗位安全责任制，保证安全生产目标的实现。</div>\n<div class="doc-h3">4.2.2 考核内容包括：</div>\n<div class="doc-li">（1）安全生产制度及规程落实情况（含职责和目标）；</div>\n<div class="doc-li">（2）安全生产教育培训计划落实情况；</div>\n<div class="doc-li">（3）安全生产风险管控及隐患排查治理情况；</div>\n<div class="doc-li">（4）事故处理情况；</div>\n<div class="doc-li">（5）应急管理情况；</div>\n<div class="doc-li">（6）驾驶员道路交通违法、动态监控违规、发生事故等情况；</div>\n<div class="doc-li">（7）专项工作落实情况及其它相关安全管理工作的完成情况。</div>\n<div class="doc-h3">4.2.3 各项工作的安全生产考核指标以安全员制定的安全生产考核指标为准，详见附件《安全生产考核及奖惩标准》。</div>\n<div class="doc-h1">5.奖惩的类型</div>\n<div class="doc-p">安全生产奖惩坚持以绩论奖、以责论罚，奖罚分明的原则。奖励坚持精神鼓励与物质奖励相结合；处罚坚持经济处罚与行政处分相结合。</div>\n<div class="doc-h2">5.1奖励类型</div>\n<div class="doc-p">安全生产奖励分物质奖励和精神奖励。物质奖励包括一次性奖金、奖品或晋级；精神奖励包括通报表扬、记功、授予荣誉称号等。</div>\n<div class="doc-h2">5.2惩罚类型</div>\n<div class="doc-p">根据安全生产责任、危害程度和公司实际情况，对分不安全生产行为、安全生产事故和安全生产考核等情形，视情形给予部门、相关负责人和当事人相应处罚。</div>\n<div class="doc-h3">5.2.1安全生产惩罚分经济处罚和行政处罚两种。</div>\n<div class="doc-h3">5.2.2经济处罚根据危害程度和损失情况、责任大小予以不同程度经济处罚。</div>\n<div class="doc-h3">5.2.3行政处罚根据危害程度和损失情况、责任大小可处以警告、降职、开除。</div>\n<div class="doc-h3">5.3.4性质特别严重、情节恶劣，追究法律责任。</div>\n<div class="doc-h1">6.奖励和处罚标准</div>\n<div class="doc-h2">6.1公司安全生产领导机构组织进行安全生产奖励和处罚的标准的制定工作，具体编制工作由安全员负责。</div>\n<div class="doc-h2">6.2奖励和处罚的标准的设置，应结合公司各岗位的日常安全生产开展情况和年度安全生产目标考核工作进行，针对相关责任落实、工作开展情况、违法违规情形以及安全管理突出表现贡献等方面进行处罚或奖励。</div>\n<div class="doc-h2">6.3具体奖励和处罚的标准内容，详见附件《安全生产考核及奖惩标准》。</div>\n<div class="doc-h1">7.奖惩档案或台账的记录要求</div>\n<div class="doc-h2">7.1 公司安全员负责安全生产奖惩档案及台账的建立与管理工作。</div>\n<div class="doc-h2">7.2奖惩档案内容包括：奖惩依据的证明材料；奖惩信息登记、审核及结果认定等相关记录；落实奖惩措施的结果记录及凭证；公司发布的奖惩公示记录等。</div>\n<div class="doc-h2">7.3记录台账包括：记录时间、考核对象、考核人员、考核标准及结果、奖惩依据、奖惩事由、奖惩类别、奖惩时间、奖惩措施。</div>\n<div class="doc-h1">8.附则</div>\n<div class="doc-h2">8.1本制度由公司安全生产领导机构组织制定。</div>\n<div class="doc-h2">8.2本制度的解释权属于公司安全生产领导机构。</div>\n<div class="doc-h2">8.3本制度自发布之日起实施。</div>\n<div class="doc-p">附件：《安全生产考核及奖惩标准》</div>\n<div class="doc-p">附件：</div>\n<div class="doc-p">安全生产考核及奖惩标准</div>\n<div class="doc-p">一、安全生产责任目标考核与奖惩标准</div>\n<div class="doc-p">（一）安全生产责任目标考核标准</div>\n<div class="doc-p">总经理安全生产责任目标考核标准</div>\n<div class="doc-p">安全员安全生产责任目标考核标准</div>\n<div class="doc-p">监控员安全生产责任目标考核标准</div>\n<div class="doc-p">车队长安全生产责任目标考核标准</div>\n<div class="doc-p">驾驶员安全生产责任目标考核标准</div>\n<div class="doc-p">安全生产责任目标考核结果对应奖惩标准</div>\n<div class="doc-p">日常安全生产工作情况考核与奖惩标准</div>\n<div class="doc-p">总经理日常安全生产工作情况考核与奖惩标准</div>\n<div class="doc-p">安全员日常安全生产工作情况考核与奖惩标准</div>\n<div class="doc-p">监控员日常安全生产工作情况考核与奖惩标准</div>\n<div class="doc-p">车队长日常安全生产工作情况考核与奖惩标准</div>\n<div class="doc-p">驾驶员日常安全生产工作情况考核与奖惩标准</div>\n<div class="doc-p">安全生产考核与奖惩制度\n\n\n \n\n\nXxxx有限公司</div>\n<div class="doc-p">考核事项 | 考核内容 | 考核标准 | 评分标准</div>\n<div class="doc-p">安全生产责任 | 建立健全并落实本公司全员安全生产责任制，加强安全生产标准化建设； | 未组织制定安全生产责任制、责任制未体现公司全部岗位、责任制未体现岗位责任目标 | 3.0</div>\n<div class="doc-p">安全生产责任 | 建立健全并落实本公司全员安全生产责任制，加强安全生产标准化建设； | 安全生产责书、安全承诺书、岗位危害告知书未全员签订、未按安全组织架构全员层层签订制 | 3.0</div>\n<div class="doc-p">安全规章制度、操作规程 | 组织制定并实施本公司安全生产规章制度和操作规程； | 未按法律法规要求组织制定安全生产规章制度、安全生操作规程 | 3.0</div>\n<div class="doc-p">安全教育和培训 | 组织制定并实施本公司安全生产教育和培训计划； | 未按法律法规组织制定年度培训计划； | 3.0</div>\n<div class="doc-p">安全教育和培训 | 组织制定并实施本公司安全生产教育和培训计划； | 未组织公司管理人员及从业人员按培训计划要求进行安全生产教育； | 3.0</div>\n<div class="doc-p">安全教育和培训 | 组织制定并实施本公司安全生产教育和培训计划； | 没对培训结果进行履职签字的 | 2.0</div>\n<div class="doc-p">安全投入费用的提取和管理 | 保证本公司安全生产投入的有效实施； | 未按规定保证本公司安全生产投入的有效实施， | 2.0</div>\n<div class="doc-p">风险分级管控和隐患排查治理 | 组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制； | 未组织建立公司风险识别清单、风险管控措施，并进行告知。 | 2.0</div>\n<div class="doc-p">风险分级管控和隐患排查治理 | 组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制； | 未按规定定期组织并参加公司级隐患排查工作; | 5.0</div>\n<div class="doc-p">风险分级管控和隐患排查治理 | 组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制； | 未对公司隐患排查工作过程中发现的隐患进行及时消除； | 5.0</div>\n<div class="doc-p">安全会议管理 | 协助组织召开安全生产工作会议，汇报安全生产工作开展情况，综合分析公司安全生产和安全运输中的突出问题，提出工作要求及工作建议，如实记录相关会议情况； | 无故未按要求协助组织召开并参加安全生产例会 | 3.0</div>\n<div class="doc-p">应急管理 | 组织制定并实施本公司的生产安全事故应急救援预案，成立应急救援队伍，配备应急救援物资，按规定要求组织开展事故应急救援演练； | 未按法律法规要求制定公司安全生产事故应急预案; | 2.0</div>\n<div class="doc-p">应急管理 | 组织制定并实施本公司的生产安全事故应急救援预案，成立应急救援队伍，配备应急救援物资，按规定要求组织开展事故应急救援演练； | 未按要求组织应急演练 | 2.0</div>\n<div class="doc-p">事故管理 | 及时、如实报告生产安全事故，发生事故时迅速组织抢险救援，并及时向安全生产监督管理等有关部门报告事故情况，启动应急预案，做好善后处理工作，配合管理部门事故调查处理； | 发生事故，未按法律法规要求在1小时内上报有关部门; | 10.0</div>\n<div class="doc-p">事故管理 | 及时、如实报告生产安全事故，发生事故时迅速组织抢险救援，并及时向安全生产监督管理等有关部门报告事故情况，启动应急预案，做好善后处理工作，配合管理部门事故调查处理； | 未按“四不放过"原则进行事故处理，并配合管理部门事故调查处理 | 10.0</div>\n<div class="doc-p">责任事故管理目标 | 发生一般以上生产安全责任事故0宗；\n百万车公里行车责任事故死亡率≤0人；\n百万车公里行车责任事故重伤率≤0人； | 发生一般以上生产安全责任事故（百万车公里行车责任事故死亡1人及以上，百万车公里行车责任事故重伤1人及以上） | 15.0</div>\n<div class="doc-p">责任事故管理目标 | 百万车公里行车责任事故频率≤3宗； | 百万车公里行车责任事故＞3宗 | 15.0</div>\n<div class="doc-p">责任事故管理目标 | 百万车公里行车责任事故经损率≤3.5万元； | 百万车公里行车责任事故累计经济损失＞3.5万元 | 2.0</div>\n<div 