(4231,0,4001,0,'RESP_LETTER','安全生产责任书（变量化范本）','范本','BOX1','安全生产责任书',1,'','<div class="doc-h0">{{title}}</div>\n\n<div class="doc-p">\n遵循"安全第一，预防为主，综合治理"的安全方针，贯彻落实《中华人民共和国安全生产法》的相关要求，\n按照行业及上级主管部门有关安全生产指示精神，强化安全生产"一岗双责、党政同责、失职追责"，\n加强安全生产的管理和监督，开展交通运输企业安全生产标准化建设，建立安全管理长效机制，\n营造良好的安全生产秩序，杜绝生产安全责任死亡交通事故，遏制伤人事故和经济损失事故，\n确保公司各项安全指标达标；按照公司《安全生产责任制》要求，\n{{sign_relation_intro}}，履行公司责任制规定的{{post}}的安全生产责任。\n</div>\n\n<div class="doc-h1">一、安全生产目标</div>\n<div class="doc-p" class="no-indent">1、责任事故控制指标</div>\n<div class="doc-ol">\n  {% if post == \'主要负责人\' %}\n  <div class="doc-li">发生一般以上生产安全责任事故0宗；</div>\n  <div class="doc-li">百万车公里行车责任事故频率≤3宗；</div>\n  <div class="doc-li">百万车公里行车责任事故死亡率≤0人；</div>\n  <div class="doc-li">百万车公里行车责任事故重伤率≤0人；</div>\n  <div class="doc-li">百万车公里行车责任事故经损率≤3.5万元；</div>\n  <div class="doc-li">不发生火灾事故；</div>\n  {% elif post == \'监控员\' or post == \'行政财务\' %}\n  <div class="doc-li">不发生火灾事故；</div>\n  {% else %}\n  <div class="doc-li">发生一般及以上生产安全责任事故0宗；</div>\n  <div class="doc-li">百万车公里行车责任事故频率≤3宗；</div>\n  <div class="doc-li">百万车公里行车责任事故死亡率≤0人；</div>\n  <div class="doc-li">百万车公里行车责任事故重伤率≤0人；</div>\n  <div class="doc-li">百万车公里行车责任事故经损率≤3.5万元；</div>\n  <div class="doc-li">不发生火灾事故、爆炸、泄漏事故；</div>\n  {% endif %}\n</div>\n<div class="doc-p" class="no-indent">2、运输安全管理工作指标</div>\n<div class="doc-ol">\n  {% if post == \'主要负责人\' %}\n  <div class="doc-li">职业病防护率100%；</div>\n  <div class="doc-li">车辆卫星定位装置安装率100%；</div>\n  <div class="doc-li">安全管理人员持证上岗率100%；</div>\n  <div class="doc-li">从业人员持证上岗率100%；</div>\n  <div class="doc-li">培训考核合格率100%；</div>\n  <div class="doc-li">隐患排查治理率100%；</div>\n  <div class="doc-li">事故治理及整改率100%；</div>\n  <div class="doc-li">车辆年检率100%；</div>\n  <div class="doc-li">车辆二级维护率100%；</div>\n  <div class="doc-li">安全生产经费投入100%；</div>\n  <div class="doc-li">组织开展至少3次应急演练。</div>\n  {% elif post == \'安全员\' %}\n  <div class="doc-li">职业病防护率100%；</div>\n  <div class="doc-li">培训考核合格率100%；</div>\n  <div class="doc-li">安全管理人员持证上岗率100%；</div>\n  <div class="doc-li">从业人员持证上岗率100%；</div>\n  <div class="doc-li">隐患排查治理率100%；</div>\n  <div class="doc-li">事故治理及整改率100%；</div>\n  <div class="doc-li">组织并参与3次应急演练。</div>\n  {% elif post == \'监控员\' %}\n  <div class="doc-li">职业病防护率100%；</div>\n  <div class="doc-li">隐患排查治理率100%；</div>\n  <div class="doc-li">卫星定位装置安装率100%；</div>\n  <div class="doc-li">培训考核合格率100%；</div>\n  <div class="doc-li">应急预案演练参与率100%。</div>\n  {% elif post == \'行政财务\' %}\n  <div class="doc-li">职业病防护率100%；</div>\n  <div class="doc-li">隐患排查治理率100%；</div>\n  <div class="doc-li">培训考核合格率100%；</div>\n  <div class="doc-li">安全生产经费投入100%；</div>\n  <div class="doc-li">应急预案演练参与率100%。</div>\n  {% elif post == \'驾驶员\' %}\n  <div class="doc-li">职业病防护率100%；</div>\n  <div class="doc-li">隐患排查治理率100%；</div>\n  <div class="doc-li">卫星定位装置安装率100%；</div>\n  <div class="doc-li">事故治理及整改率100%；</div>\n  <div class="doc-li">培训考核合格率100%；</div>\n  <div class="doc-li">车辆二级维护率100%；</div>\n  <div class="doc-li">车辆年检率100%；</div>\n  <div class="doc-li">应急预案演练参与率100%。</div>\n  {% endif %}\n</div>\n\n<div class="doc-h1">二、安全职责</div>\n<div class="doc-ol">\n  {% if post == \'主要负责人\' %}\n  <div class="doc-li">贯彻执行国家安全生产方针、政策和有关安全生产法律、法规、规章及技术标准等；</div>\n  <div class="doc-li">建立健全并落实本公司全员安全生产责任制，加强安全生产标准化建设；</div>\n  <div class="doc-li">组织制定并实施本公司安全生产规章制度和操作规程；</div>\n  <div class="doc-li">确定符合条件的安全生产分管负责人，依法设置安全生产管理机构或配备专职安全生产管理人员；</div>\n  <div class="doc-li">组织制定并实施本公司安全生产教育和培训计划；</div>\n  <div class="doc-li">保证本公司安全生产投入的有效实施；</div>\n  <div class="doc-li">组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制；</div>\n  <div class="doc-li">督促、检查本公司的安全生产工作，每年至少参加不少于两次的安全生产全面检查...</div>\n  <div class="doc-li">每季度召开一次安全生产专题会议...</div>\n  <div class="doc-li">定期研究安全生产工作...</div>\n  <div class="doc-li">组织制定并实施本公司的生产安全事故应急救援预案...</div>\n  <div class="doc-li">建立、健全本公司的公司负责人现场带班制度...</div>\n  <div class="doc-li">及时、如实报告生产安全事故...</div>\n  <div class="doc-li">组织做好公司传染病疫情防控工作；</div>\n\n  {% elif post == \'安全员\' %}\n  <div class="doc-li">负责公司安全生产工作日常管理工作，贯彻落实公司有关安全生产决定和管理措施。</div>\n  <div class="doc-li">组织或者参与拟订本单位安全生产规章制度、操作规程和生产安全事故应急救援预案...</div>\n  <div class="doc-li">组织或者参与本单位安全生产教育和培训，如实记录安全生产教育和培训情况；</div>\n  <div class="doc-li">组织开展安全风险和危险源辨识、评估...</div>\n  <div class="doc-li">组织或者参与本单位应急救援演练；</div>\n  <div class="doc-li">组织安全生产岗位检查、日常安全检查和专业性安全检查...</div>\n  <div class="doc-li">制止和纠正违章指挥、强令冒险作业、违反操作规程的行为；</div>\n  <div class="doc-li">督促本单位履行安全生产职责、落实安全生产整改措施，组织安全生产考核；</div>\n  <div class="doc-li">协助组织召开安全生产工作会议...</div>\n  <div class="doc-li">协助组织开展安全文化建设及安全生产活动...</div>\n  <div class="doc-li">监督本公司安全生产资金投入和技术措施的落实；</div>\n  <div class="doc-li">组织劳动防护用品及应急救援物资的购置及使用管理工作...</div>\n  <div class="doc-li">协助组织事故抢险救援工作...</div>\n  <div class="doc-li">落实公司的职业健康管理工作；</div>\n  <div class="doc-li">负责安全生产统计与安全生产管理档案建立；</div>\n  <div class="doc-li">法律、法规、规章、规范、标准规定的其他安全生产管理职责。</div>\n\n  {% elif post == \'监控员\' %}\n  <div class="doc-li">负责严格落实安全生产责任制，认真履行安全生产"一岗双责"工作职责...</div>\n  <div class="doc-li">负责对卫星定位监控平台使用及监控信息登记，建立动态监控台账，并归档管理；</div>\n  <div class="doc-li">监督卫星定位监控平台及相关车载设备使用情况...</div>\n  <div class="doc-li">组织开展驾驶员（车辆）违法违规行为分析...</div>\n  <div class="doc-li">负责对驾驶员违法违规行为的监督提醒工作...</div>\n  <div class="doc-li">每月对公司动态监控工作开展情况进行全面的总结分析...</div>\n  <div class="doc-li">参加公司开展的安全教育培训、安全活动和应急演练；</div>\n  <div class="doc-li">配合开展事故调查处理工作；</div>\n  <div class="doc-li">定期开展部门所用设备、器材进行经常性检查...</div>\n  <div class="doc-li">法律、法规、规章、规范、标准规定的其他安全生产职责。</div>\n\n  {% elif post == \'行政财务\' %}\n  <div class="doc-li">参与拟订本公司安全生产规章制度、操作规程和生产安全事故应急救援预案；</div>\n  <div class="doc-li">认真执行上级对安全生产工作的部署要求和各项安全规章制度；</div>\n  <div class="doc-li">负责严格落实安全生产责任制...负责公司日常行政管理；</div>\n  <div class="doc-li">负责严格落实安全生产责任制...负责公司安全投入费用的提取和使用管理；</div>\n  <div class="doc-li">制定、完善财务安全方面的规章制度并组织落实；</div>\n  <div class="doc-li">负责拟订本公司安全投入费用的提取和管理，梳理安全投入台账；</div>\n  <div class="doc-li">积极参加安全学习及安全培训...</div>\n  <div class="doc-li">组织做好财务规范化管理工作，保证安全资金有效使用；</div>\n  <div class="doc-li">组织落实安全生产投入管理要求...</div>\n  <div class="doc-li">组织做好重点部位、现金使用过程的安全防范工作；</div>\n  <div class="doc-li">做好各类行政管理、后勤保障等工作...</div>\n  <div class="doc-li">组织参加公司有关安全生产和基本应急知识等方面的学习培训和考核；</div>\n  <div class="doc-li">依法为从业人员办理工伤保险...</div>\n  <div class="doc-li">落实火灾预防，不发生火灾事故；</div>\n  <div class="doc-li">发生事故时，做好事故救援及处置的后勤及物资保障工作；</div>\n  <div class="doc-li">对事故费用及安全管理过程中发生的罚没款等款项按规定进行有效监督管理。</div>\n  <div class="doc-li">做好收入、成本、费用的财务分析，提出合理化建议；</div>\n  <div class="doc-li">负责公司级会议的筹备和安排...</div>\n  <div class="doc-li">负责传达上级主管部门及公司传染病疫情防控工作要求...</div>\n  <div class="doc-li">负责公司日常资金收支结算、往来帐的结算和清理...</div>\n  <div class="doc-li">法律、法规、规章、规范、标准规定的其他安全生产职责。</div>\n\n  {% elif post == \'驾驶员\' %}\n  <div class="doc-li">严格遵守国家及地方的法律法规及标准；</div>\n  <div class="doc-li">严格落实岗位安全责任，遵守本单位的安全生产规章制度...</div>\n  <div class="doc-li">接受安全生产教育培训和考核...</div>\n  <div class="doc-li">随身携带相关有效证件及文书，认真做好车辆及安全防护设施...</div>\n  <div class="doc-li">做好各种个人防护用品、用具的检查工作...</div>\n  <div class="doc-li">熟悉车辆性能，熟练驾驶技术...</div>\n  <div class="doc-li">严格遵守道路交通发法规，杜绝违法违规行为...</div>\n  <div class="doc-li">进出场站低速慢行，并服从作业场所人员的管理指挥...</div>\n  <div class="doc-li">合规停放车辆，严禁随意停放车辆...</div>\n  <div class="doc-li">运输作业中发生运输事故时及时上报公司相关负责人...</div>\n  <div class="doc-li">服从公司管理人员的指挥和检查，接受上级布置的有关任务；</div>\n  <div class="doc-li">法律、法规、规章、规范、标准规定的其他安全生产职责。</div>\n  {% endif %}\n</div>\n\n<div class="doc-h1">三、责任制考评与奖惩</div>\n<div class="doc-p">公司按照绩效考核方案对责任落实进行考评，按照公司安全生产奖惩制度，成绩显著者给予相应表彰，\n并与经济利益挂钩，安全控制指标不达标给予处罚，并进行相应的经济处罚，因工作失职、不履行岗位责任\n并导致发生重大安全责任事故的，按照相关规定追究责任人的责任，触犯法律的，交由司法机关处理。</div>\n\n<div class="doc-h1">四、其他</div>\n<div class="doc-p">（一）本责任书签订人因工作变动，由继任人在任职当日起继续签订本年度责任书；</div>\n<div class="doc-p">（二）本安全生产责任书期限为一年，自{{period_start}}起至{{period_end}}止。</div>\n<div class="doc-p">（三）本责任书一式贰份，公司与签订人各一份。</div>\n\n<div class="sign-block">\n  {% if post == \'主要负责人\' %}\n  \n  <div class="sign-line">\n    <span class="sign-item">责任主体：{{company_name}}　责任人：{{post}}</span>\n  </div>\n  <div class="sign-line">\n    <span class="sign-item">盖章：<span class="sign-underline"></span></span>\n    <span class="sign-item">签字：<span class="sign-underline">{{sign_image}}</span></span>\n  </div>\n  <div class="sign-line">\n    <span class="sign-item">日期：{{sign_date}}</span>\n    <span class="sign-item">日期：{{sign_date}}</span>\n  </div>\n\n  {% else %}\n  \n  <div class="sign-line">\n    <span class="sign-item">责任管理人：{{manager_post}}</span>\n    <span class="sign-item">责任人：{{post}}</span>\n  </div>\n  <div class="sign-line">\n    <span class="sign-item">签字：<span class="sign-underline">{{manager_sign_image}}</span></span>\n    <span class="sign-item">签字：<span class="sign-underline">{{sign_image}}</span></span>\n  </div>\n  <div class="sign-line">\n    <span class="sign-item">日期：{{sign_date}}</span>\n    <span class="sign-item">日期：{{sign_date}}</span>\n  </div>\n  {% endif %}\n</div>',1,1,'v1.0 内置',1,0),
(4232,0,4001,0,'APPOINT','人员任命书','范本','BOX1','人员任命书',1,'','<div class="doc-p" class="center title">{{title_prefix}}关于任命{{post_title}}的通知</div>\n\n<div class="doc-p">公司{{dept_scope}}：</div>\n\n<div class="doc-p">\n{{appoint_intro}}\n</div>\n\n<div class="doc-p">特此通知。</div>\n\n<div class="sign">\n  <div class="sign-line">公司：{{company_name}}</div>\n  <div class="sign-line">生效日期：{{effect_date}}</div>\n</div>',1,1,'v1.0 内置',1,0),
(4233,0,4001,0,'LEAD_NOTICE','关于成立安全生产领导小组的通知','范本','BOX1','关于成立安全生产领导小组的通知',1,'','<div class="topbar">\n  <div class="doc-h0">成立安全生产领导小组的通知 — 范本系统化改造样例</div>\n  <span class="hint">数据来源：企业信息 + 组织架构（主要负责人/安全员自动带出）· 11条职责为系统内置固定文本</span>\n</div>\n\n<div class="layout">\n  \n  <div class="panel panel-left">\n    <div class="panel-header">① 录入 / 自动带出变量</div>\n    <div class="panel-body">\n\n      <div class="tip">\n        <b>验证要点</b><br>\n        组长自动=主要负责人、副组长=安全员、成员=组织架构其余人员；<br>\n        文号按「企业简称＋年度＋序号」规则自动生成，可改。\n      </div>\n\n      <div class="section">\n        <div class="section-title">企业信息 <span class="badge auto">自动带出</span></div>\n        <div class="field"><label>企业全称 <span class="req">*</span></label>\n          <input id="company_name" value="佛山市励硕物流有限公司"></div>\n        <div class="field"><label>企业简称（文号前缀）</label>\n          <input id="doc_no_prefix" value="LSWL"></div>\n      </div>\n\n      <div class="section">\n        <div class="section-title">文号 <span class="badge auto">自动生成</span></div>\n        <div class="field"><label>发文字号</label>\n          <input id="doc_no" value="LSWL通知【2025】21号" class="empty-mark"></div>\n        <div class="note">规则：{{简称}}通知【{{年度}}】{{序号}}号；序号从文档编号池递增。</div>\n      </div>\n\n      <div class="section">\n        <div class="section-title">领导小组 <span class="badge list">列表变量</span></div>\n        <div class="field"><label>组长（自动=主要负责人）</label>\n          <input id="leader_name" value="万君"></div>\n        <div class="field"><label>副组长（自动=安全员，逗号分隔）</label>\n          <input id="deputy_names" value="夏倩君"></div>\n        <div class="field"><label>成员（自动=其余人员，逗号分隔）</label>\n          <input id="member_names" value="宋传雨,万良俊,梅霞,高如飞,杨涛"></div>\n      </div>\n\n      <div class="section">\n        <div class="section-title">落款</div>\n        <div class="field"><label>成文日期</label><input id="sign_date" value="2025-10-09"></div>\n        <div class="field"><label>印章</label>\n          <select id="seal_type">\n            <option value="auto">系统自动生成圆形红章</option>\n            <option value="none">不盖章</option>\n          </select></div>\n      </div>\n\n      <div class="divider"></div>\n      <button class="btn btn-primary btn-block" onclick="renderAll()">生成通知预览</button>\n      <div style="height:8px"></div>\n      <button class="btn btn-outline btn-block" onclick="resetData()">重置为样例数据</button>\n    </div>\n  </div>\n\n  \n  <div class="panel panel-right">\n    <div class="preview-toolbar">\n      <span style="font-size:12px;color:var(--muted);margin-right:6px">② 预览：</span>\n      <button class="tab active" onclick="renderAll()">通知正文</button>\n      <span style="font-size:12px;color:var(--muted);margin-left:auto">一键签名：下方"落款"已自动套用企业公章 + 主要负责人签名</span>\n    </div>\n    <div class="preview-body">\n      <div class="paper-wrap"><div class="paper" id="paper"></div></div>\n    </div>\n  </div>\n</div>\n\n<script>\nconst DUTIES = [\n  \'组织制定并审核本公司全员安全生产责任制，加强安全生产标准化建设；\',\n  \'组织制定并审核本公司安全生产规章制度、操作规程和生产安全事故应急救援预案，并监督落实；\',\n  \'组织制定并审核本公司安全生产教育和培训计划，并监督落实；\',\n  \'定期召开安全生产领导机构会议，听取各部门安全生产工作汇报，研究解决安全生产运行中的相关问题；\',\n  \'组织建立并审核安全风险分级管控和隐患排查治理双重预防工作机制，督促、检查本单位的安全生产工作，并监督工作开展情况；\',\n  \'组织开展危险源辨识和评估，督促落实本单位重大危险源的安全管理措施；\',\n  \'督促落实本公司安全生产整改措施；\',\n  \'督促各部门及工作人员履行安全生产职责，组织安全生产考核，提出奖惩意见建议；\',\n  \'组织开展公司事故调查、处置及事故责任追究等工作；\',\n  \'督促落实本单位安全生产整改措施；\',\n  \'法律、法规规定的其他安全生产职责。\',\n];\n\nfunction v(id){ return document.getElementById(id).value; }\nfunction esc(s){ return String(s||\'\').replace(/&/g,\'&amp;\').replace(/</g,\'&lt;\').replace(/>/g,\'&gt;\'); }\nfunction fill(val){ return val && val.trim() ? \'<span class="fill-var">\'+esc(val)+\'</span>\' : \'<span class="fill-empty"></span>\'; }\nfunction splitList(s){ return String(s||\'\').split(/[,，、]/).map(x=>x.trim()).filter(Boolean); }\n\nfunction renderMemberList(){\n  const leader = v(\'leader_name\').trim();\n  const deputies = splitList(v(\'deputy_names\'));\n  const members = splitList(v(\'member_names\'));\n  let html = \'\';\n  if(leader) html += \'<div>组&nbsp;&nbsp;长：<span class="fill-var">\'+esc(leader)+\'</span></div>\';\n  if(deputies.length) html += \'<div>副组长：<span class="fill-var">\'+esc(deputies.join(\'、\'))+\'</span></div>\';\n  if(members.length) html += \'<div>成&nbsp;&nbsp;员：<span class="fill-var">\'+esc(members.join(\'、\'))+\'</span></div>\';\n  return html || \'<div class="fill-empty"></div>\';\n}\n\nfunction sealSVG(company){\n  const name = esc(company||\'\');\n  // 简化红章：圆 + 星 + 公司名（弧形排字用 textPath 简化处理，取公司名沿上半弧）\n  const r = 60;\n  return \'<svg viewBox="-75 -75 150 150" xmlns="http://www.w3.org/2000/svg">\' +\n    \'<circle cx="0" cy="0" r="70" fill="none" stroke="#d0021b" stroke-width="3.5"/>\' +\n    \'<circle cx="0" cy="0" r="60" fill="none" stroke="#d0021b" stroke-width="1.2"/>\' +\n    \'<div class="doc-p"ath id="sealarc" d="M -48 26 A 55 55 0 0 1 48 26" fill="none"/>\' +\n    \'<text font-size="12" fill="#d0021b" font-family="SimSun,serif" font-weight="bold"><textPath href="#sealarc" startOffset="50%" text-anchor="middle">\'+name+\'</textPath></text>\' +\n    \'<div class="doc-p"olygon points="0,-18 4,-5 18,-5 7,3 11,16 0,8 -11,16 -7,3 -18,-5 -4,-5" fill="#d0021b"/>\' +\n    \'</svg>\';\n}\n\nfunction renderAll(){\n  const company = v(\'company_name\').trim();\n  const docNo = v(\'doc_no\').trim();\n  const signDate = v(\'sign_date\').trim();\n  const sealOn = v(\'seal_type\') === \'auto\';\n\n  let sealHtml = \'\';\n  if(sealOn && company){\n    sealHtml = \'<span class="seal-anchor">\' + fill(company) +\n      \'<span class="seal-on-line"><span class="seal-wrap">\' + sealSVG(company) + \'</span></span></span>\';\n  } else {\n    sealHtml = fill(company);\n  }\n\n  const html =\n    \'<div class="doc-head"><span class="fill-var">\'+esc(company||\'（企业全称）\')+\'</span></div>\' +\n    \'<div class="doc-no">\' + fill(docNo) + \'</div>\' +\n    \'<div class="rule"></div>\' +\n    \'<h1 class="title">关于公司成立安全生产<br>领导小组的通知</div>\' +\n    \'<div class="doc-p">公司各部门：</div>\' +\n    \'<div class="doc-p">为加强本公司安全生产管理工作，提高全员安全意识，严格认真地落实企业主体责任，做好制度和操作规程管理、安全投入、监控管理、教育培训、现场检查、危险源辨识、隐患排查、风险管控、职业健康、安全文化、应急管理、事故处理、持续改进等规范管理工作，我公司决定成立安全生产领导小组。具体人员组成如下：</div>\' +\n    \'<div class="member-list">\' + renderMemberList() + \'</div>\' +\n    \'<div class="doc-p">安全生产领导小组职责附后。</div>\' +\n    \'<div class="sign-zone">\' +\n      \'<div class="company">\' + sealHtml + \'</div>\' +\n      \'<div class="date">\' + fill(signDate) + \'</div>\' +\n    \'</div>\' +\n    \'<hr style="border:none;border-top:1px dashed #ccc;margin:28px 0">\' +\n    \'<div class="doc-h1">安全生产领导小组职责</div>\' +\n    \'<div class="doc-ol" class="duty">\' + DUTIES.map(function(d,i){ return \'<div class="doc-li">（\'+ (i+1) +\'）\'+d+\'</div>\'; }).join(\'\') + \'</div>\';\n\n  document.getElementById(\'paper\').innerHTML = html;\n}\n\nfunction resetData(){\n  document.getElementById(\'company_name\').value = \'佛山市励硕物流有限公司\';\n  document.getElementById(\'doc_no_prefix\').value = \'LSWL\';\n  document.getElementById(\'doc_no\').value = \'LSWL通知【2025】21号\';\n  document.getElementById(\'leader_name\').value = \'万君\';\n  document.getElementById(\'deputy_names\').value = \'夏倩君\';\n  document.getElementById(\'member_names\').value = \'宋传雨,万良俊,梅霞,高如飞,杨涛\';\n  document.getElementById(\'sign_date\').value = \'2025-10-09\';\n  document.getElementById(\'seal_type\').value = \'auto\';\n  renderAll();\n}\n\nrenderAll();\n</script>',1,1,'v1.0 内置',1,0),
(4234,0,4001,0,'RESUME_SIX','复工复产方案（六个一套装）','范本','BOX1','复工复产方案',1,'','<div class="topbar">\n  <div class="doc-h0">复工复产"六个一"套装 — 范本系统化改造样例</div>\n  <span class="hint">一套范本组 · 共用变量一键生成 7 份文件 · 现场照片/签到表/手填项由企业补齐</span>\n</div>\n\n<div class="layout">\n  \n  <div class="panel panel-left">\n    <div class="panel-header">① 录入 / 自动带出变量（7份共用）</div>\n    <div class="panel-body">\n      <div class="tip">\n        <b>验证要点</b><br>\n        企业全称、复工领导小组、复工日期填一次，7 份文件联动生成；<br>\n        负责人签名/企业盖章自动套用；<span style="color:var(--warn)">现场照片、签到表、培训试卷、检查记录表勾选</span>由企业复工后补。\n      </div>\n\n      <div class="section">\n        <div class="section-title">企业信息 <span class="badge auto">自动带出</span></div>\n        <div class="field"><label>企业全称 <span class="req">*</span></label><input id="company_name" value="广东佳邦通达物流有限公司"></div>\n        <div class="field"><label>应急（值班）电话</label><input id="tel" value="18923277715"></div>\n      </div>\n\n      <div class="section">\n        <div class="section-title">复工领导小组 <span class="badge auto">默认复用安全生产领导小组</span></div>\n        <div class="field"><label>组长（主要负责人）</label><input id="leader_name" value="柴国顺"></div>\n        <div class="field"><label>副组长（安全员）</label><input id="deputy_names" value="韩雪"></div>\n        <div class="field"><label>成员（逗号分隔）</label><input id="member_names" value="陈秀清"></div>\n      </div>\n\n      <div class="section">\n        <div class="section-title">复工时间 <span class="badge auto">默认取节后首工作日</span></div>\n        <div class="field"><label>复工日期（贯穿培训/会议/检查）</label><input id="resume_date" value="2026-02-24"></div>\n        <div class="field"><label>培训/会议地点</label><input id="place" value="办公室"></div>\n        <div class="field"><label>授课人</label><input id="teacher" value="柴国顺"></div>\n      </div>\n\n      <div class="divider"></div>\n      <button class="btn btn-primary btn-block" onclick="renderAll()">一键生成 7 份文件</button>\n      <div style="height:8px"></div>\n      <button class="btn btn-outline btn-block" onclick="resetData()">重置为样例数据</button>\n    </div>\n  </div>\n\n  \n  <div class="panel panel-right">\n    <div class="preview-toolbar">\n      <span style="font-size:12px;color:var(--muted);margin-right:4px">② 预览：</span>\n      <button class="tab active" data-t="1" onclick="switchTab(\'1\')">① 承诺书 <span class="badge sign">签名</span></button>\n      <button class="tab" data-t="2" onclick="switchTab(\'2\')">② 专题会议</button>\n      <button class="tab" data-t="3" onclick="switchTab(\'3\')">③ 复工方案</button>\n      <button class="tab" data-t="4" onclick="switchTab(\'4\')">④ 员工大会</button>\n      <button class="tab" data-t="5" onclick="switchTab(\'5\')">⑤ 培训教育</button>\n      <button class="tab" data-t="6" onclick="switchTab(\'6\')">⑥ 应急方案</button>\n      <button class="tab" data-t="7" onclick="switchTab(\'7\')">⑦ 检查记录表 <span class="badge hand">手填</span></button>\n    </div>\n    <div class="preview-body">\n      <div class="paper-wrap"><div class="paper" id="paper"></div></div>\n    </div>\n  </div>\n</div>\n\n<script>\nlet curTab = \'1\';\n\nfunction v(id){ return document.getElementById(id).value; }\nfunction esc(s){ return String(s||\'\').replace(/&/g,\'&amp;\').replace(/</g,\'&lt;\').replace(/>/g,\'&gt;\'); }\nfunction fill(val){ return val && val.trim() ? \'<span class="fill-var">\'+esc(val)+\'</span>\' : \'<span class="fill-empty"></span>\'; }\nfunction splitList(s){ return String(s||\'\').split(/[,，、]/).map(x=>x.trim()).filter(Boolean); }\nfunction D(){ return { c: v(\'company_name\').trim(), t: v(\'tel\').trim(), leader: v(\'leader_name\').trim(), deputies: splitList(v(\'deputy_names\')), members: splitList(v(\'member_names\')), d: v(\'resume_date\').trim(), place: v(\'place\').trim(), teacher: v(\'teacher\').trim() }; }\n\nfunction sealSVG(company){\n  return \'<svg viewBox="-75 -75 150 150" xmlns="http://www.w3.org/2000/svg">\' +\n    \'<circle cx="0" cy="0" r="70" fill="none" stroke="#d0021b" stroke-width="3.5"/>\' +\n    \'<circle cx="0" cy="0" r="60" fill="none" stroke="#d0021b" stroke-width="1.2"/>\' +\n    \'<div class="doc-p"ath id="sealarc" d="M -48 26 A 55 55 0 0 1 48 26" fill="none"/>\' +\n    \'<text font-size="11" fill="#d0021b" font-family="SimSun,serif" font-weight="bold"><textPath href="#sealarc" startOffset="50%" text-anchor="middle">\'+esc(company||\'\')+\'</textPath></text>\' +\n    \'<div class="doc-p"olygon points="0,-18 4,-5 18,-5 7,3 11,16 0,8 -11,16 -7,3 -18,-5 -4,-5" fill="#d0021b"/>\' +\n    \'</svg>\';\n}\nfunction sealInline(company){\n  return \'<span class="seal-anchor">\'+fill(company)+\'<span class="seal-on-line"><span class="seal-wrap">\'+sealSVG(company)+\'</span></span></span>\';\n}\nfunction leaderBlock(d){\n  let h = \'\';\n  if(d.leader) h += \'<div>组&nbsp;&nbsp;长：<span class="fill-var">\'+esc(d.leader)+\'</span></div>\';\n  if(d.deputies.length) h += \'<div>副组长：<span class="fill-var">\'+esc(d.deputies.join(\'、\'))+\'</span></div>\';\n  if(d.members.length) h += \'<div>成&nbsp;&nbsp;员：<span class="fill-var">\'+esc(d.members.join(\'、\'))+\'</span></div>\';\n  return h || \'<span class="fill-empty"></span>\';\n}\n\n// ---------- 各文件模板 ----------\nfunction tpl1(d){ // 承诺书\n  return \'<h1 class="doc-title">安全生产诚信承诺书</div>\' +\n    \'<div class="doc-p">为切实履行安全生产主体责任，防止和减少生产安全事故发生，<span class="fill-var">\'+esc(d.c)+\'</span>现向本单位从业人员和社会郑重承诺：</div>\' +\n    \'<div class="doc-p">一、切实履行节后复产复工"六个一"（即企业主要负责人主持召开一次企业领导班子安全生产专题会议、制定一份周密的复工复产方案、召开一次全体员工大会、开展一次全员安全教育、制定一套应急处置方案、开展一次全厂性安全检查）。</div>\' +\n    \'<div class="doc-p">二、建立、完善和落实全员安全生产责任制和安全管理制度。企业主要负责人定期听取安全生产工作报告、研究安全生产问题、至少每半年组织一次安全生产全面检查。</div>\' +\n    \'<div class="doc-p">三、依法配置安全生产管理机构和人员，切实保障以上机构和人员履行安全管理职责。</div>\' +\n    \'<div class="doc-p">四、依法保证安全生产资金投入，依法提取和使用安全生产费用，不挤占、不挪用；按规定购买安全生产责任保险。</div>\' +\n    \'<div class="doc-p">五、落实全员安全生产培训制度，明确告知从业人员岗位危险因素、防范措施和应急措施，保证安全培训不合格者不得上岗、未持证者不得从事特种作业。</div>\' +\n    \'<div class="doc-p">六、依法为从业人员提供劳动防护用品并教育从业人员正确佩带；及时纠正违章操作行为，坚决杜绝违章指挥和强令违章冒险作业。</div>\' +\n    \'<div class="doc-p">七、切实加强对涉气、爆破、吊装、高空悬挂、有限空间等危险作业的安全管理。每半年至少开展一次风险点危险源排查，全面识别安全风险，有效落实管控措施。定期开展事故隐患排查，及时消除隐患，按规定向当地应急管理部门报告重大事故隐患排查治理情况。</div>\' +\n    \'<div class="doc-p">八、严格落实建设项目安全设施"三同时"，做好安全警示和安全设备日常维护，不使用淘汰的或明令禁止的工艺、设备和材料。</div>\' +\n    \'<div class="doc-p">九、严格依照许可范围从事矿山生产、危险化学品生产经营使用、烟花爆竹经营等活动，严禁非法违法生产经营。</div>\' +\n    \'<div class="doc-p">十、组织制定并实施本单位生产安全事故应急救援预案，按规定建立应急管理队伍，储备必要应急物资，每半年至少组织一次事故应急救援演练。如发生生产安全事故，保证及时、如实报告当地应急管理部门。</div>\' +\n    \'<div class="doc-p">我单位将严格遵守《中华人民共和国安全生产法》和《广东省安全生产条例》等国家及省有关安全生产法律、法规和标准规定，认真履行承诺，依法建设施工和生产经营，积极配合应急管理部门的监督检查，自觉维护从业人员和公众权益，接受社会监督。如有违反，我单位愿意承担相应法律责任。</div>\' +\n    \'<div class="sign-zone">\' +\n      \'<div>承诺单位（盖章）：\'+sealInline(d.c)+\'</div>\' +\n      \'<div style="margin-top:12px">法定代表人签字：<span class="sign-line"></span></div>\' +\n      \'<div style="margin-top:12px">\'+fill(d.d.split(\'-\')[0])+\' 年&nbsp;&nbsp;&nbsp;&nbsp;月&nbsp;&nbsp;&nbsp;&nbsp;日</div>\' +\n    \'</div>\';\n}\n\nfunction tpl2(d){ // 专题会议\n  return \'<h1 class="doc-title">\'+esc(d.c)+\'<br>\'+fill(d.d.split(\'-\')[0])+\'年节后复产领导班子安全生产专题会议</div>\' +\n    \'<div class="doc-p" class="no-indent meta">培训时间：\'+fill(d.d)+\'&nbsp;&nbsp;培训地点：\'+fill(d.place)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent meta">培训人数：<span class="fill-empty"></span>人&nbsp;&nbsp;培训方式：线下</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>培训主要内容：</b></div>\' +\n    \'<div class="doc-ol"><div class="doc-li">复工复产六个一的安排工作；</div><div class="doc-li">节后复工复产安全工作目标；</div><div class="doc-li">"三个一"（高危行业"六个一"）解读；</div><div class="doc-li">督促落实全员安全生产责任制；</div><div class="doc-li">\'+fill(d.d.split(\'-\')[0])+\'年度风险辨识；</div><div class="doc-li">制定排查方案；</div><div class="doc-li">全员安全生产培训；</div><div class="doc-li">新入职员工入职三级教育；公司级、部门级、岗位级安全教育层层落实；</div><div class="doc-li">应急物资检查；</div><div class="doc-li">督促大家去线上学习复工复产第一课。</div></div>\' +\n    \'<div class="sign-zone">企业盖章：<br><span style="display:inline-block;margin-top:6px">\'+sealInline(d.c)+\'</span></div>\' +\n    \'<h2 style="margin-top:26px">会议记录表</div>\' +\n    \'<div class="doc-p" class="no-indent">培训时间：\'+fill(d.d)+\'&nbsp;&nbsp;培训地点：\'+fill(d.place)+\'&nbsp;&nbsp;授课人：\'+fill(d.teacher)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>内容摘要：</b>（同上培训主要内容）</div>\' +\n    \'<div class="photo-holder">现场照片（企业拍摄后上传）</div>\' +\n    \'<div class="doc-h1">会议签到表</div>\' + signSheet();\n}\n\nfunction tpl3(d){ // 复工方案\n  return \'<h1 class="doc-title">\'+esc(d.c)+\'<br>\'+fill(d.d.split(\'-\')[0])+\'年节后复工复产方案</div>\' +\n    \'<div class="doc-p">根据各级关于企业节后复工复产工作要求精神，切实加强我司（厂）安全生产工作，保证安全生产工作的顺利推进，确保做到"安全第一、预防为主"的安全方针政策，特制定本复工复产方案，确保我司（厂）各项复工复产安全生产工作有序进行。</div>\' +\n    \'<div class="doc-h1">一、成立节后复工复产领导小组</div>\' +\n    \'<div style="margin-left:3em">\'+leaderBlock(d)+\'</div>\' +\n    \'<div class="doc-p">领导小组组成：必须由企业主要负责人带队，由安全员、监控员等重要岗位负责人组成。</div>\' +\n    \'<div class="doc-h1">二、复工复产安全生产培训教育计划</div>\' +\n    \'<div class="doc-p" class="no-indent">（一）培训方式：线上+线下培训</div>\' +\n    \'<div class="doc-p" class="no-indent">（二）培训时间：\'+fill(d.d)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent">（三）培训地点：\'+fill(d.place)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent">（四）培训内容</div>\' +\n    \'<div class="doc-p">1.安全生产法律法规、规章制度、操作规程、应急救援及应急处置技能、复工复产安全措施。</div>\' +\n    \'<div class="doc-p">2.职业病及劳保用品防护使用知识。</div>\' +\n    \'<div class="doc-p">3.车间危险源及管控措施培训。</div>\' +\n    \'<div class="doc-p" class="no-indent">（五）培训对象：全体员工</div>\' +\n    \'<div class="doc-p" class="no-indent">（六）培训考核要求：通过安全教育培训使全体员工提高安全生产意识，掌握公司及本人岗位安全风险要点、防护措施和应急处置措施；自觉遵守公司各项规章制度和安全操作规程。</div>\' +\n    \'<div class="doc-h1">三、复工复产安全检查内容</div>\' +\n    \'<div class="doc-p" class="no-indent">1.检查时间：\'+fill(d.d.split(\'-\')[1])+\' 月 \'+fill(d.d.split(\'-\')[2])+\' 日</div>\' +\n    \'<div class="doc-p" class="no-indent">2.检查内容：电气线路和设备安全检查；机械设备安全检查；车间、仓库作业环境安全检查；消防设备设施安全检查；职业卫生、劳动防护安全检查；特种设备安全检查。</div>\' +\n    \'<div class="doc-h1">四、隐患整改及落实</div>\' +\n    \'<div class="doc-p" class="no-indent">1、管理上缺失隐患，需形成制度，加强日后监督管理；</div>\' +\n    \'<div class="doc-p" class="no-indent">2、存在重大安全隐患部位，一律不允许复产生产；</div>\' +\n    \'<div class="doc-p" class="no-indent">3、一般安全隐患，立即快速处理整改，当天处理不了的必须限期整改；</div>\' +\n    \'<div class="doc-p" class="no-indent">4、安全隐患必须定责任人、定期、定资金、重大安全隐患还需定方案和验收。</div>\' +\n    \'<div class="sign-zone">\' +\n      \'<div>企业名称（盖章）：\'+sealInline(d.c)+\'</div>\' +\n      \'<div style="margin-top:8px">\'+fill(d.d)+\'</div>\' +\n    \'</div>\';\n}\n\nfunction tpl4(d){ // 员工大会\n  return \'<h1 class="doc-title">\'+esc(d.c)+\'<br>\'+fill(d.d.split(\'-\')[0])+\'年节后复产全体员工大会</div>\' +\n    \'<div class="doc-p" class="no-indent meta">会议时间：\'+fill(d.d)+\'&nbsp;&nbsp;会议地点：\'+fill(d.place)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent meta">会议人数：<span class="fill-empty"></span>人&nbsp;&nbsp;会议方式：线下</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>会议主要内容：</b></div>\' +\n    \'<div class="doc-ol"><div class="doc-li">近期政府宣贯文件或内部需传达的安全事项、文件等；</div><div class="doc-li">我司复工复产方案；</div><div class="doc-li">事故分析通报、解剖事故案例；</div><div class="doc-li">下月安全生产工作的实施部署和其他需要讨论研究的事宜；</div><div class="doc-li">道路运输驾驶员应急驾驶操作培训。</div></div>\' +\n    \'<div class="sign-zone">企业盖章：<br><span style="display:inline-block;margin-top:6px">\'+sealInline(d.c)+\'</span></div>\' +\n    \'<h2 style="margin-top:26px">会议记录表</div>\' +\n    \'<div class="doc-p" class="no-indent">会议时间：\'+fill(d.d)+\'&nbsp;&nbsp;会议地点：\'+fill(d.place)+\'&nbsp;&nbsp;授课人：\'+fill(d.teacher)+\'</div>\' +\n    \'<div class="photo-holder">现场照片（企业拍摄后上传）</div>\' +\n    \'<div class="doc-h1">会议签到表</div>\' + signSheet();\n}\n\nfunction tpl5(d){ // 培训教育\n  return \'<h1 class="doc-title">\'+esc(d.c)+\'<br>\'+fill(d.d.split(\'-\')[0])+\'年节后复产专题培训班</div>\' +\n    \'<div class="doc-p" class="no-indent meta">培训时间：\'+fill(d.d)+\'&nbsp;&nbsp;培训地点：\'+fill(d.place)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent meta">培训人数：<span class="fill-empty"></span>人</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>培训主要内容：</b></div>\' +\n    \'<div class="doc-ol"><div class="doc-li">"线上"必修课【安全复工复产第一课】；</div><div class="doc-li">复工复产培训通用培训企业版；</div><div class="doc-li">"一线三排"工作机制、工作指引、实施指南等相关文件；</div><div class="doc-li">其他重要的政策法规及工作要求；</div><div class="doc-li">新员工入职公司级安全生产知识；</div><div class="doc-li">员工安全意识培养和行为安全管理培训教材；</div><div class="doc-li">观看历年警示教育片。</div></div>\' +\n    \'<div class="sign-zone">企业盖章：<br><span style="display:inline-block;margin-top:6px">\'+sealInline(d.c)+\'</span></div>\' +\n    \'<h2 style="margin-top:26px">安全培训教育班情况记录表</div>\' +\n    \'<div class="doc-p" class="no-indent">培训时间：\'+fill(d.d)+\'&nbsp;&nbsp;培训地点：\'+fill(d.place)+\'&nbsp;&nbsp;授课人：\'+fill(d.teacher)+\'</div>\' +\n    \'<div class="photo-holder">现场照片（企业拍摄后上传）</div>\' +\n    \'<div class="doc-h1">安全培训签到表</div>\' + signSheet() +\n    \'<h2 style="margin-top:22px">复工复产培训试卷</div>\' +\n    \'<div class="doc-p" class="no-indent">姓名：<span class="sign-line"></span>&nbsp;&nbsp;分数：<span class="sign-line"></span></div>\' +\n    \'<div class="doc-p" class="no-indent"><b>一、选择题（每题10分，总分60分）</b></div>\' +\n    \'<div class="doc-p" class="no-indent">1.从业人员上岗要求是保证具备必要的安全生产知识。（&nbsp;&nbsp;）A.正确 B.错误</div>\' +\n    \'<div class="doc-p" class="no-indent">2.从业人员具有拒绝违章权。（&nbsp;&nbsp;）A.正确 B.错误</div>\' +\n    \'<div class="doc-p" class="no-indent">3.当发生严重火灾时，应及时拨打119电话。（&nbsp;&nbsp;）A.正确 B.错误</div>\' +\n    \'<div class="doc-p" class="no-indent">4.发生事故时应及时上报领导或者公司。（&nbsp;&nbsp;）A.正确 B.错误</div>\' +\n    \'<div class="doc-p" class="no-indent">5.连续行驶（&nbsp;&nbsp;）小时以上属于疲劳驾驶。A.2 B.3 C.4 D.5</div>\' +\n    \'<div class="doc-p" class="no-indent">6.（多选题）以下属于安全生产"三不违原则"的是（&nbsp;&nbsp;）。A.不违章指挥 B.不违章作业 C.不违反劳动纪律 D.不违反领导的安排</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>二、填空题（每空5分，总分20分）</b></div>\' +\n    \'<div class="doc-p" class="no-indent">1.处理事故的"四不放过"原则指的是&nbsp;&nbsp;&nbsp;&nbsp;不放过、&nbsp;&nbsp;&nbsp;&nbsp;不放过和&nbsp;&nbsp;&nbsp;&nbsp;不放过、&nbsp;&nbsp;&nbsp;&nbsp;不放过。</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>三、判断题（每题4分，总分20分）</b></div>\' +\n    \'<div class="doc-p" class="no-indent">1、灭火器和配电箱前可以随意被遮挡。（&nbsp;&nbsp;）&nbsp;2、员工可以要求企业把劳动防护用品折现成现金或者其它物品。（&nbsp;&nbsp;）</div>\' +\n    \'<div class="doc-p" class="no-indent">3、疏散通道处可以存放物品，只要不影响正常的生产工作。（&nbsp;&nbsp;）&nbsp;4、大多数的安全生产事故是由物的不安全状态造成的。（&nbsp;&nbsp;）</div>\' +\n    \'<div class="doc-p" class="no-indent">5、员工佩不佩戴劳动防护用品无关紧要。（&nbsp;&nbsp;）</div>\';\n}\n\nfunction tpl6(d){ // 应急方案\n  return \'<h1 class="doc-title">\'+esc(d.c)+\'<br>节后复工复产应急处置工作方案</div>\' +\n    \'<div class="doc-p">因春节后复工复产历年来是各类生产安全事故易发多发时期。为深刻吸取历年多起生产安全事故教训，扭转春季事故多发态势，确保全年安全生产形势良好开局，根据区委区政府关于节后复产安全生产工作的部署，结合我司实际，且为认真贯彻落实《安全生产法》《突发事件应对法》《生产安全事故应急条例》《生产安全事故应急预案管理办法》等法律法规要求，有效应对公司生产安全事故发生，进一步提高我公司在春运期间突发事件处理的综合指挥能力、紧急救援反应速度和协调水平，以"安全第一，预防为主，综合治理"的方针，采取措施，加强协调，狠抓落实，努力圆满完成春运复工复产任务，特制定\'+fill(d.d.split(\'-\')[0])+\'年春节后复工复产应急处置工作方案。</div>\' +\n    \'<div class="doc-h1">一、编制依据</div>\' +\n    \'<div class="doc-p">依据《安全生产法》《突发事件应对法》《生产安全事故应急条例》《生产安全事故应急预案管理办法》《企业职工伤亡事故分类》等法律法规，制订本工作方案。</div>\' +\n    \'<div class="doc-h1">二、适用范围</div>\' +\n    \'<div class="doc-p">本应急救援工作方案适用于本公司春运复工复产期间因突发交通事故、消防事故、社会安全事件、自然灾害等原因引发的危及或者损害乘客生命财产安全等及其它公共突发事件。</div>\' +\n    \'<div class="doc-h1">三、应急组织及职责</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（一）成立应急领导小组</b></div>\' +\n    \'<div style="margin-left:3em">\'+leaderBlock(d)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent">应急救援电话：\'+fill(d.t)+\'</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>领导小组职责：</b></div>\' +\n    \'<div class="doc-ol"><div class="doc-li">决定启动和终止突发事件预警状态和应急响应行动；</div><div class="doc-li">负责统一领导突发事件的应急处置工作发布指挥调度命令，并督促检查执行情况；</div><div class="doc-li">根据上级领导部门要求，或根据应急处置需要指定成立现场工作组，并派往突发事件现场开展应急处置工作；</div><div class="doc-li">根据需要，会同上级有关部门，制定应对突发事件的联合行动方案，并监督实施；</div><div class="doc-li">当突发事件由上级领导部门统一指挥时，应急领导小组按照领导部门的指令执行相应的应急行动；</div><div class="doc-li">其他相关重大事项。</div></div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（二）应急工作小组职责：</b></div>\' +\n    \'<div class="doc-p">1、综合协调组：事故发生时，立即奔赴现场进行指挥，组织开展救援工作。</div>\' +\n    \'<div class="doc-p">2、现场抢救组：协调指挥做好救险救援工作，调配消防器材、救援物资，实施抢救，保障乘客安全有序地撤离现场，力争在最短时间、最大限度地补救灾情，减少损失等。</div>\' +\n    \'<div class="doc-p">3、后勤保障组：负责救援工作所需要的办公用品采购，保证补给用品充足，保障一线工作不受影响等。</div>\' +\n    \'<div class="doc-p">4、医疗救护组：负责现场简易的医疗救护，协助医疗救护机构对重伤员的转运工作等。</div>\' +\n    \'<div class="doc-h1">三、应急处理程序</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（一）运营车辆发生交通事故的处理程序：</b></div>\' +\n    \'<div class="doc-p">1、驾驶员应将车辆熄火，切断车辆油电路，防止车辆起火爆炸，向公安交警部门报案，开展应急处置，保护好事故现场，做好救援和疏散乘客工作，并向过往的车辆、行人以及附近的住户求救，并及时向单位报告；</div>\' +\n    \'<div class="doc-p">2、应急领导小组接到通知后，要立即组织车管科人员赶赴事故现场，了解事故情况、分析事故原因，调度指挥车辆输送乘客，协助公安交警、医疗救护、保险等有关部门做好善后处理工作。</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（二）火灾事故的应急处理程序：</b></div>\' +\n    \'<div class="doc-p">1、在灾情附近岗位的员工，确定灾情发生后，马上利用通讯设备报告，报告完毕后必须利用最近的灭火器材赶往灾情现场；</div>\' +\n    \'<div class="doc-p">2、指挥调度组立刻通知现场施救组奔赴现场；</div>\' +\n    \'<div class="doc-p">3、现场施救组到达现场后，展开施救工作；</div>\' +\n    \'<div class="doc-p">4、如果火势较轻，没有涉及乘客安全，财物无大损失，待消防人员扑灭火源后，组长可考虑撤离现场的救援小组，随后必须要总结此次经验教训；</div>\' +\n    \'<div class="doc-p">5、善后处理组拨打火警119、120请求救援，确认联系后，到路口接应消防车、救护车。同时并安排人员封锁现场，指挥人员撤离。对受伤的人员及时救治，对重伤者重点照顾，按救护程序正确处理，等待转送医院的救治；</div>\' +\n    \'<div class="doc-p">6、后勤保障组根据救援现场的需要及时保证所需物资的供给；</div>\' +\n    \'<div class="doc-p">7、火灾扑救完毕后，善后处理组负责现场保护工作，协助公安、消防机关和有关部门调查起火原因，及负责善后处理工作，做好灾情过程的记录和存档。</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（三）发生爆炸事件应急处理程序：</b></div>\' +\n    \'<div class="doc-p">1、发现可疑爆炸物品时，第一发现人及时通知联络协调办公室，联络协调办公室召集消防灭火组赶往现场疏散周围人群，并报告应急救援指挥组组长，并拨打119、120报警，并派专员在路口接应消防人员；</div>\' +\n    \'<div class="doc-p">2、现场施救组穿好防护衣赶往可疑爆炸点封锁现场，迅速准备好消防器材等，减少爆炸引起火灾造成的人员伤亡和建筑的破坏；</div>\' +\n    \'<div class="doc-p">3、现场施救组再安排人员检查附近的是否有可疑爆炸品，发现要即时报告组长及协调联络办公室；</div>\' +\n    \'<div class="doc-p">4、善后处理组抽调工作人员到达现场指挥、维持秩序，其它应急救援小组随时候命；</div>\' +\n    \'<div class="doc-p">5、现场救援组对乘客说明情况，要求不要惊慌，由在场工作人员指引乘客、车辆向安全方向撤离；</div>\' +\n    \'<div class="doc-p">6、发生爆炸后，按火灾事故应急程序操作，配合公安、消防工作人员指挥疏散群众，控制现场，及做好善后工作。</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（四）发生恶劣天气的应急处理程序：</b></div>\' +\n    \'<div class="doc-p">1、出现雨、雪、雾等恶劣天气，领导小组应迅速启动预案，在确定会影响安全行车时，及时发布停运信息，做好监控工作；</div>\' +\n    \'<div class="doc-p">2、加强运输组织工作，储备足够运力，按照上级部门指挥调度要求，配合做好人员运输工作，最大限度降低恶劣天气对公共交通出行的影响；</div>\' +\n    \'<div class="doc-p">3、加强对驾驶人员的应急培训，增强其恶劣天气条件下的行车安全意识。同时做好车辆安全技术检测工作，并应随车配备相关安全设备，确保运输安全。</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（五）发生恐怖事件的应急处理程序：</b></div>\' +\n    \'<div class="doc-p">1、驾驶员要及时启动报警按钮，同时尽量分散恐怖分子注意力，拖延时间；</div>\' +\n    \'<div class="doc-p">2、应急领导小组成员得知恐怖事件发生后，要立即向上级有关部门报告，并配合公安部门处理好；</div>\' +\n    \'<div class="doc-p">3、公安、武警、交通、卫生等部门调派力量到达现场后，应急救援小组各施其职，协助有关部门实施救护，维持秩序。</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（六）发生自然灾害的应急处理程序：</b></div>\' +\n    \'<div class="doc-p">自然灾害发生后，应急领导小组成员应立即到位，及时向上级管理部门报告，服从区政府及有关部门调遣，及时调度车辆运送救灾物资和输送受灾群众，并按灾害破坏程度，及时调整运营服务，避免车辆通过险桥、险路。</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>（六）发生突发性群体上访的处理程序：</b></div>\' +\n    \'<div class="doc-p">1、突发性群体上访事件发生后，应急领导小组成员要及时向区交通运输局汇报，赶赴事发现场，按照行业政策和法规做好解释工作，化解矛盾，运用各种措施、方法、手段防止事态扩大及恶化，使社会负面影响降至最小程度。重大突发性群体事件，按区交通运输局及相关管理部门要求，配合做好现场的协调解决工作；</div>\' +\n    \'<div class="doc-p">2、发生导致国、省道干线公路和城市主要道路中断2小时以上或严重影响到交通秩序和社会稳定的重大突发性群体上访事件时，应急领导小组成员要立即向区交通运输局报告，前往事件现场进行调查，积极协调有关部门进行处理。</div>\' +\n    \'<div class="doc-h1">四、应急救援的要求</div>\' +\n    \'<div class="doc-p" class="no-indent">（一）事故现场急救必须遵循"先救人后救物、先救命后疗伤"的原则；</div>\' +\n    \'<div class="doc-p" class="no-indent">（二）参加现场灭火人员要沉着冷静、遇险不慌、按照"应急要求"执行程序操作；</div>\' +\n    \'<div class="doc-p" class="no-indent">（三）服从命令、听从指挥、坚守岗位，履行职责，做到令行禁止；</div>\' +\n    \'<div class="doc-p" class="no-indent">（四）公安消防机关到达火灾现场后，所有人员要积极主动并服从他们的指挥和安排，协助做好救援和现场警卫等工作。</div>\' +\n    \'<div class="doc-h1">五、应急处置基本原则</div>\' +\n    \'<div class="doc-p">应急处置遵循的原则：以人为本，安全第一；统一领导，分级响应；预防为主，防救结合；快速反应，协同应对；防止次生、衍生灾害，减少人员伤亡和财产损失。</div>\' +\n    \'<div class="doc-h1">六、责任追究</div>\' +\n    \'<div class="doc-p">预案启动后，各部门及全体人员必须听从指挥，无条件立即行动。对拒不行动、见死不救、行动迟缓、贻误时机的人员，要严厉惩罚，触犯法律的，依法交相关部门处理。</div>\' +\n    \'<div class="sign-zone">\' +\n      \'<div>\'+esc(d.c)+\'</div>\' +\n      \'<div style="margin-top:6px">\'+fill(d.d)+\'</div>\' +\n    \'</div>\';\n}\n\nfunction tpl7(d){ // 检查记录表\n  return \'<h1 class="doc-title">\'+esc(d.c)+\'<br>\'+fill(d.d.split(\'-\')[0])+\'年节后复产安全检查记录表</div>\' +\n    \'<table><tr><td style="width:22%">时间</td><td>\'+fill(d.d)+\'</td><td style="width:22%">组织者（带队人）</td><td><span class="sign-line"></span></td></tr>\' +\n    \'<tr><td>检查人员</td><td colspan="3"><span class="sign-line" style="width:70%"></span></td></tr>\' +\n    \'<tr><td>检查区域</td><td colspan="3"><span class="sign-line" style="width:70%"></span></td></tr></table>\' +\n    \'<div class="doc-p" class="no-indent"><b>检查发现问题：</b></div><div class="doc-p">1.<br>2.<br>3.<br>4.<br>5.</div>\' +\n    \'<div class="doc-p" class="no-indent"><b>整改措施：</b></div><div class="doc-p">1.<br>2.<br>3.<br>4.<br>5.</div>\' +\n    \'<div class="doc-p" class="no-indent">整改责任人（签名）：<span class="sign-line"></span>&nbsp;&nbsp;落实整改时间：<span class="sign-line"></span></div>\' +\n    \'<div class="doc-p" class="no-indent"><b>复查结论：</b></div><div class="doc-p">1.<br>2.<br>3.<br>4.<br>5.</div>\' +\n    \'<div class="doc-p" class="no-indent">复查人签字：<span class="sign-line"></span>&nbsp;&nbsp;复查时间：<span class="sign-line"></span></div>\' +\n    \'<div class="doc-h1">检查项目清单（在□打"√"）</div>\' +\n    checkTable();\n}\n\nfunction checkTable(){\n  const rows = [\n    [\'安全设施\',\'消防设备齐全、摆放整齐、性能良好\',\'消防通道畅通\',\'疏散指示标志、应急照明完好\',\'有应急预案，车辆设施完好齐全\'],\n    [\'建筑物\',\'建筑结构无变形、裂缝等现象\',\'室内顶棚完好\'],\n    [\'厂区环境\',\'厂貌整洁，布局合理\',\'厂区通道照明，厂区消防、消防通道符合要求\'],\n    [\'车间作业环境\',\'实行定置摆放\',\'车间通道、地面、通风、采光消防及疏散、设备布局合理\'],\n    [\'电气设备\',\'无乱拉、乱接临时线、临时灯行为\',\'带电部位屏护正常\'],\n    [\'易燃物品材料场所\',\'料场堆放整齐稳定可靠，道路畅通\',\'在入口及重点位置设置了防火安全标志\',\'消防设施齐全完备，电器设备符合要求，防火间距达到要求\'],\n    [\'劳动保护\',\'按规定为员工配备劳动防护用品\',\'职业卫生符合国家规定的标准\'],\n    [\'机械设备\',\'建立机械设备及其各种保护装置使用管理制度\',\'定期进行机械设备及其各种保护装置安全检查和维修保养\',\'对机械设备及其各种保护装置进行班前检查\',\'操作者经培训合格\',\'机械设备其运动（转动）部件、传动（传输）装置安装有防护装置\'],\n    [\'用电安全\',\'电器设备、电源线路由专业施工队安装、敷设\',\'内有增大电气装置的额定容量\',\'没有任意改动保护装置的整定值和保护元件的规格\',\'电气装置没有超负荷运行或带故障使用\',\'在用电设备和电气线路的周围留有足够的安全通道和工作空间\'],\n    [\'照明配电箱（柜、板）\',\'箱(柜、板）符合作业要求，内外整洁\',\'有足够的操作空间，PE可靠\',\'各种原件及线路接触良好，保护装置齐全\'],\n    [\'危险化学品\',\'化学危险品物品标识\',\'分类、分开堆放\',\'稳固、无超高、无倾斜\',\'防漏措施、应急措施\'],\n    [\'仓库\',\'环境、建筑符合仓库要求\',\'物品分类、分开、分库存放\',\'物料摆放整齐、合理\',\'物料堆放无超高、五距符合要求\',\'消防器材、器材分布合理\'],\n    [\'有限空间作业\',\'对有限空间作业场所进行辨识，并建立完善有限空间管理台帐\',\'在辨识出的有限空间作业场所或设备附近设置警示标志和危险告知牌\',\'配备合格的有限空间作业检测、通风、应急救援等安全设施设备\'],\n    [\'动火作业\',\'持证上岗，清理可燃物，防火防爆，测爆，安全距离，监护\',\'先审批、派监护、安全措施要到位\'],\n    [\'高处作业\',\'个体防护（安全帽、安全带），工具包、杂物箱等，脚手架检查，监护\',\'高处作业严禁上下抛物\'],\n    [\'吊装作业\',\'吊具检查，持证及人员能力，作业过程中管理\',\'当起重、吊钩或吊物下面有人时不得进行起重操作\'],\n  ];\n  let html = \'<table><tr><th style="width:16%">检查项目</th><th>检查内容</th><th style="width:18%">检查情况</th><th style="width:14%">存在问题</th></tr>\';\n  rows.forEach(function(r){\n    const cat = r[0], items = r.slice(1);\n    html += \'<tr><td rowspan="\'+items.length+\'">\'+cat+\'</td><td style="text-align:left">\'+items[0]+\'</td><td>□是 □否</td><td></td></tr>\';\n    for(let i=1;i<items.length;i++){\n      html += \'<tr><td style="text-align:left">\'+items[i]+\'</td><td>□是 □否</td><td></td></tr>\';\n    }\n  });\n  html += \'</table>\';\n  return html;\n}\n\nfunction signSheet(){\n  let html = \'<table><tr><th style="width:12%">序号</th><th style="width:20%">部门</th><th style="width:30%">签到</th><th>联系电话</th><th style="width:12%">序号</th><th style="width:20%">部门</th><th style="width:30%">签到</th><th>联系电话</th></tr>\';\n  for(let i=1;i<=15;i++){\n    html += \'<tr><td>\'+i+\'</td><td></td><td></td><td></td><td>\'+(i+15)+\'</td><td></td><td></td><td></td></tr>\';\n  }\n  html += \'</table>\';\n  return html;\n}\n\nconst TPLS = { \'1\': tpl1, \'2\': tpl2, \'3\': tpl3, \'4\': tpl4, \'5\': tpl5, \'6\': tpl6, \'7\': tpl7 };\n\nfunction renderAll(){\n  const d = D();\n  const fn = TPLS[curTab] || tpl1;\n  document.getElementById(\'paper\').innerHTML = fn(d);\n}\n\nfunction switchTab(t){\n  curTab = t;\n  document.querySelectorAll(\'.tab\').forEach(function(b){ b.classList.toggle(\'active\', b.dataset.t === t); });\n  renderAll();\n}\n\nfunction resetData(){\n  document.getElementById(\'company_name\').value = \'广东佳邦通达物流有限公司\';\n  document.getElementById(\'tel\').value = \'18923277715\';\n  document.getElementById(\'leader_name\').value = \'柴国顺\';\n  document.getElementById(\'deputy_names\').value = \'韩雪\';\n  document.getElementById(\'member_names\').value = \'陈秀清\';\n  document.getElementById(\'resume_date\').value = \'2026-02-24\';\n  document.getElementById(\'place\').value = \'办公室\';\n  document.getElementById(\'teacher\').value = \'柴国顺\';\n  renderAll();\n}\n\nrenderAll();\n</script>',1,1,'v1.0 内置',1,0),
(4235,0,4001,0,'EMERGENCY_PLAN','生产安全事故应急预案（普货通用版）','预案','BOX7','应急预案',7,'','<div class="doc-h0">生产安全事故应急预案</div>\n<div class="doc-p">{{公司名称}}</div>\n<div class="doc-h0">生产安全事故应急预案</div>\n<div class="doc-p">编制单位：{{公司名称}}</div>\n<div class="doc-p">发布日期：{{发布日期}}</div>\n<div class="doc-p">实施日期：{{实施日期}}</div>\n<div class="doc-h1">{{公司名称}} 关于成立应急预案编制（修订）小组的通知</div>\n<div class="doc-p">各部门、各岗位：</div>\n<div class="doc-p">为做好公司生产安全事故应急预案的编制（修订）工作，根据《生产安全事故应急预案管理办法》第十条的规定，经公司研究，决定成立应急预案编制（修订）小组。现将有关事项通知如下：</div>\n<div class="doc-p">**一、编制小组组成**</div>\n<div class="doc-p">组　长：{{主要负责人}}（总经理）</div>\n<div class="doc-p">副组长：{{安全管理员}}（安全管理员）</div>\n<div class="doc-p">组　员：{{车队长}}（车队长、{{监控员}}监控员）</div>\n<div class="doc-p">**二、职责分工**</div>\n<div class="doc-p">（一）组长：负责组织成立编制小组，确定编制原则和工作计划，审定预案内容，批准预案的发布与实施。</div>\n<div class="doc-p">（二）副组长：负责组织事故风险评估和应急资源调查，起草预案文本，组织征求意见和评审，汇总修改意见。</div>\n<div class="doc-p">（三）组员：负责提供车辆、人员、线路和现场处置方面的资料，参与风险评估和预案讨论，配合开展培训演练。</div>\n<div class="doc-p">**三、工作要求**</div>\n<div class="doc-p">编制小组应当依据《生产经营单位生产安全事故应急预案编制导则》（GB/T 29639—2020），在事故风险评估和应急资源调查的基础上编制预案，做到符合企业实际、简明实用、可操作。</div>\n<div class="doc-p">特此通知。</div>\n<div class="doc-p">{{公司名称}}</div>\n<div class="doc-p">{{发布日期}}</div>\n<div class="doc-h1">编 制 说 明</div>\n<div class="doc-p">为认真贯彻落实《中华人民共和国突发事件应对法》《中华人民共和国安全生产法》《生产安全事故应急条例》《生产安全事故报告和调查处理条例》《生产安全事故应急预案管理办法》《生产过程危险和有害因素分类与代码》《中华人民共和国道路运输条例》《道路货物运输及站场管理规定》《中华人民共和国消防法》《机关、团体、企业、事业单位消防安全管理规定》《企业职工伤亡事故分类标准》等法律法规要求，有效应对公司生产安全事故发生，最大程度减少事故人员伤亡及财产损失，公司成立了以总经理为编制组组长、安全负责人为主要编制负责人的生产安全事故应急预案编制小组。</div>\n<div class="doc-p">小组依据《生产经营单位生产安全事故应急预案编制导则》标准要求，在对公司基础资料收集、事故风险辨识评估和应急资源调查等的基础上编制本预案，本预案由总经理签字发布后在公司范围内实施。</div>\n<div class="doc-p">本预案应在相关法律法规等发生重大变化、应急指挥机构职责发生重大变化、公司安全风险发生重大变化、重要应急资源发生重大变化以及在应急演练或事故救援中发现重大问题等情况时进行修订归档，实现持续改进。</div>\n<div class="doc-p">{{公司名称}}</div>\n<div class="doc-p">{{发布日期}}</div>\n<div class="doc-h1">发 布 令</div>\n<div class="doc-p">《{{公司名称}}生产安全事故应急预案》已经公司安全生产领导小组审定，现予发布，自{{实施日期}}起实施。</div>\n<div class="doc-p">公司全体从业人员应当认真学习、严格执行本预案，熟悉本岗位的应急职责、处置程序和报告要求，确保事故发生时能够迅速、有序、有效处置。</div>\n<div class="doc-p">批准人（签字）：</div>\n<div class="doc-p">{{公司名称}}</div>\n<div class="doc-p">{{发布日期}}</div>\n<div class="doc-h0">第一篇　生产安全事故综合应急预案</div>\n<div class="doc-h1">1　总则</div>\n<div class="doc-h2">1.1　编制目的</div>\n<div class="doc-p">为规范公司生产安全事故应急管理工作，提高对道路货物运输过程中突发事故的处置能力，在事故发生后能够迅速控制事态、抢救受伤人员、减少财产损失和社会影响，结合公司实际，制定本预案。</div>\n<div class="doc-h2">1.2　编制依据</div>\n<div class="doc-p">《中华人民共和国安全生产法》《中华人民共和国突发事件应对法》《生产安全事故应急条例》《生产安全事故报告和调查处理条例》《生产安全事故应急预案管理办法》（应急管理部令第2号）、《生产经营单位生产安全事故应急预案编制导则》（GB/T 29639—2020）、《中华人民共和国道路运输条例》《道路货物运输及站场管理规定》《道路运输车辆技术管理规定》《道路运输车辆动态监督管理办法》等法律法规和标准规范。</div>\n<div class="doc-h2">1.3　适用范围</div>\n<div class="doc-p">本预案适用于公司{{车辆数}}辆营运车辆（{{车辆清单}}）在运营过程中发生的道路交通事故、车辆火灾、恶劣天气受阻、货物损失、人员伤亡等生产安全事故，以及办公场所火灾等突发事件的预防、预警、响应和处置。</div>\n<div class="doc-p">公司持有道路普通货物运输经营许可，主要承运{{主营货物}}等普通货物，不从事危险货物运输，不涉及重大危险源。</div>\n<div class="doc-h2">1.4　响应分级</div>\n<div class="doc-p">根据事故造成的人员伤亡和直接经济损失，公司生产安全事故应急响应分为两级。</div>\n<div class="doc-p">**表1-1　生产安全事故应急响应分级表**</div>\n<div class="doc-p">说明：1.上述伤亡人数和损失金额中的"以上"含本数。2.Ⅱ级响应处置过程中，出现人员伤情恶化、损失扩大或者可能构成Ⅰ级情形的，现场指挥应当立即报告总指挥，按程序升级为Ⅰ级响应。3.事故等级最终以属地人民政府事故调查组的认定为准。</div>\n<div class="doc-h2">1.5　预案体系</div>\n<div class="doc-p">公司生产安全事故应急预案体系由综合应急预案（第一篇）、专项应急预案（第二篇）、现场处置方案（第三篇）和附件（第四篇）组成。本预案向上与属地人民政府突发事件总体应急预案、交通运输主管部门应急预案相衔接，向下与各专项应急预案、现场处置方案相衔接。当公司应急能力不足以控制事故时，应当及时向属地交通运输、应急管理部门报告，请求启动上级预案。</div>\n<div class="doc-h1">2　应急组织机构及职责</div>\n<div class="doc-h2">2.1　应急组织体系</div>\n<div class="doc-p">公司成立生产安全事故应急救援指挥部（以下简称指挥部），下设应急管理办公室和现场处置组、警戒疏散组、医疗救护组、通讯联络与后勤保障组4个应急工作组。公司实行"一人多岗、一岗多责"，各组组长可相互兼任，事故发生时按现场统一调度开展处置。</div>\n<div class="doc-p">**表2-1　应急救援指挥部组成及联系方式**</div>\n<div class="doc-h2">2.2　指挥部职责</div>\n<div class="doc-p">（1）组织编制、修订公司生产安全事故应急预案，审定预案并组织发布。</div>\n<div class="doc-p">（2）决定启动和终止应急响应，确定现场指挥人员。</div>\n<div class="doc-p">（3）统一指挥事故现场应急处置，决定人员、车辆、物资的调配。</div>\n<div class="doc-p">（4）决定向属地交通运输、应急管理等部门报告和请求外部支援。</div>\n<div class="doc-p">（5）组织事故调查处理、善后处置和整改落实。</div>\n<div class="doc-p">（6）组织应急预案的培训、演练和评估。</div>\n<div class="doc-h2">2.3　应急管理办公室职责</div>\n<div class="doc-p">应急管理办公室设在公司办公室，主任由安全管理员兼任，实行24小时应急值守。主要职责：</div>\n<div class="doc-p">（1）负责应急值守和事故信息接报，第一时间报告总指挥。</div>\n<div class="doc-p">（2）负责按规定时限向属地交通运输、应急管理部门报告事故信息，并做好续报。</div>\n<div class="doc-p">（3）负责应急物资、装备的日常管理和检查。</div>\n<div class="doc-p">（4）负责应急值守记录、事故处置记录和资料归档。</div>\n<div class="doc-p">（5）承担指挥部交办的其他工作。</div>\n<div class="doc-h2">2.4　应急工作组职责</div>\n<div class="doc-li">1. 现场处置组（组长：安全管理员）。负责事故现场先期处置，设置警示、切断危险源、抢救伤员、转移货物、保护现场；配合交警、消防救援、医疗急救人员开展处置；负责事故现场拍照、录像和证据留存。</div>\n<div class="doc-li">2. 警戒疏散组（组长：车队长）。负责事故现场警戒区域的划定和警戒设施设置，疏导过往车辆和行人，防止二次事故；负责引导外部救援车辆进入现场；负责事故现场周围火源管控。</div>\n<div class="doc-li">3. 医疗救护组（组长：车队长兼）。负责对受伤人员的现场急救、止血包扎和保暖，协助120医护人员转运伤员，做好伤员信息登记和家属通知。</div>\n<div class="doc-li">4. 通讯联络与后勤保障组（组长：安全管理员兼）。负责内外通讯联络、信息传递和记录；负责应急车辆、物资、经费和饮食等后勤保障；负责伤员家属接待和善后事务。</div>\n<div class="doc-h2">2.5　应急值守</div>\n<div class="doc-p">公司实行24小时应急值守，值守电话{{值守电话}}，由安全管理员负责接听和记录。驾驶员在营运过程中发生事故或者发现重大隐患，应当立即报告公司值守电话；情况紧急时可以先报警、后报告公司。</div>\n<div class="doc-h1">3　应急响应</div>\n<div class="doc-p">（图3-1　应急响应流程图，略）</div>\n<div class="doc-h2">3.1　信息报告</div>\n<div class="doc-p">**3.1.1　信息接报**</div>\n<div class="doc-p">事故发生后，驾驶员应当在确保自身安全的前提下，第一时间通过电话向公司24小时值守电话报告；公司任何人员接到事故报告，应当立即转报应急管理办公室，不得延误、不得瞒报。</div>\n<div class="doc-p">**3.1.2　报告内容**</div>\n<div class="doc-p">报告应当包括以下内容：事故发生的时间、地点（路段、方向、里程）；车辆号牌、车型、装载货物名称和数量；事故类型（碰撞、追尾、侧翻、起火、坠水等）；人员伤亡情况；现场道路、天气和交通状况；已采取的措施和需要的支援。</div>\n<div class="doc-p">**3.1.3　事故上报**</div>\n<div class="doc-p">（1）发生Ⅰ级事故的，公司应当在30分钟内向属地交通运输、应急管理部门口头报告，1小时内书面报告；情况发生变化的，及时续报。</div>\n<div class="doc-p">（2）发生Ⅱ级事故的，按规定需要报告的，在24小时内向属地交通运输部门报告；涉及人员受伤的，按Ⅰ级事故报告时限执行。</div>\n<div class="doc-p">（3）事故报告后出现新情况，或者伤亡人数发生变化的，应当在24小时内补报。</div>\n<div class="doc-p">（4）任何人不得迟报、漏报、谎报或者瞒报事故。</div>\n<div class="doc-p">（图3-2　事故信息上报流程图，略）</div>\n<div class="doc-h2">3.2　预警</div>\n<div class="doc-p">（1）预警信息来源：气象部门发布的台风、暴雨、大雾、道路结冰等预警信息；交通运输主管部门发布的路况和风险提示；车辆动态监控平台报警信息；车辆日常检查和维护保养中发现的问题。</div>\n<div class="doc-p">（2）预警发布：安全管理员接到预警信息后，通过电话、微信工作群等方式通知驾驶员和管理人员，明确防范措施和要求。</div>\n<div class="doc-p">（3）预警行动：遇恶劣天气预警，暂停发车或者调整运输线路；遇车辆技术状况异常，立即停运检修；遇驾驶员身体不适或者疲劳，及时调整驾驶任务。</div>\n<div class="doc-p">（4）预警解除：预警信息解除或者风险消除后，由安全管理员发布解除通知，恢复正常运营。</div>\n<div class="doc-h2">3.3　响应启动</div>\n<div class="doc-p">**3.3.1　Ⅰ级响应**</div>\n<div class="doc-p">（1）接报后，应急管理办公室立即报告总指挥，总指挥宣布启动Ⅰ级响应。</div>\n<div class="doc-p">（2）总指挥、副总指挥和相关人员立即赶赴现场（不能到场的，通过电话指挥）。</div>\n<div class="doc-p">（3）现场处置组到达后立即开展先期处置：设置警示、抢救伤员、控制危险源、保护现场。</div>\n<div class="doc-p">（4）同时拨打122、120、119报警求助，并向属地交通运输、应急管理部门报告。</div>\n<div class="doc-p">（5）通知伤员家属，安排人员陪同处置。</div>\n<div class="doc-p">（6）必要时停止公司全部车辆营运，配合事故调查处理。</div>\n<div class="doc-p">（7）事故处置完毕后，总指挥宣布终止响应，转入后期处置。</div>\n<div class="doc-p">**3.3.2　Ⅱ级响应**</div>\n<div class="doc-p">（1）接报后，应急管理办公室报告副总指挥，由副总指挥（安全管理员）指挥处置。</div>\n<div class="doc-p">（2）根据事故类型启动相应的现场处置方案（见第三篇）。</div>\n<div class="doc-p">（3）现场需要支援的，调度公司其他人员和车辆赶赴现场。</div>\n<div class="doc-p">（4）按规定向属地交通运输部门报告。</div>\n<div class="doc-p">（5）处置结束后3日内完成总结，报总指挥审阅。</div>\n<div class="doc-h2">3.4　应急处置</div>\n<div class="doc-p">（1）立即停车。发生事故后立即停车、熄火、拉紧驻车制动、开启危险报警闪光灯；夜间或者能见度低时同时开启示廓灯和后位灯。</div>\n<div class="doc-p">（2）设置警示。在来车方向按规定距离设置三角警告牌（普通道路50至100米，高速公路150米以外），人员撤离至护栏外或者路肩安全位置。</div>\n<div class="doc-p">（3）抢救伤员。在确保自身安全的前提下，对受伤人员实施止血、包扎、固定等现场急救；伤情不明的不得随意搬动，等待120处置。</div>\n<div class="doc-p">（4）控制危险。车辆起火时立即使用灭火器扑救初起火灾，火势较大时撤离并报警；货物散落时设置警示并组织清理，防止引发二次事故。</div>\n<div class="doc-p">（5）保护现场。在交警到达前保护事故现场，因抢救伤员需要移动现场物件的，应当标明位置并拍照留存。</div>\n<div class="doc-p">（6）报告公司。按本预案3.1的要求报告事故信息。</div>\n<div class="doc-p">（7）保护货物。货物散落、受损或者车辆长时间滞留的，应当及时报告公司安排转运，减少货物损失，防止引发二次事故。</div>\n<div class="doc-h2">3.5　应急支援</div>\n<div class="doc-p">（1）公司应急力量不足以控制事故时，由总指挥决定向属地交通运输、应急管理、公安交管、消防救援、医疗急救等部门请求支援。</div>\n<div class="doc-p">（2）与周边运输企业建立的应急协作关系，可以在车辆、人员、救援器材等方面提供互助支援。</div>\n<div class="doc-p">（3）外部救援力量到达现场后，公司现场人员应当服从统一指挥，如实介绍事故情况，配合开展救援。</div>\n<div class="doc-h2">3.6　响应终止</div>\n<div class="doc-p">符合下列条件的，由总指挥宣布终止应急响应：</div>\n<div class="doc-p">（1）事故现场人员已经全部救出，伤员已经得到救治或者转运。</div>\n<div class="doc-p">（2）车辆、货物等危险源已经得到控制，次生、衍生事故隐患已经消除。</div>\n<div class="doc-p">（3）现场已经移交公安交管等部门，或者善后处置已经作出安排。</div>\n<div class="doc-h1">4　后期处置</div>\n<div class="doc-p">（1）伤员救治与赔偿。安排专人负责伤员救治的跟踪和费用保障，依法依规做好工伤认定、保险理赔和赔偿协商。</div>\n<div class="doc-p">（2）现场清理。配合有关部门清理事故现场，转移货物，拖离事故车辆，恢复道路通行。</div>\n<div class="doc-p">（3）保险理赔。及时向承保的保险公司报案，收集整理事故认定书、医疗票据、维修发票等理赔资料。</div>\n<div class="doc-p">（4）事故调查。配合属地人民政府事故调查组开展调查，如实提供车辆技术档案、动态监控数据、驾驶员从业资格证、安全教育培训记录等资料。</div>\n<div class="doc-p">（5）整改落实。针对事故暴露的问题制定整改措施，明确责任人和完成时限，实行销号管理。</div>\n<div class="doc-p">（6）恢复运营。事故车辆经维修并检验合格后方可恢复营运，驾驶员经安全教育和心理疏导后方可重新上岗。</div>\n<div class="doc-h1">5　应急保障</div>\n<div class="doc-h2">5.1　通信保障</div>\n<div class="doc-p">公司建立应急通讯录（见附件2），明确总指挥、副总指挥、驾驶员以及外部救援单位的联系方式，并确保24小时通讯畅通。应急管理办公室负责通讯录的更新维护。</div>\n<div class="doc-h2">5.2　应急队伍</div>\n<div class="doc-p">公司应急救援队伍由全体从业人员组成，其中现场处置组不少于2人、警戒疏散组不少于1人。人员发生变动时，应当及时调整并组织交底。</div>\n<div class="doc-h2">5.3　物资装备保障</div>\n<div class="doc-p">按附件4配备应急物资装备，由安全管理员负责日常管理和每月检查一次，确保完好有效；灭火器按规定定期检验，失效的及时更换；物资使用后及时补充。</div>\n<div class="doc-h2">5.4　经费保障</div>\n<div class="doc-p">公司按规定提取和使用安全生产费用，保障应急物资采购、应急演练、培训、事故救援和善后处置等费用支出。</div>\n<div class="doc-h1">6　培训与演练</div>\n<div class="doc-p">（1）公司每年组织不少于2次应急知识培训，内容包括本预案、现场处置方案、报警程序、现场急救和消防器材使用，培训情况记入培训档案。</div>\n<div class="doc-p">（2）新入职驾驶员上岗前应当接受应急预案和现场处置方案培训，考核合格后方可上岗。</div>\n<div class="doc-p">（3）公司每年至少组织1次综合或者专项应急演练，每半年至少组织1次现场处置方案演练；演练可以采取实战演练、桌面推演等方式。</div>\n<div class="doc-p">（4）演练结束后应当进行评估总结，形成评估报告，针对发现的问题修订预案、改进措施。</div>\n<div class="doc-h1">7　预案管理</div>\n<div class="doc-p">（1）本预案由公司应急预案编制（修订）小组组织编制，经公司主要负责人审定、签署发布后实施，并按规定报属地交通运输主管部门备案；同时针对驾驶员岗位编制简明实用的应急处置卡，随车携带。</div>\n<div class="doc-p">（2）预案编制完成后，公司应当组织有关人员进行评审，形成书面评审记录，评审意见作为修改完善预案的依据。</div>\n<div class="doc-p">（3）有下列情形之一的，应当及时修订预案：所依据的法律法规、标准规范发生变化；公司经营范围、车辆数量、人员或者组织机构发生较大变化；应急预案演练或者事故处置中发现预案存在重大问题；属地交通运输、应急管理部门提出整改要求。</div>\n<div class="doc-p">（4）预案修订后应当重新发布，并组织全员培训。</div>\n<div class="doc-p">（5）对在应急处置中表现突出的人员给予表彰奖励；对不履行职责、延误处置造成损失扩大的，依照公司规定追究责任。</div>\n<div class="doc-h0">第二篇　专项应急预案</div>\n<div class="doc-h1">1　道路交通事故专项应急预案</div>\n<div class="doc-h2">1.1　事故风险分析</div>\n<div class="doc-p">公司营运车辆主要在{{主要线路}}运行，事故类型以追尾、碰撞、刮擦、侧翻为主，多发生在路口、匝道、变道、超车和雨雾天气时段；可能造成人员伤亡、车辆损坏、货物损失和道路拥堵。严重时还可能引发车辆起火、货物散落、坠水等次生事故。</div>\n<div class="doc-h2">1.2　应急组织与职责</div>\n<div class="doc-p">发生道路交通事故，按第一篇第2章确定的组织机构开展处置，现场处置组负责先期处置和伤员抢救，警戒疏散组负责设置警示和疏导交通，医疗救护组负责伤员急救和转运，通讯联络与后勤保障组负责报警、报告和后勤保障。</div>\n<div class="doc-h2">1.3　处置程序</div>\n<div class="doc-p">（1）立即停车、开启危险报警闪光灯，在来车方向按规定距离设置三角警告牌；</div>\n<div class="doc-p">（2）查看人员伤亡和车辆、货物损失情况；</div>\n<div class="doc-p">（3）拨打122报警、120急救，同时报告公司；</div>\n<div class="doc-p">（4）抢救伤员、控制危险源、保护现场；</div>\n<div class="doc-p">（5）配合交警勘查，如实提供行驶证、道路运输证、从业资格证和动态监控数据；</div>\n<div class="doc-p">（6）按公司指令做好后续处置。</div>\n<div class="doc-h2">1.4　处置措施</div>\n<div class="doc-p">（1）车辆能够移动且不影响安全的，拍照取证后将车辆移至不妨碍交通的地点；</div>\n<div class="doc-p">（2）车辆无法移动的，持续做好警示，人员撤至安全位置；</div>\n<div class="doc-p">（3）有人员被困的，立即拨打119、120，不得强行破拆；</div>\n<div class="doc-p">（4）车辆侧翻的，先确认货物是否稳定，防止二次倾倒；</div>\n<div class="doc-p">（5）车辆坠水的，按第三篇车辆涉水现场处置方案执行；</div>\n<div class="doc-p">（6）货物散落、受损的，应当设置警示、组织清理，及时报告公司安排转运，减少货物损失。</div>\n<div class="doc-h2">1.5　注意事项</div>\n<div class="doc-p">（1）处置过程中首先保证自身安全，严禁在车流中停留；</div>\n<div class="doc-p">（2）不得随意移动伤员，防止加重伤情；</div>\n<div class="doc-p">（3）不得与对方当事人发生冲突，一切听从交警处理；</div>\n<div class="doc-p">（4）未经允许不得离开事故现场。</div>\n<div class="doc-h1">2　车辆火灾事故专项应急预案</div>\n<div class="doc-h2">2.1　事故风险分析</div>\n<div class="doc-p">车辆火灾主要由电路短路、线路老化、轮胎过热、货物自燃或者碰撞后油路破损引起，多发生在行驶途中或者停放期间，可能造成车辆烧毁、货物损失和人员烧伤，并可能引燃周边车辆和建筑物。</div>\n<div class="doc-h2">2.2　应急组织与职责</div>\n<div class="doc-p">现场处置组负责初起火灾扑救和人员疏散，警戒疏散组负责设置警戒、疏散周边人员和车辆，医疗救护组负责烧伤人员急救，通讯联络与后勤保障组负责报警和报告。</div>\n<div class="doc-h2">2.3　处置程序</div>\n<div class="doc-p">（1）立即靠边停车、熄火、切断电源，组织车上人员迅速下车撤离；</div>\n<div class="doc-p">（2）拨打119报警并报告公司；</div>\n<div class="doc-p">（3）在确保安全的前提下使用随车灭火器扑救初起火灾；</div>\n<div class="doc-p">（4）火势蔓延或者有爆炸危险的，立即撤离至安全距离以外，禁止靠近；</div>\n<div class="doc-p">（5）配合消防救援人员处置，说明货物性质和车辆情况。</div>\n<div class="doc-h2">2.4　注意事项</div>\n<div class="doc-p">（1）严禁在车辆起火后返回车内取物；</div>\n<div class="doc-p">（2）油箱、气瓶附近着火时不得盲目靠近；</div>\n<div class="doc-p">（3）扑救时站在上风方向，注意自身防护；</div>\n<div class="doc-p">（4）火灭后仍需观察，防止复燃。</div>\n<div class="doc-h1">3　恶劣天气专项应急预案</div>\n<div class="doc-h2">3.1　事故风险分析</div>\n<div class="doc-p">台风、暴雨、大雾、道路结冰、高温等恶劣天气会降低道路通行条件和车辆操控性能，容易引发追尾、侧滑、失控、涉水熄火等事故。</div>\n<div class="doc-h2">3.2　预警与响应</div>\n<div class="doc-p">（1）安全管理员接到气象预警后，及时通知驾驶员，评估是否暂停发车；</div>\n<div class="doc-p">（2）发布台风、暴雨红色预警或者道路结冰预警的，暂停运输任务；</div>\n<div class="doc-p">（3）运输途中遇恶劣天气的，就近选择安全地点停车避险，不得强行通行；</div>\n<div class="doc-p">（4）大雾天气开启雾灯、危险报警闪光灯，降低车速，加大跟车距离；</div>\n<div class="doc-p">（5）暴雨天气避开积水路段和低洼地带，不得贸然涉水。</div>\n<div class="doc-h2">3.3　处置措施</div>\n<div class="doc-p">（1）车辆被困的，人员先撤离至安全地带并报警；</div>\n<div class="doc-p">（2）车辆涉水的，按第三篇车辆涉水现场处置方案执行；</div>\n<div class="doc-p">（3）车辆故障无法行驶的，按规定设置警示并报告公司，等待救援。</div>\n<div class="doc-h0">第三篇　现场处置方案</div>\n<div class="doc-h1">1　车辆碰撞（追尾、刮擦）事故现场处置方案</div>\n<div class="doc-h2">1.1　风险分析</div>\n<div class="doc-p">多发生在路口、匝道、变道、跟车过近和雨雾天气，可能造成人员受伤、车辆损坏、货物散落和道路拥堵。</div>\n<div class="doc-h2">1.2　应急工作职责</div>\n<div class="doc-p">驾驶员负责现场先期处置、设置警示、报警和报告公司；随车人员协助设置警示、抢救伤员和看护货物；公司应急管理办公室负责接报、报告和调度支援。</div>\n<div class="doc-h2">1.3　处置步骤</div>\n<div class="doc-p">（1）立即停车、熄火、开启危险报警闪光灯；</div>\n<div class="doc-p">（2）在来车方向50至100米（高速公路150米以外）设置三角警告牌；</div>\n<div class="doc-p">（3）人员撤离至护栏外或者路肩；</div>\n<div class="doc-p">（4）查看伤亡情况，拨打122、120；</div>\n<div class="doc-p">（5）报告公司值守电话；</div>\n<div class="doc-p">（6）抢救伤员、保护现场、拍照取证；</div>\n<div class="doc-p">（7）配合交警处理。</div>\n<div class="doc-h2">1.4　注意事项</div>\n<div class="doc-p">不得在车道内停留；不得随意移动伤员；不得擅自离开现场；不得与对方发生冲突。</div>\n<div class="doc-h1">2　车辆起火现场处置方案</div>\n<div class="doc-h2">2.1　风险分析</div>\n<div class="doc-p">电路短路、线路老化、货物自燃、碰撞后油路破损等引起，可能造成车辆烧毁和人员烧伤。</div>\n<div class="doc-h2">2.2　应急工作职责</div>\n<div class="doc-p">驾驶员负责停车断电、组织人员撤离、报警和初起火灾扑救；随车人员协助疏散和报警；公司应急管理办公室负责接报、报告和协调救援。</div>\n<div class="doc-h2">2.3　处置步骤</div>\n<div class="doc-p">（1）靠边停车、熄火、切断电源，人员迅速下车；</div>\n<div class="doc-p">（2）拨打119并报告公司；</div>\n<div class="doc-p">（3）使用随车干粉灭火器对准火焰根部喷射；</div>\n<div class="doc-p">（4）火势无法控制时立即撤离至安全距离以外；</div>\n<div class="doc-p">（5）引导消防车辆进入，说明货物情况。</div>\n<div class="doc-h2">2.4　注意事项</div>\n<div class="doc-p">严禁返回车内取物；不得盲目靠近油箱；站在上风方向；防止复燃。</div>\n<div class="doc-h1">3　车辆涉水、坠水现场处置方案</div>\n<div class="doc-h2">3.1　风险分析</div>\n<div class="doc-p">暴雨积水、漫水桥、临水临崖路段易发生车辆涉水熄火、被困或者坠水，可能造成人员溺水和车辆损坏。</div>\n<div class="doc-h2">3.2　应急工作职责</div>\n<div class="doc-p">驾驶员负责判断险情、组织车内人员逃生和报警；随车人员协助破窗、呼救；公司应急管理办公室负责接报、报告和联系救援力量。</div>\n<div class="doc-h2">3.3　处置步骤</div>\n<div class="doc-p">（1）车辆能继续行驶的，尽快驶离积水区域；</div>\n<div class="doc-p">（2）车辆熄火无法移动的，立即解锁车门、降下车窗，组织人员撤离；</div>\n<div class="doc-p">（3）车门无法打开的，使用安全锤或者硬物击碎侧窗玻璃逃生；</div>\n<div class="doc-p">（4）人员撤离后立即拨打110、122、119报警并报告公司；</div>\n<div class="doc-p">（5）不会游泳的人员抓住漂浮物等待救援，不得盲目下水施救。</div>\n<div class="doc-h2">3.4　注意事项</div>\n<div class="doc-p">车内应常备破窗工具；不得贸然驶入情况不明的积水路段；救援时先保证自身安全。</div>\n<div class="doc-h1">4　货物散落、受损现场处置方案</div>\n<div class="doc-h2">4.1　风险分析</div>\n<div class="doc-p">车辆碰撞、侧翻、急刹车、货物捆扎不牢或者超限超载等，均可能造成货物散落、坠落、受损，影响道路通行，引发二次事故，并造成货物损失。</div>\n<div class="doc-h2">4.2　应急工作职责</div>\n<div class="doc-p">驾驶员负责发现和报告货物异常、设置警示并实施现场处置；公司调度（应急管理办公室）负责联系转运车辆、通知货主；公司负责人负责决定货物处置方式。</div>\n<div class="doc-h2">4.3　处置步骤</div>\n<div class="doc-p">（1）发现货物散落、松动或者坠落，立即选择安全地点停车，开启危险报警闪光灯；</div>\n<div class="doc-p">（2）在来车方向按规定距离设置三角警告牌，人员撤离至安全位置；</div>\n<div class="doc-p">（3）能够现场整理的（如重新捆扎、归位），在确保安全的前提下组织整理；</div>\n<div class="doc-p">（4）货物散落影响道路通行的，及时报告交警和公司，组织清理并防止二次事故；</div>\n<div class="doc-p">（5）预计货物损失较大或者需要转运的，按公司指令就近安排转运车辆，同时通知货主；</div>\n<div class="doc-p">（6）全程记录货物损失情况、时间和处置措施，拍照留存；</div>\n<div class="doc-p">（7）涉及货损赔偿的，按运输合同约定和保险条款处理，不得擅自处置货物。</div>\n<div class="doc-h2">4.4　注意事项</div>\n<div class="doc-p">不得在车流中冒险捡拾货物；不得擅自改变货物堆放方式；货损严重的，及时向货主和公司报告，不得隐瞒。</div>\n<div class="doc-h1">5　人员伤亡现场处置方案</div>\n<div class="doc-h2">5.1　风险分析</div>\n<div class="doc-p">碰撞、侧翻、货物坠落、装卸作业等可能造成人员外伤、骨折、昏迷等伤害。</div>\n<div class="doc-h2">5.2　应急工作职责</div>\n<div class="doc-p">驾驶员（现场人员）负责拨打120、实施现场急救和报告公司；随车人员协助救护和引导救护车辆；公司应急管理办公室负责接报、报告、通知家属和协调就医。</div>\n<div class="doc-h2">5.3　处置步骤</div>\n<div class="doc-p">（1）立即拨打120，同时报告公司；</div>\n<div class="doc-p">（2）判断伤员意识和呼吸，保持呼吸道通畅；</div>\n<div class="doc-p">（3）外伤出血的，用无菌敷料或者干净布料加压包扎止血；</div>\n<div class="doc-p">（4）疑似骨折的，就地固定，不得随意搬动；</div>\n<div class="doc-p">（5）昏迷伤员取侧卧位，注意保暖；</div>\n<div class="doc-p">（6）协助120转运，登记伤员姓名、伤情和送往医院。</div>\n<div class="doc-h2">5.4　注意事项</div>\n<div class="doc-p">不得给昏迷伤员喂水喂药；不得强行拉拽伤员肢体；不得盲目施救。</div>\n<div class="doc-h1">6　办公场所火灾现场处置方案</div>\n<div class="doc-h2">6.1　风险分析</div>\n<div class="doc-p">办公场所电器线路老化、超负荷用电、吸烟或者违规使用明火可能引发火灾，造成人员伤亡和财产损失。</div>\n<div class="doc-h2">6.2　应急工作职责</div>\n<div class="doc-p">现场发现人负责呼喊报警、拨打119和初期扑救；公司负责人负责组织疏散和清点人数；安全管理员负责切断电源、引导消防车辆和报告。</div>\n<div class="doc-h2">6.3　处置步骤</div>\n<div class="doc-p">（1）发现火情立即呼喊报警，拨打119；</div>\n<div class="doc-p">（2）切断电源，使用灭火器扑救初起火灾；</div>\n<div class="doc-p">（3）组织人员沿疏散通道撤离至安全地带；</div>\n<div class="doc-p">（4）清点人数，报告公司；</div>\n<div class="doc-p">（5）引导消防车辆进入。</div>\n<div class="doc-h2">6.4　注意事项</div>\n<div class="doc-p">不得乘坐电梯；浓烟中低姿弯腰、湿毛巾捂住口鼻；火势较大时不得返回取物。</div>\n<div class="doc-h0">第四篇　附　件</div>\n<div class="doc-h1">附件1　企业基本情况及车辆清单</div>\n<div class="doc-p">**表A-1　企业基本情况表**</div>\n<div class="doc-p">**表A-2　运营车辆清单**</div>\n<div class="doc-h1">附件2　应急救援人员名单及联系方式</div>\n<div class="doc-p">总指挥：{{主要负责人}}（总经理）　{{值守电话}}</div>\n<div class="doc-p">副总指挥：{{安全管理员}}（安全管理员）　（按实际填写）</div>\n<div class="doc-p">成　员：{{车队长}}（车队长、{{监控员}}监控员）　{{值守电话}}</div>\n<div class="doc-p">驾驶员：（按实际填写）</div>\n<div class="doc-p">24小时应急值守电话：{{值守电话}}</div>\n<div class="doc-h1">附件3　义务消防员名单</div>\n<div class="doc-p">**表A-3　义务消防员名单**</div>\n<div class="doc-h1">附件4　应急物资装备名录及清单</div>\n<div class="doc-p">**表A-4　应急物资装备名录及清单**</div>\n<div class="doc-p">注：本清单按公司现有应急物资实际填报，由安全管理员每月检查一次；新购、报废或者更换的，及时更新清单并留存检查记录。</div>\n<div class="doc-h1">附件5　外部应急联动单位及电话</div>\n<div class="doc-p">**表A-5　外部应急联动电话**</div>\n<div class="doc-h1">附件6　生产安全事故信息报告表</div>\n<div class="doc-h1">附件7　启动应急响应命令（格式）</div>\n<div class="doc-h1">附件8　关键路线、标识和图纸</div>\n<div class="doc-p">一、关键路线。公司办公场所位于{{企业地址}}，运输业务以{{主要线路}}为主。外部救援力量至公司的行进路线见下列各图，公司应急车辆停放于办公场所门前指定车位。</div>\n<div class="doc-p">（图A-1　消防救援局至公司交通线路图，略）</div>\n<div class="doc-p">（图A-2　卫生院至公司交通线路图，略）</div>\n<div class="doc-p">（图A-3　疾控中心至公司交通线路图，略）</div>\n<div class="doc-p">二、应急标识。公司在办公场所和车辆设置下列应急标识：办公场所安全出口标识、疏散指示标识、灭火器存放点标识、应急物资存放点标识、配电箱警示标识；车辆设置反光标识、危险报警闪光灯，随车配备三角警告牌。安全管理员每月检查一次，标识损坏、污损的及时更换。</div>\n<div class="doc-p">三、图纸。公司办公场所平面布置及救援力量分布图（含办公室、停车位、灭火器、配电箱、疏散通道和安全出口位置）由公司按实际场地绘制，张贴于办公场所入口，并作为本预案附图归档。</div>',1,1,'v1.0 内置',1,0),
(4236,0,4001,0,'MEETING_MINUTES','安全生产会议记录（四段式）','会议','BOX3','安全生产月度会议（会议记录、会议PPT、签到、照片）',3,'','<div class="doc-h0">安全生产会议记录（四段式）</div><div class="doc-p">企业名称：<span class="fill">{{company_name}}</span>　归档年度：<span class="fill">{{year}}</span></div><div class="doc-h1">一、会议通知</div><div class="doc-p">会议时间/地点/内容/参会人员</div><table class="doc-tbl"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>签名</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><div class="doc-h1">二、会议签到表</div><div class="doc-p">序号/姓名/岗位/签名</div><table class="doc-tbl"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>签名</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><div class="doc-h1">三、会议记录</div><div class="doc-p">会议名称/地点/时间/主持人/记录人/议题/正文</div><table class="doc-tbl"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>签名</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><div class="doc-h1">四、会议照片</div><div class="doc-p">（附于表后）</div><table class="doc-tbl"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>签名</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><div class="doc-sign"><div>填表人（签字）：<span class="fill">{{person_name}}</span></div><div>日期：<span class="fill">{{sign_date}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4237,0,4001,0,'TRAIN_PLAN','安全生产教育培训计划','培训','BOX4','安全生产教育和培训计划',4,'','<div class="doc-h0">安全生产教育培训计划</div><div class="doc-p">企业名称：<span class="fill">{{company_name}}</span>　归档年度：<span class="fill">{{year}}</span></div><div class="doc-h1">一、年度培训计划表</div><div class="doc-p">按月度培训联动</div><table class="doc-tbl"><thead><tr><th>序号</th><th>培训类别</th><th>时间</th><th>培训内容</th><th>培训对象</th><th>学时</th><th>培训方式</th><th>培训人</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><div class="doc-sign"><div>填表人（签字）：<span class="fill">{{person_name}}</span></div><div>日期：<span class="fill">{{sign_date}}</span></div></div>',1,1,'v1.0 内置',1,0),
(4238,0,4001,0,'TRAIN_RECORD','安全生产月度培训记录','培训','BOX4','安全生产月度培训（培训内容、照片、签字）',4,'','<div class="doc-h0">安全生产月度培训记录</div><div class="doc-p">企业名称：<span class="fill">{{company_name}}</span>　归档年度：<span class="fill">{{year}}</span></div><div class="doc-h1">培训签到表</div><div class="doc-p">序号/姓名/岗位/签名</div><table class="doc-tbl"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>签名</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><div class="doc-h1">培训记录</div><div class="doc-p">项目/授课人/内容/考核结果</div><table class="doc-tbl"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>签名</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table><div class="doc-h1">培训照片</div><div class="doc-p">（附于表后）</div><table class="doc-tbl"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>签名</th></tr></thead><tbody><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></t