-- V10：台账范本库（用户提供的真实范本正文，来源：原型 sys_docs.js / 样例 / 台账合集）
-- 范本管理与电子档案柜共用本表 tpl_template，实现「改范本 → 生成台账同步变化」。
-- box_no / archive_item 是两模块同源映射键：档案柜归档项按 archive_item 精确匹配范本。

ALTER TABLE `tpl_template`
  ADD COLUMN `box_no` TINYINT NOT NULL DEFAULT 0 COMMENT '归属档案盒序号（对齐电子档案柜 BOX1~BOX11）',
  ADD COLUMN `archive_item` VARCHAR(160) NOT NULL DEFAULT '' COMMENT '对应档案柜归档项名称（生成时按此匹配范本）',
  ADD COLUMN `version_label` VARCHAR(60) NOT NULL DEFAULT '' COMMENT '版本说明（如 v1.0 内置 / 2026 修订版）';

CREATE INDEX `idx_tpl_template_box` ON `tpl_template` (`box_no`);
CREATE INDEX `idx_tpl_template_code` ON `tpl_template` (`tenant_id`, `code`);

DELETE FROM `tpl_template` WHERE `id` BETWEEN 4200 AND 4999;

-- 旧占位范本（4101 RESPONSIBILITY）由真实范本库替代，停用避免重复匹配
UPDATE `tpl_template` SET `status` = 0 WHERE `id` = 4101;